DG.put("rudr-avtaar/27",{"n":27,"title":"ਅਥ ਪਾਰਸ ਨਾਥ ਰੁਦ੍ਰ ਅਵਤਾਰ ਕਥਨੰ","title_roman":"Ath paaras naath rudr avtaar kathnan","page":862,"blocks":[{"type":"invocation","gurmukhi":"ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ","roman":"Ik Oankaar satigur prasaadi","meaning_en":"","page":862},{"type":"invocation","gurmukhi":"ਪਾਤਸ਼ਾਹੀ ੧੦","roman":"Paatshaahee 10","meaning_en":"","page":862},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":862},{"type":"verse","number":[1],"number_text":"੧।","page":862,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਦਤ ਰੁਦ੍ਰ ਅਵਤਾਰਾ। ਪੂਰਣ ਮਤ ਕੋ ਕੀਨ ਪਸਾਰਾ।","roman":"Ih bidhi dat rudr avtaaraa | pooran mat ko keen pasaaraa |","meaning_en":"","page":862},{"gurmukhi":"ਅੰਤਿ ਜੋਤਿ ਸੋ ਜੋਤਿ ਮਿਲਾਨੀ। ਜਿਹ ਬਿਧਿ ਸੋ ਪਾਰਬ੍ਰਹਮ ਭਵਾਨੀ। ੧।","roman":"Anti joti so joti milaanee | jih bidhi so paarbraham bhavaanee | 1 |","meaning_en":"","page":862}]},{"type":"verse","number":[2],"number_text":"੨।","page":862,"lines":[{"gurmukhi":"ਏਕ ਲਛ ਦਸ ਬਰਖ ਪ੍ਰਮਾਨਾ। ਪਾਛੇ ਚਲਾ ਜੋਗ ਕੋ ਬਾਨਾ।","roman":"Ek lachh das barakh pramaanaa | paachhe chalaa jog ko baanaa |","meaning_en":"","page":862},{"gurmukhi":"ਗ੍ਯਾਰਵ ਬਰਖ ਬਿਤੀਤਤ ਭਯੋ। ਪਾਰਸਨਾਥ ਪੁਰਖ ਭੂਅ ਵਯੋ। ੨।","roman":"Gyaarav barakh biteetat bhayo | paarasnaath purakh bhooa vayo | 2 |","meaning_en":"","page":862}]},{"type":"verse","number":[3],"number_text":"੩।","page":862,"lines":[{"gurmukhi":"ਰੋਹ ਦੇਸ ਸੁਭ ਦਿਨ ਭਲ ਥਾਨੁ। ਪਰਸ ਨਾਥ ਭਯੋ ਸੁਰ ਗ੍ਯਾਨੁ।","roman":"Roh des subh din bhal thaanu | paras naath bhayo sur gyaanu |","meaning_en":"","page":862},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਅਸਿ ਅਵਰ ਨ ਹੋਊ। ਚਕ੍ਰਤ ਰਹੇ ਮਾਤ ਪਿਤ ਦੋਊ। ੩।","roman":"Amit tej asi avar na ho'oo | chakrat rahe maat pit do'oo | 3 |","meaning_en":"","page":862}]},{"type":"verse","number":[4],"number_text":"੪।","page":863,"lines":[{"gurmukhi":"ਦਸਊ ਦਿਸਨਿ ਤੇਜ ਅਤਿ ਬਢਾ। ਦ੍ਵਾਦਸ ਭਾਨ ਏਕ ਹ੍ਵੈ ਚਢਾ।","roman":"Dasaoo disni tej ati badhaa | dvaadas bhaan ek hvai chadhaa |","meaning_en":"","page":863},{"gurmukhi":"ਦਹ ਦਿਹਸ ਲੋਕ ਉਠੇ ਅਕੁਲਾਈ। ਭੂਪਤਿ ਤੀਰ ਪੁਕਾਰੇ ਜਾਈ। ੪।","roman":"Dah dihas lok uthe akulaaee | bhoopti teer pukaare jaaee | 4 |","meaning_en":"","page":863}]},{"type":"verse","number":[5],"number_text":"੫।","page":863,"lines":[{"gurmukhi":"ਸੁਨੋ ਭੂਮ ਇਕ ਕਹੋ ਕਹਾਨੀ। ਏਕ ਪੁਰੁਖ ਉਪਜ੍ਯੋ ਅਭਿਮਾਨੀ।","roman":"Suno bhoom ik kaho kahaanee | ek purukh upjyo abhimaanee |","meaning_en":"","page":863},{"gurmukhi":"ਜਿਹ ਸਮ ਰੂਪ ਜਗਤ ਨਹੀ ਕੋਈ। ਏਕੈ ਘੜਾ ਬਿਧਾਤਾ ਸੋਈ। ੫।","roman":"Jih sam roop jagat nahee koee | ekai gharaa bidhaataa soee | 5 |","meaning_en":"","page":863}]},{"type":"verse","number":[6],"number_text":"੬।","page":863,"lines":[{"gurmukhi":"ਕੈ ਗੰਧ੍ਰਬ ਜਛ ਕੋਈ ਅਹਾ। ਜਾਨੁਕ ਦੂਸਰ ਭਾਨੁ ਚੜ ਰਹਾ।","roman":"Kai gandhrab jachh koee ahaa | jaanuk doosar bhaanu char rahaa |","meaning_en":"","page":863},{"gurmukhi":"ਅਤਿ ਜੋਬਨ ਝਮਕਤ ਤਿਹ ਅੰਗਾ। ਨਿਖਰਤ ਜਾ ਕੇ ਲਜਤ ਅਨੰਗਾ। ੬।","roman":"Ati joban jhamkat tih angaa | nikhrat jaa ke lajat anangaa | 6 |","meaning_en":"","page":863}]},{"type":"verse","number":[7],"number_text":"੭।","page":863,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਦੇਖਨ ਕਾਜ ਬੁਲਾਵਾ। ਪਹਿਲੇ ਦ੍ਯੋਸ ਸਾਥ ਚਲ ਆਵਾ।","roman":"Bhoopti dekhan kaaj bulaavaa | pahile dyos saath chal aavaa |","meaning_en":"","page":863},{"gurmukhi":"ਹਰਖ ਹ੍ਰਿਦੈ ਧਰ ਕੇ ਜਟਧਾਰੀ। ਜਾਨੁਕ ਦੁਤੀ ਦਤ ਅਵਤਾਰੀ। ੭।","roman":"Harakh hridai dhar ke jatdhaaree | jaanuk dutee dat avtaaree | 7 |","meaning_en":"","page":863}]},{"type":"verse","number":[8],"number_text":"੮।","page":863,"lines":[{"gurmukhi":"ਨਿਰਖ ਰੂਪ ਕਾਪੇ ਜਟਧਾਰੀ। ਯਹ ਕੋਊ ਭਯੋ ਪੁਰਖੁ ਅਵਤਾਰੀ।","roman":"Nirakh roop kaape jatdhaaree | yah ko'oo bhayo purkhu avtaaree |","meaning_en":"","page":863},{"gurmukhi":"ਯਹ ਮਤ ਦੂਰ ਹਮਾਰਾ ਕੈ ਹੈ। ਜਟਾਧਾਰ ਕੋਈ ਰਹੈ ਨ ਪੈ ਹੈ। ੮।","roman":"Yah mat door hamaaraa kai hai | jataadhaar koee rahai na pai hai | 8 |","meaning_en":"","page":863}]},{"type":"verse","number":[9],"number_text":"੯।","page":863,"lines":[{"gurmukhi":"ਤੇਜ ਪ੍ਰਭਾਵ ਨਿਰਖਿ ਤਬ ਰਾਜਾ। ਅਤਿ ਪ੍ਰਸੰਨਿ ਪੁਲਕਤ ਚਿਤ ਗਾਜਾ।","roman":"Tej prabhaav nirkhi tab raajaa | ati prasanni pulkat chit gaajaa |","meaning_en":"","page":863},{"gurmukhi":"ਜਿਹ ਜਿਹਾ ਲਖਾ ਰਹੇ ਬਿਸਮਾਈ। ਜਾਨੁਕ ਰੰਕ ਨਵੋ ਨਿਧ ਪਾਈ। ੯।","roman":"Jih jihaa lakhaa rahe bismaaee | jaanuk rank navo nidh paaee | 9 |","meaning_en":"","page":863}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":863,"lines":[{"gurmukhi":"ਮੋਹਨ ਜਾਲ ਸਭਨ ਸਿਰ ਡਾਰਾ। ਚੇਟਕ ਬਾਨ ਚਕ੍ਰਿਤ ਹ੍ਵੈ ਮਾਰਾ।","roman":"Mohan jaal sabhan sir daaraa | chetak baan chakrit hvai maaraa |","meaning_en":"","page":863},{"gurmukhi":"ਜਹ ਤਹ ਮੋਹਿ ਸਕਲ ਨਰ ਗਿਰੇ। ਜਾਨ ਸੁਭਟ ਸਾਮੁਹਿ ਰਣ ਭਿਰੇ। ੧੦।","roman":"Jah tah mohi sakal nar gire | jaan subhat saamuhi ran bhire | 10 |","meaning_en":"","page":863}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":863,"lines":[{"gurmukhi":"ਨਰ ਨਾਰੀ ਜਿਹ ਜਿਹ ਤਿਹ ਪੇਖਾ। ਤਿਹ ਤਿਹ ਮਦਨ ਰੂਪ ਅਵਿਰੇਖਾ।","roman":"Nar naaree jih jih tih pekhaa | tih tih madan roop avirekhaa |","meaning_en":"","page":863},{"gurmukhi":"ਸਾਧਨ ਸਰਬ ਸਿਧਿ ਕਰ ਜਾਨਾ। ਜੋਗਨ ਜੋਗ ਰੂਪ ਅਨੁਮਾਨਾ। ੧੧।","roman":"Saadhan sarab sidhi kar jaanaa | jogan jog roop anumaanaa | 11 |","meaning_en":"","page":863}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":863,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਰੂਪ ਰਨਵਾਸ ਲੁਭਾਨਾ। ਦੇ ਤਿਹ ਸੁਤਾ ਨ੍ਰਿਪਤਿ ਮਨਿ ਮਾਨਾ।","roman":"Nirkhi roop ranvaas lubhaanaa | de tih sutaa nripti mani maanaa |","meaning_en":"","page":863},{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਭਯੋ ਜਬੈ ਜਾਮਾਤਾ। ਮਹਾ ਧਨੁਖਧਰ ਬੀਰ ਬਿਖ੍ਯਾਤਾ। ੧੨।","roman":"Nrip ko bhayo jabai jaamaataa | mahaa dhanukhdhar beer bikhyaataa | 12 |","meaning_en":"","page":863}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":863,"lines":[{"gurmukhi":"ਮਹਾ ਰੂਪ ਅਰੁ ਅਮਿਤ ਪ੍ਰਤਾਪੂ। ਜਾਨੁ ਜਪੈ ਹੈ ਆਪਨ ਜਾਪੂ।","roman":"Mahaa roop aru amit prataapoo | jaanu japai hai aapan jaapoo |","meaning_en":"","page":863},{"gurmukhi":"ਸਸਤ੍ਰ ਸਾਸਤ੍ਰ ਬੇਤਾ ਸੁਰਿ ਗ੍ਯਾਨਾ। ਜਾ ਸਮ ਪੰਡਿਤ ਜਗਤਿ ਨ ਆਨਾ। ੧੩।","roman":"Sasatr saasatr betaa suri gyaanaa | jaa sam pandit jagti na aanaa | 13 |","meaning_en":"","page":863}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":864,"lines":[{"gurmukhi":"ਥੋਰਿ ਬਹਿਕ੍ਰਮ ਬੁਧਿ ਬਿਸੇਖਾ। ਜਾਨੁਕ ਧਰਾ ਬਿਤਨ ਯਹਿ ਭੇਖਾ।","roman":"Thori bahikram budhi bisekhaa | jaanuk dharaa bitan yahi bhekhaa |","meaning_en":"","page":864},{"gurmukhi":"ਜਿਹ ਜਿਹ ਰੂਪ ਤਵਨ ਕਾ ਲਹਾ। ਸੋ ਸੋ ਚਮਕ ਚਕ੍ਰਿ ਹੁਐ ਰਹਾ। ੧੪।","roman":"Jih jih roop tavan kaa lahaa | so so chamak chakri huai rahaa | 14 |","meaning_en":"","page":864}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":864},{"type":"verse","number":[15],"number_text":"੧੫।","page":864,"lines":[{"gurmukhi":"ਮਾਨ ਭਰੇ ਸਰ ਸਾਨ ਧਰੇ ਮਠ ਸਾਨ ਚੜੇ ਅਸਿ ਸ੍ਰੋਣਤਿ ਸਾਏ।","roman":"Maan bhare sar saan dhare math saan chare asi sronti saae |","meaning_en":"","page":864},{"gurmukhi":"ਲੇਤ ਹਰੇ ਜਿਹ ਡੀਠ ਪਰੇ ਨਹੀ ਫੇਰਿ ਫਿਰੇ ਗ੍ਰਿਹ ਜਾਨ ਨ ਪਾਏ।","roman":"Let hare jih deeth pare nahee pheri phire grih jaan na paae |","meaning_en":"","page":864},{"gurmukhi":"ਝੀਮ ਝਰੇ ਜਨ ਸੇਲ ਹਰੇ ਇਹ ਭਾਤਿ ਗਿਰੇ ਜਨੁ ਦੇਖਨ ਆਏ।","roman":"Jheem jhare jan sel hare ih bhaati gire janu dekhan aae |","meaning_en":"","page":864},{"gurmukhi":"ਜਾਸੁ ਹਿਰੇ ਸੋਊ ਮੈਨ ਘਿਰੇ ਗਿਰ ਭੂਮਿ ਪਰੇ ਨ ਉਠੰਤ ਉਠਾਏ। ੧੫।","roman":"Jaasu hire so'oo main ghire gir bhoomi pare na uthant uthaae | 15 |","meaning_en":"","page":864}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":864,"lines":[{"gurmukhi":"ਸੋਭਤ ਜਾਨੁ ਸੁਧਾਸਰ ਸੁੰਦਰ ਕਾਮ ਕੇ ਮਾਨਹੁ ਕੂਪ ਸੁ ਧਾਰੇ।","roman":"Sobhat jaanu sudhaasar sundar kaam ke maanhu koop su dhaare |","meaning_en":"","page":864},{"gurmukhi":"ਲਾਜਿ ਕੇ ਜਾਨ ਜਹਾਜ ਬਿਰਾਜਤ ਹੇਰਤ ਹੀ ਹਰ ਲੇਤ ਹਕਾਰੇ।","roman":"Laaji ke jaan jahaaj biraajat herat hee har let hakaare |","meaning_en":"","page":864},{"gurmukhi":"ਹਉ ਚਹੁ ਕੁੰਟ ਭ੍ਰਮ੍ਯੋ ਖਗ ਜ੍ਯੋਂ ਇਨ ਕੇ ਸਮ ਰੂਪ ਨ ਨੈਕੁ ਨਿਹਾਰੇ।","roman":"Hau chahu kunt bhramyo khag jyon in ke sam roop na naiku nihaare |","meaning_en":"","page":864},{"gurmukhi":"ਪਾਰਥ ਬਾਨ ਕਿ ਜੁਬਨ ਖਾਨ ਕਿ ਕਾਲ ਕ੍ਰਿਪਾਨ ਕਿ ਕਾਮ ਕਟਾਰੇ। ੧੬।","roman":"Paarath baan ki juban khaan ki kaal kripaan ki kaam kataare | 16 |","meaning_en":"","page":864}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":864,"lines":[{"gurmukhi":"ਤੰਤ੍ਰ ਭਰੇ ਕਿਧੌ ਜੰਤ੍ਰ ਜਰੇ ਅਰ ਮੰਤ੍ਰ ਹਰੇ ਚਖ ਚੀਨਤ ਯਾ ਤੇ।","roman":"Tantr bhare kidhau jantr jare ar mantr hare chakh cheenat yaa te |","meaning_en":"","page":864},{"gurmukhi":"ਜੋਬਨ ਜੋਤਿ ਜਗੇ ਅਤਿ ਸੁੰਦਰ ਰੰਗ ਰੰਗੇ ਮਦ ਸੇ ਮਦੂਆ ਤੇ।","roman":"Joban joti jage ati sundar rang range mad se madooaa te |","meaning_en":"","page":864},{"gurmukhi":"ਰੰਗ ਸਹਾਬ ਫੂਲ ਗੁਲਾਬ ਸੇ ਸੀਖੇ ਹੈ ਜੋਰਿ ਕਰੋਰਕ ਘਾਤੇ।","roman":"Rang sahaab phool gulaab se seekhe hai jori karorak ghaate |","meaning_en":"","page":864},{"gurmukhi":"ਮਾਧੁਰੀ ਮੂਰਤਿ ਸੁੰਦਰ ਸੂਰਤਿ ਹੇਰਤਿ ਹੀ ਹਰ ਲੇਤ ਹੀਯਾ ਤੇ। ੧੭।","roman":"Maadhuree moorti sundar soorti herti hee har let heeyaa te | 17 |","meaning_en":"","page":864}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":864,"lines":[{"gurmukhi":"ਪਾਨ ਚਬਾਇ ਸੀਗਾਰ ਬਨਾਇ। ਸੁਗੰਧ ਲਗਾਇ ਸਭਾ ਜਬ ਆਵੈ।","roman":"Paan chabaai seegaar banaai | sugandh lagaai sabhaa jab aavai |","meaning_en":"","page":864},{"gurmukhi":"ਕਿਨਰ ਜਛ ਭੁਜੰਗ ਚਰਾਚਰ ਦੇਵ ਅਦੇਵ ਦੋਊ ਬਿਸਮਾਵੈ।","roman":"Kinar jachh bhujang charaachar dev adev do'oo bismaavai |","meaning_en":"","page":864},{"gurmukhi":"ਮੋਹਿਤ ਜੇ ਮਹਿ ਲੋਗਨ ਮਾਨਨਿ ਮੋਹਤ ਤਉਨ ਮਹਾ ਸੁਖ ਪਾਵੈ।","roman":"Mohit je mahi logan maanni mohat taun mahaa sukh paavai |","meaning_en":"","page":864},{"gurmukhi":"ਵਾਰਹਿ ਹੀਰ ਅਮੋਲਕ ਚੀਰ ਤ੍ਰੀਯਾ ਬਿਨ ਧੀਰ ਸਬੈ ਬਲ ਜਾਵੈ। ੧੮।","roman":"Vaarhi heer amolak cheer treeyaa bin dheer sabai bal jaavai | 18 |","meaning_en":"","page":864}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":864,"lines":[{"gurmukhi":"ਰੂਪ ਅਪਾਰ ਪੜੇ ਦਸ ਚਾਰ ਮਨੋ ਅਸੁਰਾਰਿ ਚਤੁਰ ਚਕ ਜਾਨ੍ਯੋ।","roman":"Roop apaar pare das chaar mano asuraari chatur chak jaanyo |","meaning_en":"","page":864},{"gurmukhi":"ਆਹਵ ਜੁਕਤਿ ਜਿਤੀਕ ਹੁਤੀ ਜਗ ਸਰਬਨ ਮੈ ਸਬ ਹੀ ਅਨੁਮਾਨ੍ਯੋ।","roman":"Aahav jukti jiteek hutee jag sarban mai sab hee anumaanyo |","meaning_en":"","page":864},{"gurmukhi":"ਦੇਸਿ ਬਿਦੇਸਨ ਜੀਤ ਜੁਧਾਂਬਰ ਕ੍ਰਿਤ ਚੰਦੋਵ ਦਸੋ ਦਿਸ ਤਾਨ੍ਯੋ।","roman":"Desi bidesan jeet judhaanbar krit chandov daso dis taanyo |","meaning_en":"","page":864},{"gurmukhi":"ਦੇਵਨ ਇੰਦ੍ਰ ਗੋਪੀਨ ਗੋਬਿੰਦ ਨਿਸਾ ਕਰਿ ਚੰਦ ਸਮਾਨ ਪਛਾਨ੍ਯੋ। ੧੯।","roman":"Devan indr gopeen gobind nisaa kari chand samaan pachhaanyo | 19 |","meaning_en":"","page":864}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":865,"lines":[{"gurmukhi":"ਚਉਧਿਤ ਚਾਰ ਦਿਸਾ ਭਈ ਚਕ੍ਰਤ ਭੂਮਿ ਅਕਾਸ ਦੁਹੂੰ ਪਹਿਚਾਨਾ।","roman":"Chaudhit chaar disaa bhaee chakrat bhoomi akaas duhoon pahichaanaa |","meaning_en":"","page":865},{"gurmukhi":"ਜੁਧ ਸਮਾਨ ਲਖ੍ਯੋ ਜਗ ਜੋਧਨ ਬੋਧਨ ਬੋਧ ਮਹਾ ਅਨੁਮਾਨਾ।","roman":"Judh samaan lakhyo jag jodhan bodhan bodh mahaa anumaanaa |","meaning_en":"","page":865},{"gurmukhi":"ਸੂਰ ਸਮਾਨ ਲਖਾ ਦਿਨ ਕੈ ਤਿਹ ਚੰਦ ਸਰੂਪ ਨਿਸਾ ਪਹਿਚਾਨਾ।","roman":"Soor samaan lakhaa din kai tih chand saroop nisaa pahichaanaa |","meaning_en":"","page":865},{"gurmukhi":"ਰਾਨਨਿ ਰਾਵਿ ਸਵਾਨਿਨ ਸਾਵ ਭਵਾਨਿਨ ਭਾਵ ਭਲੋ ਮਨਿ ਮਾਨਾ। ੨੦।","roman":"Raanni raavi savaanin saav bhavaanin bhaav bhalo mani maanaa | 20 |","meaning_en":"","page":865}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"","page":865},{"type":"verse","number":[21],"number_text":"੨੧।","page":865,"lines":[{"gurmukhi":"ਬਿਤੈ ਬਰਖ ਦ੍ਵੈ ਅਸਟ ਮਾਸੰ ਪ੍ਰਮਾਨੰ। ਭਯੋ ਸੁਪ੍ਰਭੰ ਸਰਬ ਬਿਦ੍ਯਾ ਨਿਧਾਨੰ।","roman":"Bitai barakh dvai asat maasan pramaanan | bhayo suprabhan sarab bidyaa nidhaanan |","meaning_en":"","page":865},{"gurmukhi":"ਜਪੈ ਹਿੰਗੁਲਾ ਠਿੰਗੁਲਾ ਪਾਣ ਦੇਵੀ। ਅਨਾਸਾ ਛੁਧਾ ਅਤ੍ਰਧਾਰੀ ਅਭੇਵੀ। ੨੧।","roman":"Japai hingulaa thingulaa paan devee | anaasaa chhudhaa atradhaaree abhevee | 21 |","meaning_en":"","page":865}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":865,"lines":[{"gurmukhi":"ਜਪੈ ਤੋਤਲਾ ਸੀਤਲਾ ਖਗ ਤਾਨੀ। ਭ੍ਰਮਾ ਭੈਹਰੀ ਭੀਮ ਰੂਪਾ ਭਵਾਣੀ।","roman":"Japai totlaa seetlaa khag taanee | bhramaa bhaihree bheem roopaa bhavaanee |","meaning_en":"","page":865},{"gurmukhi":"ਚਲਾਚਲ ਸਿੰਘ ਝਮਾਝੰਮ ਅਤ੍ਰੰ। ਹਹਾ ਹੂਹਿ ਹਾਸੰ ਝਲਾ ਝਲ ਛਤ੍ਰੰ। ੨੨।","roman":"Chalaachal singh jhamaajhanm atran | hahaa hoohi haasan jhalaa jhal chhatran | 22 |","meaning_en":"","page":865,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":865,"lines":[{"gurmukhi":"ਅਟਾ ਅਟ ਹਾਸੰ ਛਟਾ ਛੁਟ ਕੇਸੰ। ਅਸੰ ਓਧ ਪਾਣੰ ਨਮੋ ਕ੍ਰੂਰ ਭੇਸੰ।","roman":"Ataa at haasan chhataa chhut kesan | asan odh paanan namo kroor bhesan |","meaning_en":"","page":865,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਸਿਰੰਮਾਲ ਸ੍ਵਛੰ ਲਸੈ ਦੰਤ ਪੰਤੰ। ਭਜੈ ਸਤ੍ਰੂ ਗੂੜੰ ਪ੍ਰਫੁਲੰਤ ਸੰਤੰ। ੨੩।","roman":"Siranmaal svachhan lasai dant pantan | bhajai satroo gooran praphulant santan | 23 |","meaning_en":"","page":865}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":865,"lines":[{"gurmukhi":"ਅਲਿੰਪਾਤਿ ਅਰਧੀ ਮਹਾ ਰੂਪ ਰਾਜੈ। ਮਹਾ ਜੋਤ ਜ੍ਵਾਲੰ ਕਰਾਲੰ ਬਿਰਾਜੈ।","roman":"Alinpaati ardhee mahaa roop raajai | mahaa jot jvaalan karaalan biraajai |","meaning_en":"","page":865},{"gurmukhi":"ਤ੍ਰਸੈ ਦੁਸਟ ਪੁਸਟੰ ਹਸੈ ਸੁਧ ਸਾਧੰ। ਭਜੈ ਪਾਨ ਦੁਰਗਾ ਅਰੂਪੀ ਅਗਾਧੰ। ੨੪।","roman":"Trasai dusat pustan hasai sudh saadhan | bhajai paan durgaa aroopee agaadhan | 24 |","meaning_en":"","page":865}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":865,"lines":[{"gurmukhi":"ਸੁਨੇ ਉਸਤਤੀ ਭੀ ਭਵਾਨੀ ਕ੍ਰਿਪਾਲੰ। ਅਧੰ ਉਰਧਵੀ ਆਪ ਰੂਪੀ ਰਸਾਲੰ।","roman":"Sune usattee bhee bhavaanee kripaalan | adhan uradhvee aap roopee rasaalan |","meaning_en":"","page":865},{"gurmukhi":"ਦਏ ਇਖ੍ਵਧੀ ਦ੍ਵੈ ਅਭੰਗੰ ਖਤੰਗੰ। ਪਰਸ੍ਯੰ ਧਰੰ ਜਾਨ ਲੋਹੰ ਸੁਰੰਗੰ। ੨੫।","roman":"Dae ikhvadhee dvai abhangan khatangan | parsyan dharan jaan lohan surangan | 25 |","meaning_en":"","page":865}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":865,"lines":[{"gurmukhi":"ਜਬੈ ਸਸਤ੍ਰ ਸਾਧੀ ਸਬੈ ਸਸਤ੍ਰ ਪਾਏ। ਉਘਾਰੇ ਚੂਮੇ ਕੰਠ ਸੀਸੰ ਛੁਹਾਏ।","roman":"Jabai sasatr saadhee sabai sasatr paae | ughaare choome kanth seesan chhuhaae |","meaning_en":"","page":865},{"gurmukhi":"ਲਖ੍ਯੋ ਸਰਬ ਰਾਵੰ ਪ੍ਰਭਾਵੰ ਅਪਾਰੰ। ਅਜੋਨੀ ਅਜੈ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ। ੨੬।","roman":"Lakhyo sarab raavan prabhaavan apaaran | ajonee ajai bed bidiaa bichaaran | 26 |","meaning_en":"","page":865}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":866,"lines":[{"gurmukhi":"ਗ੍ਰਿਹੀਤੁਆ ਜਬੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰੰ ਅਪਾਰੰ। ਪੜੇ ਅਨੁਭਵੰ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ।","roman":"Griheetuaa jabai sasatr astran apaaran | pare anubhvan bed bidiaa bichaaran |","meaning_en":"","page":866},{"gurmukhi":"ਪੜੇ ਸਰਬ ਬਿਦਿਆ ਹੁਤੀ ਸਰਬ ਦੇਸੰ। ਜਿਤੇ ਸਰਬ ਦੇਸੀ ਸੁ ਅਸਤ੍ਰੁੰ ਨਰੇਸੰ। ੨੭।","roman":"Pare sarab bidiaa hutee sarab desan | jite sarab desee su astrun naresan | 27 |","meaning_en":"","page":866}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":866,"lines":[{"gurmukhi":"ਪਠੇ ਕਾਗਦੰ ਦੇਸ ਦੇਸੰ ਆਪਰੀ। ਕਰੋ ਆਨਿ ਕੈ ਬੇਦ ਬਿਦ੍ਯਾ ਬਿਚਾਰੀ।","roman":"Pathe kaagdan des desan aapree | karo aani kai bed bidyaa bichaaree |","meaning_en":"","page":866},{"gurmukhi":"ਜਟੇ ਦੰਡ ਮੁੰਡੀ ਤਪੀ ਬ੍ਰਹਮਚਾਰੀ। ਸਧੀ ਸ੍ਰਾਵਗੀ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੀ। ੨੮।","roman":"Jate dand mundee tapee brahamchaaree | sadhee sraavgee bed bidiaa bichaaree | 28 |","meaning_en":"","page":866}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":866,"lines":[{"gurmukhi":"ਹਕਾਰੇ ਸਬੈ ਦੇਸ ਦੇਸਾ ਨਰੇਸੰ। ਬੁਲਾਏ ਸਬੈ ਮੋਨ ਮਾਨੀ ਸੁ ਬੇਸੰ।","roman":"Hakaare sabai des desaa naresan | bulaae sabai mon maanee su besan |","meaning_en":"","page":866},{"gurmukhi":"ਜਟਾ ਧਾਰ ਜੇਤੇ ਕਹੂੰ ਦੇਖ ਪਈਯੈ। ਬੁਲਾਵੈ ਤਿਸੈ ਨਾਥ ਭਾਖੈ ਬੁਲਈਯੈ। ੨੯।","roman":"Jataa dhaar jete kahoon dekh paeeyai | bulaavai tisai naath bhaakhai bulaeeyai | 29 |","meaning_en":"","page":866}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":866,"lines":[{"gurmukhi":"ਫਿਰੇ ਸਰਬ ਦੇਸੰ ਨਰੇਸੰ ਬੁਲਾਵੈ। ਮਿਲੇ ਨ ਤਿਸੈ ਛਤ੍ਰ ਛੈਣੀ ਛਿਨਾਵੈ।","roman":"Phire sarab desan naresan bulaavai | mile na tisai chhatr chhainee chhinaavai |","meaning_en":"","page":866},{"gurmukhi":"ਪਠੇ ਪਤ੍ਰ ਏਕੈ ਦਿਸਾ ਏਕ ਧਾਵੈ। ਜਟੀ ਦੰਡ ਮੁੰਡੀ ਕਹੂੰ ਹਾਥ ਆਵੈ। ੩੦।","roman":"Pathe patr ekai disaa ek dhaavai | jatee dand mundee kahoon haath aavai | 30 |","meaning_en":"","page":866}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":866,"lines":[{"gurmukhi":"ਰਚ੍ਯੋ ਜਗ ਰਾਜਾ ਚਲੇ ਸਰਬ ਜੋਗੀ। ਜਹਾ ਲਉ ਕੋਈ ਬੂਢ ਬਾਰੋ ਸਭੋਗੀ।","roman":"Rachyo jag raajaa chale sarab jogee | jahaa lau koee boodh baaro sabhogee |","meaning_en":"","page":866},{"gurmukhi":"ਕਹਾ ਰੰਕ ਰਾਜਾ ਕਹਾ ਨਾਰ ਹੋਈ। ਰਚ੍ਯੋ ਜਗ ਰਾਜਾ ਚਲਿਓ ਸਰਬ ਕੋਈ। ੩੧।","roman":"Kahaa rank raajaa kahaa naar hoee | rachyo jag raajaa chalio sarab koee | 31 |","meaning_en":"","page":866}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":866,"lines":[{"gurmukhi":"ਫਿਰੇ ਪਤ੍ਰ ਸਰਬਤ੍ਰ ਦੇਸੰ ਅਪਾਰੰ। ਜੁਰੇ ਸਰਬ ਰਾਜਾ ਨ੍ਰਿਪੰ ਆਨਿ ਦੁਆਰੰ।","roman":"Phire patr sarbatr desan apaaran | jure sarab raajaa nripan aani duaaran |","meaning_en":"","page":866},{"gurmukhi":"ਜਹਾ ਲੌ ਹੁਤੇ ਜਗਤ ਮੈ ਜਟਾਧਾਰੀ। ਮਿਲੈ ਰੋਹ ਦੇਸੰ ਭਏ ਭੇਖ ਭਾਰੀ। ੩੨।","roman":"Jahaa lau hute jagat mai jataadhaaree | milai roh desan bhae bhekh bhaaree | 32 |","meaning_en":"","page":866}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":866,"lines":[{"gurmukhi":"ਜਹਾ ਲਉ ਹੁਤੇ ਜੋਗ ਜੋਗਿਸਟ ਸਾਧੇ। ਮਲੇ ਮੁਖ ਬਿਭੂਤੰ ਸੁ ਲੰਗੋਟ ਬਾਧੇ।","roman":"Jahaa lau hute jog jogisat saadhe | male mukh bibhootan su langot baadhe |","meaning_en":"","page":866},{"gurmukhi":"ਜਟਾ ਸੀਸ ਧਾਰੇ ਨਿਹਾਰੇ ਅਪਾਰੰ। ਮਹਾ ਜੋਗ ਧਾਰੰ ਸੁਬਿਦਿਆ ਬਿਚਾਰੰ। ੩੩।","roman":"Jataa sees dhaare nihaare apaaran | mahaa jog dhaaran subidiaa bichaaran | 33 |","meaning_en":"","page":866}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":866,"lines":[{"gurmukhi":"ਜਿਤੇ ਸਰਬ ਭੂਪੰ ਬੁਲੇ ਸਰਬ ਰਾਜਾ। ਚਹੂੰ ਚਕ ਮੋ ਦਾਨ ਨੀਸਾਨ ਬਾਜਾ।","roman":"Jite sarab bhoopan bule sarab raajaa | chahoon chak mo daan neesaan baajaa |","meaning_en":"","page":866},{"gurmukhi":"ਮਿਲੇ ਦੇਸ ਦੇਸਾਨ ਅਨੇਕ ਮੰਤ੍ਰੀ। ਕਰੈ ਸਾਧਨਾ ਜੋਗ ਬਾਜੰਤ੍ਰ ਤੰਤ੍ਰੀ। ੩੪।","roman":"Mile des desaan anek mantree | karai saadhnaa jog baajantr tantree | 34 |","meaning_en":"","page":866}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":866,"lines":[{"gurmukhi":"ਜਿਤੇ ਸਰਬ ਭੂਮਿ ਸਥਲੀ ਸੰਤ ਆਹੇ। ਤਿਤੇ ਸਰਬ ਪਾਰਸ ਨਾਥੰ ਬੁਲਾਏ।","roman":"Jite sarab bhoomi sathlee sant aahe | tite sarab paaras naathan bulaae |","meaning_en":"","page":866},{"gurmukhi":"ਦਏ ਭਾਤਿ ਅਨੇਕ ਭੋਜ ਅਰਘ ਦਾਨੰ। ਲਜੀ ਪੇਖ ਦੇਵਿ ਸਥਲੀ ਮੋਨ ਮਾਨੰ। ੩੫।","roman":"Dae bhaati anek bhoj aragh daanan | lajee pekh devi sathlee mon maanan | 35 |","meaning_en":"","page":866}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":866,"lines":[{"gurmukhi":"ਕਰੈ ਬੈਠ ਕੇ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ। ਪ੍ਰਕਾਸੋ ਸਬੈ ਆਪੁ ਆਪੰ ਪ੍ਰਕਾਰੰ।","roman":"Karai baith ke bed bidiaa bichaaran | prakaaso sabai aapu aapan prakaaran |","meaning_en":"","page":866},{"gurmukhi":"ਟਕੰ ਟਕ ਲਾਗੀ ਮੁਖੰ ਮੁਖਿ ਪੇਖਿਓ। ਸੁਨ੍ਯੋ ਕਾਨ ਹੋ ਤੋ ਸੁ ਤੋ ਆਖਿ ਦੇਖਿਓ। ੩੬।","roman":"Takan tak laagee mukhan mukhi pekhio | sunyo kaan ho to su to aakhi dekhio | 36 |","meaning_en":"","page":866}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":867,"lines":[{"gurmukhi":"ਪ੍ਰਕਾਸੋ ਸਬੈ ਆਪ ਆਪੰ ਪੁਰਾਣੰ। ਰੜੋ ਦੇਸਿ ਦੇਸਾਣ ਬਿਦਿਆ ਮੁਹਾਣੰ।","roman":"Prakaaso sabai aap aapan puraanan | raro desi desaan bidiaa muhaanan |","meaning_en":"","page":867},{"gurmukhi":"ਕਰੋ ਭਾਤਿ ਭਾਤੰ ਸੁ ਬਿਦਿਆ ਬਿਚਾਰੰ। ਨ੍ਰਿਭੈ ਚਿਤ ਦੈ ਕੈ ਮਹਾ ਤ੍ਰਾਸ ਟਾਰੰ। ੩੭।","roman":"Karo bhaati bhaatan su bidiaa bichaaran | nribhai chit dai kai mahaa traas taaran | 37 |","meaning_en":"","page":867}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":867,"lines":[{"gurmukhi":"ਜੁਰੇ ਬੰਗਸੀ ਰਾਫਿਜੀ ਰੋਹਿ ਰੂਮੀ। ਚਲੇ ਬਾਲਖੀ ਛਾਡ ਕੈ ਰਾਜ ਭੂਮੀ।","roman":"Jure bangsee raaphijee rohi roomee | chale baalkhee chhaad kai raaj bhoomee |","meaning_en":"","page":867},{"gurmukhi":"ਨ੍ਰਿਭੈ ਭਿੰਭਰੀ ਕਾਸਮੀਰੀ ਕੰਧਾਰੀ। ਕਿ ਕੈ ਕਾਲਮਾਖੀ ਕਸੇ ਕਾਸਕਾਰੀ। ੩੮।","roman":"Nribhai bhinbhree kaasmeeree kandhaaree | ki kai kaalmaakhee kase kaaskaaree | 38 |","meaning_en":"","page":867}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":867,"lines":[{"gurmukhi":"ਜੁਰੇ ਦਛਣੀ ਸਸਤ੍ਰ ਬੇਤਾ ਅਰਯਾਰੇ। ਦ੍ਰੁਜੈ ਦ੍ਰਾਵੜੀ ਤਪਤ ਤਈਲੰਗ ਵਾਰੇ।","roman":"Jure dachhnee sasatr betaa aryaare | drujai draavree tapat taeelang vaare |","meaning_en":"","page":867},{"gurmukhi":"ਪਰੰ ਪੂਰਬੀ ਉਤ੍ਰ ਦੇਸੀ ਅਪਾਰੰ। ਮਿਲੇ ਦੇਸ ਦੇਸੇਣ ਜੋਧਾ ਜੁਝਾਰੰ। ੩੯।","roman":"Paran poorbee utr desee apaaran | mile des desen jodhaa jujhaaran | 39 |","meaning_en":"","page":867}]},{"type":"heading","kind":"chhand","name":"ਪਾਧਰੀ ਛੰਦ","gurmukhi":"ਪਾਧਰੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"","page":867},{"type":"verse","number":[40],"number_text":"੪੦।","page":867,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੀਰ ਬਹੁ ਬੀਰ ਜੋਰਿ। ਮਤ ਦੇਸ ਦੇਸ ਰਾਜਾ ਕਰੋਰ।","roman":"Ih bhaati beer bahu beer jori | mat des des raajaa karor |","meaning_en":"","page":867},{"gurmukhi":"ਦੇ ਹੀਰ ਚੀਰ ਬਹੁ ਦਿਰਬ ਸਾਜ। ਸਨਮਾਨ ਦਾਨ ਬਹੁ ਭਾਤਿ ਰਾਜ। ੪੦।","roman":"De heer cheer bahu dirab saaj | sanmaan daan bahu bhaati raaj | 40 |","meaning_en":"","page":867}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":867,"lines":[{"gurmukhi":"ਅਨਭੈ ਅਭੰਗ ਅਵਧੂਤ ਛਤ੍ਰ। ਅਨਜੀਤ ਜੁਧ ਬੇਤਾ ਅਤਿ ਅਤ੍ਰ।","roman":"Anbhai abhang avdhoot chhatr | anjeet judh betaa ati atr |","meaning_en":"","page":867},{"gurmukhi":"ਅਨਗੰਜ ਸੂਰ ਅਬਿਚਲ ਜੁਝਾਰ। ਰਣ ਰੰਗ ਅਭੰਗ ਜਿਤੇ ਹਜਾਰ। ੪੧।","roman":"Anganj soor abichal jujhaar | ran rang abhang jite hajaar | 41 |","meaning_en":"","page":867}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":867,"lines":[{"gurmukhi":"ਸਬ ਦੇਸ ਦੇਸ ਕੇ ਜੀਤ ਰਾਵ। ਕਰ ਕ੍ਰੁਧ ਜੁਧ ਨਾਨਾ ਉਪਾਵ।","roman":"Sab des des ke jeet raav | kar krudh judh naanaa upaav |","meaning_en":"","page":867},{"gurmukhi":"ਕੈ ਸਾਮ ਦਾਮ ਅਰੁ ਦੰਡ ਭੇਦ। ਅਵਨੀਪ ਸਰਬ ਜੋਰੇ ਅਛੇਦ। ੪੨।","roman":"Kai saam daam aru dand bhed | avneep sarab jore achhed | 42 |","meaning_en":"","page":867}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":867,"lines":[{"gurmukhi":"ਜਬ ਸਰਬ ਭੂਪ ਜੋਰੇ ਮਹਾਨ। ਜੈ ਜੀਤ ਪਤ੍ਰ ਦਿਨੋ ਨਿਸਾਨ।","roman":"Jab sarab bhoop jore mahaan | jai jeet patr dino nisaan |","meaning_en":"","page":867},{"gurmukhi":"ਦੈ ਹੀਰ ਚੀਰ ਅਨਭੰਗ ਦਿਰਬ। ਮਹਿਪਾਲ ਮੋਹਿ ਡਾਰੇ ਸੁ ਸਰਬ। ੪੩।","roman":"Dai heer cheer anbhang dirab | mahipaal mohi daare su sarab | 43 |","meaning_en":"","page":867}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":867,"lines":[{"gurmukhi":"ਇਕ ਦਯੋ੍ਸ ਬੀਤ ਪਾਰਸ੍ਵ ਰਾਇ। ਉਤਿਸਟ ਦੇਵਿ ਪੂਜੰਤ ਜਾਇ।","roman":"Ik dayso beet paarasv raai | utisat devi poojant jaai |","meaning_en":"","page":867},{"gurmukhi":"ਉਸਤਤਿ ਕਿਨ ਬਹੁ ਬਿਧਿ ਪ੍ਰਕਾਰ। ਸੋ ਕਹੋ ਛੰਦ ਮੋਹਣਿ ਮਝਾਰ। ੪੪।","roman":"Usatti kin bahu bidhi prakaar | so kaho chhand mohni majhaar | 44 |","meaning_en":"","page":867}]},{"type":"heading","kind":"chhand","name":"ਮੋਹਣੀ ਛੰਦ","gurmukhi":"ਮੋਹਣੀ ਛੰਦ","roman":"Mohnee chhand","meaning_en":"","page":867},{"type":"verse","number":[45],"number_text":"੪੫।","page":867,"lines":[{"gurmukhi":"ਜੈ ਦੇਵੀ ਭੇਵੀ ਭਾਵਾਣੀ। ਭਉ ਖੰਡੀ ਦੁਰਗਾ ਸਰਬਾਣੀ।","roman":"Jai devee bhevee bhaavaanee | bhau khandee durgaa sarbaanee |","meaning_en":"","page":867},{"gurmukhi":"ਕੇਸਰੀਆ ਬਾਹੀ ਕਊਮਾਰੀ। ਭੈਖੰਡੀ ਭੈਰਵਿ ਉਧਾਰੀ। ੪੫।","roman":"Kesreeaa baahee kaoomaaree | bhaikhandee bhairvi udhaaree | 45 |","meaning_en":"","page":867}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":867,"lines":[{"gurmukhi":"ਅਕਲੰਕਾ ਅਤ੍ਰੀ ਛਤ੍ਰਾਣੀ। ਮੋਹਣੀਅੰ ਸਰਬੰ ਲੋਕਾਣੀ।","roman":"Aklankaa atree chhatraanee | mohneean sarban lokaanee |","meaning_en":"","page":867},{"gurmukhi":"ਰਕਤਾਂਗੀ ਸਾਂਗੀ ਸਾਵਿਤ੍ਰੀ। ਪਰਮੇਸ੍ਰੀ ਪਰਮਾ ਪਾਵਿਤ੍ਰੀ। ੪੬।","roman":"Raktaangee saangee saavitree | parmesree parmaa paavitree | 46 |","meaning_en":"","page":867}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":868,"lines":[{"gurmukhi":"ਤੋਤਲੀਆ ਜਿਹਬਾ ਕਊਮਾਰੀ। ਭਵ ਭਰਣੀ ਹਰਣੀ ਉਧਾਰੀ।","roman":"Totleeaa jihbaa kaoomaaree | bhav bharnee harnee udhaaree |","meaning_en":"","page":868},{"gurmukhi":"ਮ੍ਰਿਦੁ ਰੂਪਾ ਭੂਪਾ ਬੁਧਾਣੀ। ਜੈ ਜੰਪੈ ਸੁਧੰ ਸਿਧਾਣੀ। ੪੭।","roman":"Mridu roopaa bhoopaa budhaanee | jai janpai sudhan sidhaanee | 47 |","meaning_en":"","page":868}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":868,"lines":[{"gurmukhi":"ਜਗ ਧਾਰੀ ਭਾਰੀ ਭਗਤਾਯੰ। ਕਰਿ ਧਾਰੀ ਭਾਰੀ ਮੁਕਤਾਯੰ।","roman":"Jag dhaaree bhaaree bhagtaayan | kari dhaaree bhaaree muktaayan |","meaning_en":"","page":868},{"gurmukhi":"ਸੁੰਦਰ ਗੋਫਣੀਆ ਗੁਰਜਾਣੀ। ਤੇ ਬਰਣੀ ਹਰਣੀ ਭਾਮਾਣੀ। ੪੮।","roman":"Sundar gophneeaa gurjaanee | te barnee harnee bhaamaanee | 48 |","meaning_en":"","page":868}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":868,"lines":[{"gurmukhi":"ਭਿੰਭਰੀਆ ਜਛੰ ਸਰਬਾਣੀ। ਗੰਧਰਬੀ ਸਿਧੰ ਚਾਰਾਣੀ।","roman":"Bhinbhreeaa jachhan sarbaanee | gandharbee sidhan chaaraanee |","meaning_en":"","page":868},{"gurmukhi":"ਅਕਲੰਕ ਸਰੂਪੰ ਨਿਰਮਲੀਅੰ। ਘਣ ਮਧੇ ਮਾਨੋ ਚੰਚਲੀਅੰ। ੪੯।","roman":"Aklank saroopan niramleean | ghan madhe maano chanchleean | 49 |","meaning_en":"","page":868}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":868,"lines":[{"gurmukhi":"ਅਸਿਪਾਣੰ ਮਾਣੰ ਲੋਕਾਯੰ। ਸੁਖ ਕਰਣੀ ਹਰਣੀ ਸੋਕਾਯੰ।","roman":"Asipaanan maanan lokaayan | sukh karnee harnee sokaayan |","meaning_en":"","page":868},{"gurmukhi":"ਦੁਸਟ ਹੰਤੀ ਸੰਤੰ ਉਧਾਰੀ। ਅਨਛੇਦਾਭੇਦਾ ਕਉਮਾਰੀ। ੫੦।","roman":"Dusat hantee santan udhaaree | anchhedaabhedaa kaumaaree | 50 |","meaning_en":"","page":868}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":868,"lines":[{"gurmukhi":"ਆਨੰਦੀ ਗਿਰਜਾ ਕਉਮਾਰੀ। ਅਨਛੇਦਾਭੇਦਾ ਉਧਾਰੀ।","roman":"Aanandee girjaa kaumaaree | anchhedaabhedaa udhaaree |","meaning_en":"","page":868},{"gurmukhi":"ਅਨਗੰਜ ਅਭੰਜਾ ਖੰਕਾਲੀ। ਮ੍ਰਿਗਨੈਣੀ ਰੂਪੰ ਉਜਾਲੀ। ੫੧।","roman":"Anganj abhanjaa khankaalee | mrignainee roopan ujaalee | 51 |","meaning_en":"","page":868}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":868,"lines":[{"gurmukhi":"ਰਕਤਾਂਗੀ ਰੁਦ੍ਰਾ ਪਿੰਗਾਛੀ। ਕਟਿ ਕਛੀ ਸ੍ਵਛੀ ਹੁਲਾਸੀ।","roman":"Raktaangee rudraa pingaachhee | kati kachhee svachhee hulaasee |","meaning_en":"","page":868},{"gurmukhi":"ਰਕਤਾਲੀ ਰਾਮਾ ਧਉਲਾਲੀ। ਮੋਹਣੀਆ ਮਾਈ ਖੰਕਾਲੀ। ੫੨।","roman":"Raktaalee raamaa dhaulaalee | mohneeaa maaee khankaalee | 52 |","meaning_en":"","page":868}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":868,"lines":[{"gurmukhi":"ਜਗਦਾਨੀ ਮਾਨੀ ਭਾਵਾਣੀ। ਭਵਖੰਡੀ ਦੁਰਗਾ ਦੇਵਾਣੀ।","roman":"Jagdaanee maanee bhaavaanee | bhavkhandee durgaa devaanee |","meaning_en":"","page":868},{"gurmukhi":"ਰੁਦ੍ਰਾਗੀ ਰੁਦ੍ਰਾ ਰਕਤਾਂਗੀ। ਪਰਮੇਸਰੀ ਮਾਈ ਧਰਮਾਂਗੀ। ੫੩।","roman":"Rudraagee rudraa raktaangee | parmesree maaee dharmaangee | 53 |","meaning_en":"","page":868}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":868,"lines":[{"gurmukhi":"ਮਹਿਖਾਸੁਰ ਦਰਣੀ ਮਹਿਪਾਲੀ। ਚਿਛੁਰਾਸਰ ਹੰਤੀ ਖੰਕਾਲੀ।","roman":"Mahikhaasur darnee mahipaalee | chichhuraasar hantee khankaalee |","meaning_en":"","page":868},{"gurmukhi":"ਅਸਿ ਪਾਣੀ ਮਾਣੀ ਦੇਵਾਣੀ। ਜੈ ਦਾਤੀ ਦੁਰਗਾ ਭਾਵਾਣੀ। ੫੪।","roman":"Asi paanee maanee devaanee | jai daatee durgaa bhaavaanee | 54 |","meaning_en":"","page":868}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":868,"lines":[{"gurmukhi":"ਪਿੰਗਾਛੀ ਪਰਮਾ ਪਾਵਿਤ੍ਰੀ। ਸਾਵਿਤ੍ਰੀ ਸੰਧਿਆ ਗਾਇਤ੍ਰੀ।","roman":"Pingaachhee parmaa paavitree | saavitree sandhiaa gaaitree |","meaning_en":"","page":868},{"gurmukhi":"ਭੈ ਹਰਣੀ ਭੀਮਾ ਭਾਮਾਣੀ। ਜੈ ਦੇਵੀ ਦੁਰਗਾ ਦੇਵਾਣੀ। ੫੫।","roman":"Bhai harnee bheemaa bhaamaanee | jai devee durgaa devaanee | 55 |","meaning_en":"","page":868}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":869,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਦਲ ਗਾਹੀ ਦੇਵਾਣੀ। ਭੈ ਖੰਡੀ ਸਰਬੰ ਭੂਤਾਣੀ।","roman":"Durgaa dal gaahee devaanee | bhai khandee sarban bhootaanee |","meaning_en":"","page":869},{"gurmukhi":"ਜੈ ਚੰਡੀ ਮੁੰਡੀ ਸਤ੍ਰੁ ਹੰਤੀ। ਜੈ ਦਾਤੀ ਮਾਤਾ ਜੈਅੰਤੀ। ੫੬।","roman":"Jai chandee mundee satru hantee | jai daatee maataa jaiantee | 56 |","meaning_en":"","page":869}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":869,"lines":[{"gurmukhi":"ਸੰਸਰਣੀ ਤਰਾਣੀ ਲੋਕਾਣੀ। ਭਿੰਭਰਾਣੀ ਦਰਣੀ ਦਈਤਾਣੀ।","roman":"Sansarnee taraanee lokaanee | bhinbhraanee darnee daeetaanee |","meaning_en":"","page":869},{"gurmukhi":"ਕੇਕਰਣੀ ਕਾਰਣ ਲੋਕਾਣੀ। ਦੁਖ ਹਰਣੀ ਦੇਵੰ ਇੰਦ੍ਰਾਣੀ। ੫੭।","roman":"Kekarnee kaaran lokaanee | dukh harnee devan indraanee | 57 |","meaning_en":"","page":869}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":869,"lines":[{"gurmukhi":"ਸੁੰਭ ਹੰਤੀ ਜਯੰਤੀ ਖੰਕਾਲੀ। ਕੰਕੜੀਆ ਰੂਪਾ ਰਕਤਾਲੀ।","roman":"Sunbh hantee jayantee khankaalee | kankreeaa roopaa raktaalee |","meaning_en":"","page":869},{"gurmukhi":"ਤੋਤਲੀਆ ਜਿਹਵਾ ਸਿੰਧੁਲੀਆ। ਹਿੰਗਲੀਆ ਮਾਤਾ ਪਿੰਗਲੀਆ। ੫੮।","roman":"Totleeaa jihvaa sindhuleeaa | hingleeaa maataa pingleeaa | 58 |","meaning_en":"","page":869}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":869,"lines":[{"gurmukhi":"ਚੰਚਾਲੀ ਚਿਤ੍ਰਾ ਚਿਤ੍ਰਾਂਗੀ। ਭਿੰਭਰੀਆ ਭੀਮਾ ਸਰਬਾਂਗੀ।","roman":"Chanchaalee chitraa chitraangee | bhinbhreeaa bheemaa sarbaangee |","meaning_en":"","page":869},{"gurmukhi":"ਬੁਧਿ ਭੂਪਾ ਕੂਪਾ ਜੁਜ੍ਵਾਲੀ। ਅਕਲੰਕਾ ਮਾਈ ਨ੍ਰਿਮਾਲੀ। ੫੯।","roman":"Budhi bhoopaa koopaa jujvaalee | aklankaa maaee nrimaalee | 59 |","meaning_en":"","page":869}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":869,"lines":[{"gurmukhi":"ਉਛਲੈ ਲੰਕੜੁੀਆ ਛਤ੍ਰਾਲਾ। ਭਿੰਭਰੀਆ ਭੈਰੋ ਭਉਹਾਲਾ।","roman":"Uchhlai lankreeaa chhatraalaa | bhinbhreeaa bhairo bhauhaalaa |","meaning_en":"","page":869},{"gurmukhi":"ਜੈ ਦਾਤਾ ਮਾਤਾ ਜੈਦਾਣੀ। ਲੋਕੇਸੀ ਦੁਰਗਾ ਭਾਵਾਣੀ। ੬੦।","roman":"Jai daataa maataa jaidaanee | lokesee durgaa bhaavaanee | 60 |","meaning_en":"","page":869}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":869,"lines":[{"gurmukhi":"ਸੰਮੋਹੀ ਸਰਬੰ ਜਗਤਾਯੰ। ਨਿੰਦ੍ਰਾ ਛੁਧ੍ਯਾ ਪਿਪਾਸਾਯੰ।","roman":"Sanmohee sarban jagtaayan | nindraa chhudhyaa pipaasaayan |","meaning_en":"","page":869},{"gurmukhi":"ਜੈ ਕਾਲੰ ਰਾਤੀ ਸਕ੍ਰਾਣੀ। ਉਧਾਰੀ ਭਾਰੀ ਭਗਤਾਣੀ। ੬੧।","roman":"Jai kaalan raatee sakraanee | udhaaree bhaaree bhagtaanee | 61 |","meaning_en":"","page":869}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":869,"lines":[{"gurmukhi":"ਜੈ ਮਾਈ ਗਾਈ ਬੇਦਾਣੀ। ਅਨਛਿਜ ਅਭਿਦਾ ਅਖਿਦਾਣੀ।","roman":"Jai maaee gaaee bedaanee | anchhij abhidaa akhidaanee |","meaning_en":"","page":869},{"gurmukhi":"ਭੈ ਹਰਣੀ ਸਰਬੰ ਸੰਤਾਣੀ। ਜੈ ਦਾਤਾ ਮਾਤਾ ਕ੍ਰਿਪਾਣੀ। ੬੨।","roman":"Bhai harnee sarban santaanee | jai daataa maataa kripaanee | 62 |","meaning_en":"","page":869}]},{"type":"heading","kind":"chhand","name":"ਅਚਕੜਾ ਛੰਦ","gurmukhi":"ਅਚਕੜਾ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Achakraa chhand | tvaprasaadi","meaning_en":"","page":869,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[63],"number_text":"੬੩।","page":869,"lines":[{"gurmukhi":"ਅੰਬਿਕਾ ਤੋਤਲਾ ਸੀਤਲਾ ਸਾਕਣੀ।","roman":"Anbikaa totlaa seetlaa saaknee |","meaning_en":"","page":869},{"gurmukhi":"ਸਿੰਧੁਰੀ ਸੁਪ੍ਰਭਾ ਸੁਭ੍ਰਮਾ ਡਾਕਣੀ।","roman":"Sindhuree suprabhaa subhramaa daaknee |","meaning_en":"","page":869},{"gurmukhi":"ਸਾਵਜਾ ਸੰਭਿਰੀ ਸਿੰਧੁਲਾ ਦੁਖਹਰੀ।","roman":"Saavjaa sanbhiree sindhulaa dukhahree |","meaning_en":"","page":869},{"gurmukhi":"ਸੁੰਮਿਲਾ ਸੰਭਿਲਾ ਸੁਪ੍ਰਭਾ ਦੁਧਰੀ। ੬੩।","roman":"Sunmilaa sanbhilaa suprabhaa dudhree | 63 |","meaning_en":"","page":869}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":869,"lines":[{"gurmukhi":"ਭਾਵਨਾ ਭੈ ਹਰੀ ਭੂਤਿਲੀ ਭੈਹਰਾ।","roman":"Bhaavnaa bhai haree bhootilee bhaihraa |","meaning_en":"","page":869},{"gurmukhi":"ਟਾਕਣੀ ਝਾਕਣੀ ਸਾਕਣੀ ਸਿੰਧੁਲਾ।","roman":"Taaknee jhaaknee saaknee sindhulaa |","meaning_en":"","page":869},{"gurmukhi":"ਦੁਧਰਾ ਦ੍ਰੁਮੁਖਾ ਦ੍ਰੁਕਟਾ ਦੁਧਰੀ।","roman":"Dudhraa drumukhaa druktaa dudhree |","meaning_en":"","page":869},{"gurmukhi":"ਕੰਪਿਲਾ ਜੰਪਿਲਾ ਹਿੰਗੁਲਾ ਭੈਹਰੀ। ੬੪।","roman":"Kanpilaa janpilaa hingulaa bhaihree | 64 |","meaning_en":"","page":869}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":870,"lines":[{"gurmukhi":"ਚਿਤ੍ਰਣੀ ਚਾਪਣੀ ਚਾਰਣੀ ਚਛਣੀ।","roman":"Chitranee chaapnee chaarnee chachhnee |","meaning_en":"","page":870},{"gurmukhi":"ਹਿੰਗੁਲਾ ਪਿੰਗੁਲਾ ਗੰਧ੍ਰਬਾ ਜਛਣੀ।","roman":"Hingulaa pingulaa gandhrabaa jachhnee |","meaning_en":"","page":870},{"gurmukhi":"ਬਰਮਣੀ ਚਰਮਣੀ ਪਰਘਣੀ ਪਾਸਣੀ।","roman":"Baramnee charamnee paraghnee paasnee |","meaning_en":"","page":870},{"gurmukhi":"ਖੜਗਣੀ ਗੜਗਣੀ ਸੈਥਣੀ ਸਾਪਣੀ। ੬੫।","roman":"Kharagnee garagnee saithnee saapnee | 65 |","meaning_en":"","page":870}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":870,"lines":[{"gurmukhi":"ਭੀਮੜਾ ਸਮਦੜਾ ਹਿੰਗੁਲਾ ਕਾਰਤਕੀ।","roman":"Bheemraa samadraa hingulaa kaaratkee |","meaning_en":"","page":870},{"gurmukhi":"ਸੁਪ੍ਰਭਾ ਅਛਿਦਾ ਅਧਿਰਾ ਮਾਰੁਤਕੀ।","roman":"Suprabhaa achhidaa adhiraa maarutkee |","meaning_en":"","page":870},{"gurmukhi":"ਗਿੰਗਲੀ ਹਿੰਗੁਲੀ ਠਿੰਗੁਲੀ ਪਿੰਗੁਲਾ।","roman":"Ginglee hingulee thingulee pingulaa |","meaning_en":"","page":870},{"gurmukhi":"ਚਿਕਣੀ ਚਰਕਟਾ ਚਰਪਟਾ ਚਾਂਵਡਾ। ੬੬।","roman":"Chiknee charaktaa charaptaa chaanvdaa | 66 |","meaning_en":"","page":870}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":870,"lines":[{"gurmukhi":"ਅਛਿਦਾ ਅਭਿਦਾ ਅਸਿਤਾ ਅਧਰੀ।","roman":"Achhidaa abhidaa asitaa adhree |","meaning_en":"","page":870},{"gurmukhi":"ਅਕਟਾ ਅਖੰਡਾ ਅਛਟਾ ਦੁਧਰੀ।","roman":"Aktaa akhandaa achhtaa dudhree |","meaning_en":"","page":870},{"gurmukhi":"ਅੰਜਨੀ ਅੰਬਿਕਾ ਅਸਤ੍ਰਣੀ ਧਾਰਣੀ।","roman":"Anjnee anbikaa astranee dhaarnee |","meaning_en":"","page":870},{"gurmukhi":"ਅਭਰੰ ਅਧਰਾ ਜਗਤਿ ਉਧਾਰਣੀ। ੬੭।","roman":"Abhran adhraa jagti udhaarnee | 67 |","meaning_en":"","page":870}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":870,"lines":[{"gurmukhi":"ਅੰਜਨੀ ਗੰਜਨੀ ਸਾਕੜੀ ਸੀਤਲਾ।","roman":"Anjnee ganjnee saakree seetlaa |","meaning_en":"","page":870},{"gurmukhi":"ਸਿਧਰੀ ਸੁਪ੍ਰਭਾ ਸਾਮਲਾ ਤੋਤਲਾ।","roman":"Sidhree suprabhaa saamlaa totlaa |","meaning_en":"","page":870},{"gurmukhi":"ਸੰਭਰੀ ਗੰਭਰੀ ਅੰਭਰੀ ਅਕਟਾ।","roman":"Sanbhree ganbhree anbhree aktaa |","meaning_en":"","page":870},{"gurmukhi":"ਦੁਸਲਾ ਦ੍ਰੁਭਿਖਾ ਦ੍ਰੁਕਟਾ ਅਮਿਟਾ। ੬੮।","roman":"Duslaa drubhikhaa druktaa amitaa | 68 |","meaning_en":"","page":870}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":870,"lines":[{"gurmukhi":"ਭੈਰਵੀ ਭੈਹਰੀ ਭੂਚਰਾ ਭਾਨਵੀ।","roman":"Bhairvee bhaihree bhoochraa bhaanvee |","meaning_en":"","page":870},{"gurmukhi":"ਤ੍ਰਿਕੁਟਾ ਚਰਪਟਾ ਚਾਂਵਡਾ ਮਾਨਵੀ।","roman":"Trikutaa charaptaa chaanvdaa maanvee |","meaning_en":"","page":870},{"gurmukhi":"ਜੋਬਨਾ ਜੈਕਰੀ ਜੰਭਹਰੀ ਜਾਲਪਾ।","roman":"Jobnaa jaikree janbhahree jaalpaa |","meaning_en":"","page":870},{"gurmukhi":"ਤੋਤਲਾ ਤੁੰਦਲਾ ਦੰਤਲੀ ਕਾਲਿਕਾ। ੬੯।","roman":"Totlaa tundlaa dantlee kaalikaa | 69 |","meaning_en":"","page":870}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":870,"lines":[{"gurmukhi":"ਭਰਮਣਾ ਨਿਭ੍ਰਮਾ ਭਾਵਨਾ ਭੈਹਰੀ।","roman":"Bharamnaa nibhramaa bhaavnaa bhaihree |","meaning_en":"","page":870},{"gurmukhi":"ਬਰ ਬੁਧਾ ਦਾਤ੍ਰਣੀ ਸਤ੍ਰਣੀ ਛੈਕਰੀ।","roman":"Bar budhaa daatranee satranee chhaikree |","meaning_en":"","page":870},{"gurmukhi":"ਦ੍ਰੁਕਟਾ ਦ੍ਰੁਭਿਦਾ ਦੁਧਰਾ ਦ੍ਰੁਮਦੀ।","roman":"Druktaa drubhidaa dudhraa drumdee |","meaning_en":"","page":870},{"gurmukhi":"ਅਤ੍ਰੁਟਾ ਅਛੁਟਾ ਅਜਟਾ ਅਭਿਦੀ। ੭੦।","roman":"Atrutaa achhutaa ajtaa abhidee | 70 |","meaning_en":"","page":870}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":870,"lines":[{"gurmukhi":"ਤੰਤਲਾ ਅੰਤਲਾ ਸੰਤਲਾ ਸਾਵਜਾ।","roman":"Tantlaa antlaa santlaa saavjaa |","meaning_en":"","page":870},{"gurmukhi":"ਭੀਮੜਾ ਭੈਹਰੀ ਭੂਤਲਾ ਬਾਵਜਾ।","roman":"Bheemraa bhaihree bhootlaa baavjaa |","meaning_en":"","page":870},{"gurmukhi":"ਡਾਕਣੀ ਸਾਕਣੀ ਝਾਕਣੀ ਕਾਕਿੜਾ।","roman":"Daaknee saaknee jhaaknee kaakiraa |","meaning_en":"","page":870},{"gurmukhi":"ਕਿੰਕੜੀ ਕਾਲਿਕਾ ਜਾਲਪਾ ਜੈ ਮ੍ਰਿੜਾ। ੭੧।","roman":"Kinkree kaalikaa jaalpaa jai mriraa | 71 |","meaning_en":"","page":870}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":871,"lines":[{"gurmukhi":"ਠਿੰਗੁਲਾ ਹਿੰਗੁਲਾ ਪਿੰਗੁਲਾ ਪ੍ਰਾਸਣੀ।","roman":"Thingulaa hingulaa pingulaa praasnee |","meaning_en":"","page":871},{"gurmukhi":"ਸਸਤ੍ਰਣੀ ਅਸਤ੍ਰਣੀ ਸੂਲਣੀ ਸਾਸਣੀ।","roman":"Sastranee astranee soolnee saasnee |","meaning_en":"","page":871},{"gurmukhi":"ਕੰਨਿਕਾ ਅੰਨਿਕਾ ਧੰਨਿਕਾ ਧਉਲਰੀ।","roman":"Kannikaa annikaa dhannikaa dhaulree |","meaning_en":"","page":871},{"gurmukhi":"ਰਕਤਿਕਾ ਸਕਤਿਕਾ ਭਕਤਕਾ ਜੈਕਰੀ। ੭੨।","roman":"Raktikaa saktikaa bhakatkaa jaikree | 72 |","meaning_en":"","page":871}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":871,"lines":[{"gurmukhi":"ਝਿੰਗੜਾ ਪਿੰਗੜਾ ਜਿੰਗੜਾ ਜਾਲਪਾ।","roman":"Jhingraa pingraa jingraa jaalpaa |","meaning_en":"","page":871},{"gurmukhi":"ਜੋਗਣੀ ਭੋਗਣੀ ਰੋਗ ਹਰੀ ਕਾਲਿਕਾ।","roman":"Jognee bhognee rog haree kaalikaa |","meaning_en":"","page":871},{"gurmukhi":"ਚੰਚਲਾ ਚਾਂਵਡਾ ਚਾਚਰਾ ਚਿਤ੍ਰਤਾ।","roman":"Chanchlaa chaanvdaa chaachraa chitrataa |","meaning_en":"","page":871},{"gurmukhi":"ਤੰਤਰੀ ਭਿੰਭਰੀ ਛਤ੍ਰਣੀ ਛਿੰਛਲਾ। ੭੩।","roman":"Tantree bhinbhree chhatranee chhinchhlaa | 73 |","meaning_en":"","page":871}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":871,"lines":[{"gurmukhi":"ਦੰਤੁਲਾ ਦਾਮਣੀ ਦ੍ਰੁਕਟਾ ਦ੍ਰੁਭ੍ਰਮਾ।","roman":"Dantulaa daamnee druktaa drubhramaa |","meaning_en":"","page":871},{"gurmukhi":"ਛੁਧਿਤਾ ਨਿੰਦ੍ਰਕਾ ਨ੍ਰਿਭਿਖਾ ਨ੍ਰਿਗਮਾ।","roman":"Chhudhitaa nindrakaa nribhikhaa nrigmaa |","meaning_en":"","page":871},{"gurmukhi":"ਕਦ੍ਰਕਾ ਚੂੜਿਕਾ ਚਾਚਕਾ ਚਾਪਣੀ।","roman":"Kadrakaa choorikaa chaachkaa chaapnee |","meaning_en":"","page":871},{"gurmukhi":"ਚਿਚ੍ਰੜੀ ਚਾਵੜਾ ਚਿੰਪਿਲਾ ਜਾਪਣੀ। ੭੪।","roman":"Chichraree chaavraa chinpilaa jaapnee | 74 |","meaning_en":"","page":871}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"","page":871},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"","page":871},{"type":"verse","number":[75],"number_text":"੭੫।","page":871,"lines":[{"gurmukhi":"ਕੈਸੇ ਕੌ ਪਾਇਨ ਪ੍ਰਭਾ ਉਚਾਰੋ।","roman":"Kaise kau paain prabhaa uchaaro |","meaning_en":"","page":871},{"gurmukhi":"ਜਾਨੁਕ ਨਿਪਟ ਅਘਟ ਅੰਮ੍ਰਿਤ ਸਮ ਸੰਪਟ ਸੁਭਟ ਬਿਚਾਰੋ।","roman":"Jaanuk nipat aghat anmrit sam sanpat subhat bichaaro |","meaning_en":"","page":871},{"gurmukhi":"ਮਨ ਮਧੁਕਰਹਿ ਚਰਨ ਕਮਲਨ ਪਰ ਹ੍ਵੈ ਮਨਮਤ ਗੁੰਜਾਰੋ।","roman":"Man madhukarhi charan kamlan par hvai manmat gunjaaro |","meaning_en":"","page":871},{"gurmukhi":"ਮਾਤ੍ਰਿਕ ਸਪਤ ਸਪਿਤ ਪਿਤਰਨ ਕੁਲ ਚੌਦਹੂੰ ਕੁਲੀ ਉਧਾਰੋ। ੭੫।","roman":"Maatrik sapat sapit pitran kul chaudhoon kulee udhaaro | 75 |","meaning_en":"","page":871}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"","page":871},{"type":"verse","number":[76],"number_text":"੭੬।","page":871,"lines":[{"gurmukhi":"ਤਾ ਦਿਨ ਦੇਹ ਸਫਲ ਕਰ ਜਾਨੋ।","roman":"Taa din deh saphal kar jaano |","meaning_en":"","page":871},{"gurmukhi":"ਜਾ ਦਿਨ ਜਗਤ ਮਾਤ ਪ੍ਰਫੁਲਿਤ ਹ੍ਵੈ ਦੇਹਿ ਬਿਜੈ ਬਰਦਾਨੋ।","roman":"Jaa din jagat maat praphulit hvai dehi bijai bardaano |","meaning_en":"","page":871},{"gurmukhi":"ਤਾ ਦਿਨ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਕਟਿ ਬਾਧੋ ਚੰਦਨ ਚਿਤ੍ਰ ਲਗਾਊਂ।","roman":"Taa din sasatr asatr kati baadho chandan chitr lagaaoon |","meaning_en":"","page":871},{"gurmukhi":"ਜਾ ਕਹੁ ਨੇਤ ਨਿਗਮ ਕਹਿ ਬੋਲਤ ਤਾਸੁ ਸੁ ਬਰੁ ਜਬ ਪਾਊਂ। ੭੬।","roman":"Jaa kahu net nigam kahi bolat taasu su baru jab paaoon | 76 |","meaning_en":"","page":871}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":871},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"","page":871},{"type":"verse","number":[77],"number_text":"੭੭।","page":871,"lines":[{"gurmukhi":"ਅੰਤਰਜਾਮੀ ਅਭਯ ਭਵਾਨੀ।","roman":"Antarjaamee abhay bhavaanee |","meaning_en":"","page":871},{"gurmukhi":"ਅਤਿ ਹੀ ਨਿਰਖਿ ਪ੍ਰੇਮ ਪਾਰਸ ਕੋ ਚਿਤ ਕੀ ਬ੍ਰਿਥਾ ਪਛਾਨੀ।","roman":"Ati hee nirkhi prem paaras ko chit kee brithaa pachhaanee |","meaning_en":"","page":871},{"gurmukhi":"ਆਪਨ ਭਗਤ ਜਾਨ ਭਵਖੰਡਨ ਅਭਯ ਰੂਪ ਦਿਖਾਯੋ।","roman":"Aapan bhagat jaan bhavkhandan abhay roop dikhaayo |","meaning_en":"","page":871},{"gurmukhi":"ਚਕ੍ਰਤ ਰਹੇ ਪੇਖਿ ਮੁਨਿ ਜਨ ਸੁਰ ਅਜਰ ਅਮਰ ਪਦ ਪਾਯੋ। ੭੭।","roman":"Chakrat rahe pekhi muni jan sur ajar amar pad paayo | 77 |","meaning_en":"","page":871}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":871,"lines":[{"gurmukhi":"ਸੋਭਿਤ ਬਾਮਹਿੰ ਪਾਨਿ ਕ੍ਰਿਪਾਣੀ।","roman":"Sobhit baamhin paani kripaanee |","meaning_en":"","page":871},{"gurmukhi":"ਜਾ ਤਰ ਜਛ ਕਿੰਨਰ ਅਸੁਰਨ ਕੀ ਸਬ ਕੀ ਕ੍ਰਿਯਾ ਹਿਰਾਨੀ।","roman":"Jaa tar jachh kinnar asuran kee sab kee kriyaa hiraanee |","meaning_en":"","page":871},{"gurmukhi":"ਜਾ ਤਨ ਮਧੁ ਕੀਟਭ ਕਹੁ ਖੰਡ੍ਯੋ ਸੁੰਭ ਨਿਸੁੰਭ ਸੰਘਾਰੇ।","roman":"Jaa tan madhu keetabh kahu khandyo sunbh nisunbh sanghaare |","meaning_en":"","page":871},{"gurmukhi":"ਸੋਈ ਕ੍ਰਿਪਾਨ ਨਿਦਾਨ ਲਗੇ ਜਗ ਦਾਇਨ ਰਹੋ ਹਮਾਰੇ। ੭੮।","roman":"Soee kripaan nidaan lage jag daain raho hamaare | 78 |","meaning_en":"","page":871}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":872,"lines":[{"gurmukhi":"ਜਾ ਤਨ ਬਿੜਾਲਾਛ ਚਿਛ੍ਰਾਦਿਕ ਖੰਡਨ ਖੰਡ ਉਡਾਏ।","roman":"Jaa tan biraalaachh chichhraadik khandan khand udaae |","meaning_en":"","page":872},{"gurmukhi":"ਧੂਲੀਕਰਨ ਧੂਮ੍ਰਲੋਚਨ ਕੇ ਮਾਸਨ ਗਿਧ ਰਜਾਏ।","roman":"Dhooleekran dhoomralochan ke maasan gidh rajaae |","meaning_en":"","page":872},{"gurmukhi":"ਰਾਮ ਰਸੂਲ ਕਿਸਨ ਬਿਸਨਾਦਿਕ ਕਾਲ ਕ੍ਰਵਾਲਹਿ ਕੂਟੇ।","roman":"Raam rasool kisan bisnaadik kaal kravaalhi koote |","meaning_en":"","page":872},{"gurmukhi":"ਕੋਟਿ ਉਪਾਇ ਧਾਇ ਸਭ ਥਾਕੇ ਬਿਨ ਤਿਹ ਭਜਨ ਨ ਛੂਟੇ। ੭੯।","roman":"Koti upaai dhaai sabh thaake bin tih bhajan na chhoote | 79 |","meaning_en":"","page":872}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੂਹੀ","gurmukhi":"ਬਿਸਨਪਦ। ਸੂਹੀ","roman":"Bisanpad | soohee","meaning_en":"","page":872},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"","page":872},{"type":"verse","number":[80],"number_text":"੮੦।","page":872,"lines":[{"gurmukhi":"ਸੋਭਿਤ ਪਾਨਿ ਕ੍ਰਿਪਾਨ ਉਜਾਰੀ।","roman":"Sobhit paani kripaan ujaaree |","meaning_en":"","page":872},{"gurmukhi":"ਜਾ ਤਨ ਇੰਦ੍ਰ ਕੋਟਿ ਕਈ ਖੰਡੇ ਬਿਸਨ ਕ੍ਰੋਰਿ ਤ੍ਰਿਪੁਰਾਰੀ।","roman":"Jaa tan indr koti kaee khande bisan krori tripuraaree |","meaning_en":"","page":872},{"gurmukhi":"ਜਾ ਕਹੁ ਰਾਮ ਉਚਰ ਮੁਨਿ ਜਨ ਸਬ ਸੇਵਤ ਧਿਆਨ ਲਗਾਏ।","roman":"Jaa kahu raam uchar muni jan sab sevat dhiaan lagaae |","meaning_en":"","page":872},{"gurmukhi":"ਤਸ ਤੁਮ ਰਾਮ ਕ੍ਰਿਸਨ ਕਈ ਕੋਟਿਕ ਬਾਰ ਉਪਾਇ ਮਿਟਾਏ। ੮੦।","roman":"Tas tum raam krisan kaee kotik baar upaai mitaae | 80 |","meaning_en":"","page":872}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":872,"lines":[{"gurmukhi":"ਅਨਭਵ ਰੂਪ ਸਰੂਪ ਅਗੰਜਨ ਕਹੋ ਕਵਨ ਬਿਧਿ ਗਈਯੈ।","roman":"Anbhav roop saroop aganjan kaho kavan bidhi gaeeyai |","meaning_en":"","page":872},{"gurmukhi":"ਜਿਹਬਾ ਸਹੰਸ੍ਰ ਰਟਤ ਗੁਨ ਥਾਕੀ ਕਬਿ ਜਿਹਵੇਕ ਬਤਈਯੈ।","roman":"Jihbaa sahansr ratat gun thaakee kabi jihvek bataeeyai |","meaning_en":"","page":872},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਪਤਾਰ ਜਵਨ ਕਰ ਚਉਦਹਿ ਖੰਡ ਬਿਹੰਡੇ।","roman":"Bhoomi akaas pataar javan kar chaudhi khand bihande |","meaning_en":"","page":872},{"gurmukhi":"ਜਗਮਗ ਜੋਤਿ ਹੋਤਿ ਭੂਤਲਿ ਮੈ ਖੰਡਨ ਅਉ ਬ੍ਰਹਮੰਡੇ। ੮੧।","roman":"Jagmag joti hoti bhootli mai khandan au brahmande | 81 |","meaning_en":"","page":872}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":872},{"type":"verse","number":[82],"number_text":"੮੨।","page":872,"lines":[{"gurmukhi":"ਜੈ ਜੈ ਰੂਪ ਅਰੇਖ ਅਪਾਰ।","roman":"Jai jai roop arekh apaar |","meaning_en":"","page":872},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਭ੍ਰਮਾਇ ਜਹ ਤਹ ਭੀਖ ਕੋ ਸਿਵ ਦੁਆਰ।","roman":"Jaasi paai bhramaai jah tah bheekh ko siv duaar |","meaning_en":"","page":872},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਲਗ੍ਯੋ ਨਿਸੇਸਿਹ ਕਾਰਮਾ ਤਨ ਏਕ।","roman":"Jaasi paai lagyo nisesih kaarmaa tan ek |","meaning_en":"","page":872},{"gurmukhi":"ਦੇਵਤੇਸ ਸਹੰਸ੍ਰ ਭੇ ਭਗ ਜਾਸਿ ਪਾਇ ਅਨੇਕ। ੮੨।","roman":"Devtes sahansr bhe bhag jaasi paai anek | 82 |","meaning_en":"","page":872}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":872,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਰਾਮ ਭਏ ਕਿਤੇ ਪੁਨਿ ਕਾਲ ਪਾਇ ਬਿਹਾਨ।","roman":"Krisan raam bhae kite puni kaal paai bihaan |","meaning_en":"","page":872},{"gurmukhi":"ਕਾਲ ਕੋ ਅਨਕਾਲ ਕੈ ਅਕਲੰਕ ਮੂਰਤਿ ਮਾਨ।","roman":"Kaal ko ankaal kai aklank moorti maan |","meaning_en":"","page":872},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਭਯੋ ਸਭੈ ਜਗ ਜਾਸ ਪਾਇ ਬਿਲਾਨ।","roman":"Jaasi paai bhayo sabhai jag jaas paai bilaan |","meaning_en":"","page":872},{"gurmukhi":"ਤਾਹਿ ਤੈ ਅਬਿਚਾਰ ਜੜ ਕਰਤਾਰ ਕਾਹਿ ਨ ਜਾਨ। ੮੩।","roman":"Taahi tai abichaar jar kartaar kaahi na jaan | 83 |","meaning_en":"","page":872}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":872,"lines":[{"gurmukhi":"ਨਰਹਰਿ ਜਾਨ ਕਾਹਿ ਨ ਲੇਤ।","roman":"Narahri jaan kaahi na let |","meaning_en":"","page":872},{"gurmukhi":"ਤੈ ਭਰੋਸ ਪਰ੍ਯੋ ਪਸੂ ਜਿਹ ਮੋਹਿ ਬਧਿ ਅਚੇਤ।","roman":"Tai bharos paryo pasoo jih mohi badhi achet |","meaning_en":"","page":872},{"gurmukhi":"ਰਾਮ ਕ੍ਰਿਸਨ ਰਸੂਲ ਕੋ ਉਠਿ ਲੇਤ ਨਿਤਪ੍ਰਤਿ ਨਾਉ।","roman":"Raam krisan rasool ko uthi let nitprati naau |","meaning_en":"","page":872},{"gurmukhi":"ਕਹਾ ਵੈ ਅਬ ਜੀਅਤ ਜਗ ਮੈ ਕਹਾ ਤਿਨ ਕੋ ਗਾਉ। ੮੪।","roman":"Kahaa vai ab jeeat jag mai kahaa tin ko gaau | 84 |","meaning_en":"","page":872}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਿ","gurmukhi":"ਸੋਰਠਿ","roman":"Sorthi","meaning_en":"","page":873},{"type":"verse","number":[85],"number_text":"੮੫।","page":873,"lines":[{"gurmukhi":"ਤਾਸ ਕਿਉ ਨ ਪਛਾਨਹੀ ਜੇ ਹੋਹਿ ਹੈ ਅਬ ਹੈ।","roman":"Taas kiu na pachhaanhee je hohi hai ab hai |","meaning_en":"","page":873},{"gurmukhi":"ਨਿਹਫਲ ਕਾਹੇ ਭਜਤ ਪਾਹਨ ਤੋਹਿ ਕਛੁ ਫਲਿ ਦੈ।","roman":"Nihphal kaahe bhajat paahan tohi kachhu phali dai |","meaning_en":"","page":873},{"gurmukhi":"ਤਾਸੁ ਸੇਵਹੁ ਜਾਸ ਸੇਵਤਿ ਹੋਹਿ ਪੂਰਣ ਕਾਮ।","roman":"Taasu sevhu jaas sevti hohi pooran kaam |","meaning_en":"","page":873},{"gurmukhi":"ਹੋਹਿ ਮਨਸਾ ਸਕਲ ਪੂਰਣ ਲੈਤ ਜਾ ਕੇ ਨਾਮ। ੮੫।","roman":"Hohi mansaa sakal pooran lait jaa ke naam | 85 |","meaning_en":"","page":873}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਰਾਮਕਲੀ","gurmukhi":"ਬਿਸਨਪਦ। ਰਾਮਕਲੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | raamaklee | tvaprasaadi","meaning_en":"","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[86],"number_text":"੮੬।","page":873,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਕੀਨੀ ਜਬੈ ਬਡਾਈ।","roman":"Ih bidhi keenee jabai badaaee |","meaning_en":"","page":873},{"gurmukhi":"ਰੀਝੇ ਦੇਵ ਦਿਆਲ ਤਿਹ ਉਪਰ ਪੂਰਣ ਪੁਰਖ ਸੁਖਦਾਈ।","roman":"Reejhe dev diaal tih upar pooran purakh sukhdaaee |","meaning_en":"","page":873},{"gurmukhi":"ਆਪਨਿ ਮਿਲੇ ਦੇਵਿ ਦਰਸਨਿ ਭਯੋ ਸਿੰਘ ਕਰੀ ਅਸਵਾਰੀ।","roman":"Aapni mile devi darasni bhayo singh karee asvaaree |","meaning_en":"","page":873},{"gurmukhi":"ਲੀਨੇ ਛਤ੍ਰ ਲੰਕੁਰਾ ਕੂਦਤ ਨਾਚਤ ਗਣ ਦੈ ਤਾਰੀ। ੮੬।","roman":"Leene chhatr lankuraa koodat naachat gan dai taaree | 86 |","meaning_en":"","page":873}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":873,"lines":[{"gurmukhi":"ਝਮਕਤ ਅਸਤ੍ਰ ਛਟਾ ਸਸਤ੍ਰਨਿ ਕੀ ਬਾਜਤ ਡਉਰ ਅਪਾਰ।","roman":"Jhamkat asatr chhataa sastrani kee baajat daur apaar |","meaning_en":"","page":873},{"gurmukhi":"ਨਿਰਤਤ ਭੂਤ ਪ੍ਰੇਤ ਨਾਨਾ ਬਿਧਿ ਡਹਕਤ ਫਿਰਤ ਬੈਤਾਰ।","roman":"Nirtat bhoot pret naanaa bidhi dahkat phirat baitaar |","meaning_en":"","page":873},{"gurmukhi":"ਕੁਹਕਤਿ ਫਿਰਤਿ ਕਾਕਣੀ ਕੁਹਰਤ ਡਹਕਤ ਕਠਨ ਮਸਾਨ।","roman":"Kuhakti phirti kaaknee kuhrat dahkat kathan masaan |","meaning_en":"","page":873},{"gurmukhi":"ਘਹਰਤਿ ਗਗਨਿ ਸਘਨ ਰਿਖ ਦਹਲਤ ਬਿਚਰਤ ਬ੍ਯੋਮ ਬਿਵਾਨ। ੮੭।","roman":"Ghaharti gagni saghan rikh dahlat bichrat byom bivaan | 87 |","meaning_en":"","page":873}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਬਾਚ","gurmukhi":"ਦੇਵੀ ਬਾਚ","roman":"Devee baach","meaning_en":"","page":873},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | saarang | tvaprasaadi","meaning_en":"","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[88],"number_text":"੮੮।","page":873,"lines":[{"gurmukhi":"ਕਛੂ ਬਰ ਮਾਂਗਹੁ ਪੂਤ ਸਯਾਨੇ।","roman":"Kachhoo bar maanghu poot sayaane |","meaning_en":"","page":873},{"gurmukhi":"ਭੂਤ ਭਵਿਖ ਨਹੀ ਤੁਮਰੀ ਸਰ ਸਾਧ ਚਰਿਤ ਹਮ ਜਾਨੇ।","roman":"Bhoot bhavikh nahee tumree sar saadh charit ham jaane |","meaning_en":"","page":873},{"gurmukhi":"ਜੋ ਬਰਦਾਨ ਚਹੋ ਸੋ ਮਾਂਗੋ ਸਬ ਹਮ ਤੁਮੈ ਦਿਵਾਰ।","roman":"Jo bardaan chaho so maango sab ham tumai divaar |","meaning_en":"","page":873},{"gurmukhi":"ਕੰਚਨ ਰਤਨ ਬਜ੍ਰ ਮੁਕਤਾਫਲ ਲੀਜਹਿ ਸਕਲ ਸੁ ਧਾਰ। ੮੮।","roman":"Kanchan ratan bajr muktaaphal leejhi sakal su dhaar | 88 |","meaning_en":"","page":873}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸ ਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਾਚ","roman":"Paaras naath baach","meaning_en":"","page":873},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"","page":873},{"type":"verse","number":[89],"number_text":"੮੯।","page":873,"lines":[{"gurmukhi":"ਸਬ ਹੀ ਪੜੋ ਬੇਦ ਬਿਦਿਆ ਬਿਧਿ ਸਬ ਹੀ ਸਸਤ੍ਰ ਚਲਾਊ।","roman":"Sab hee paro bed bidiaa bidhi sab hee sasatr chalaaoo |","meaning_en":"","page":873},{"gurmukhi":"ਸਬ ਹੀ ਦੇਸ ਜੇਰ ਕਰਿ ਆਪਨ ਆਪੇ ਮਤਾ ਮਤਾਊ।","roman":"Sab hee des jer kari aapan aape mataa mataaoo |","meaning_en":"","page":873},{"gurmukhi":"ਕਹਿ ਤਥਾਸਤੁ ਭਈ ਲੋਪ ਚੰਡਿਕਾ ਤਾਸ ਮਹਾ ਬਰ ਦੈ ਕੈ।","roman":"Kahi tathaastu bhaee lop chandikaa taas mahaa bar dai kai |","meaning_en":"","page":873},{"gurmukhi":"ਅੰਤ੍ਰ ਧ੍ਯਾਨ ਹੁਐ ਗਈ ਆਪਨ ਪਰ ਸਿੰਘ ਅਰੂੜਤ ਹੂਐ ਕੈ। ੮੯।","roman":"Antr dhyaan huai gaee aapan par singh aroorat hooai kai | 89 |","meaning_en":"","page":873,"flags":[{"code":"ੁ+ੂ","reason":"overlapping ੁ and ੂ drawn as one ੂ"}]}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਗਉਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਗਉਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | gauree | tvaprasaadi","meaning_en":"","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[90],"number_text":"੯੦।","page":873,"lines":[{"gurmukhi":"ਪਾਰਸ ਕਰਿ ਡੰਡੌਤ ਫਿਰਿ ਆਏ।","roman":"Paaras kari dandaut phiri aae |","meaning_en":"","page":873},{"gurmukhi":"ਆਵਤ ਬੀਰ ਦੇਸ ਦੇਸਨ ਤੇ ਮਾਨੁਖ ਭੇਜ ਬੁਲਾਏ।","roman":"Aavat beer des desan te maanukh bhej bulaae |","meaning_en":"","page":873},{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਰੂਪ ਬਿਲੋਕਿ ਸੁਭਟ ਸਭ ਚਕ੍ਰਿਤ ਚਿਤ ਬਿਸਮਾਏ।","roman":"Nrip ko roop biloki subhat sabh chakrit chit bismaae |","meaning_en":"","page":873},{"gurmukhi":"ਐਸੇ ਕਬਹੀ ਲਖੇ ਨਹੀ ਰਾਜਾ ਜੈਸੇ ਆਜ ਲਖਾਏ।","roman":"Aise kabhee lakhe nahee raajaa jaise aaj lakhaae |","meaning_en":"","page":873},{"gurmukhi":"ਚਕ੍ਰਿਤ ਭਈ ਗਗਨਿ ਕੀ ਬਾਲਾ ਗਨ ਉਡਗਨ ਬਿਰਮਾਏ।","roman":"Chakrit bhaee gagni kee baalaa gan udgan birmaae |","meaning_en":"","page":873},{"gurmukhi":"ਝਿਮਝਿਮ ਮੇਘ ਬੂੰਦ ਜ੍ਯੋਂ ਦੇਵਨ ਅਮਰ ਪੁਹਪ ਬਰਖਾਏ।","roman":"Jhimjhim megh boond jyon devan amar puhap barkhaae |","meaning_en":"","page":874},{"gurmukhi":"ਜਾਨੁਕ ਜੁਬਨ ਖਾਨ ਹੁਐ ਨਿਕਸੇ ਰੂਪ ਸਿੰਧੁ ਅਨੁਵਾਏ।","roman":"Jaanuk juban khaan huai nikse roop sindhu anuvaae |","meaning_en":"","page":874},{"gurmukhi":"ਜਾਨੁਕ ਧਾਰਿ ਨਿਡਰ ਬਸੁਧਾ ਪਰ ਕਾਮ ਕਲੇਵਰ ਆਏ। ੯੦।","roman":"Jaanuk dhaari nidar basudhaa par kaam kalevar aae | 90 |","meaning_en":"","page":874}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦਿ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦਿ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisnapdi | saarang | tvaprasaadi","meaning_en":"","page":874,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[91],"number_text":"੯੧।","page":874,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਪਰਮ ਗ੍ਯਾਨ ਜਬ ਪਾਯੋ।","roman":"Bhoopti param gyaan jab paayo |","meaning_en":"","page":874},{"gurmukhi":"ਮਨ ਬਚ ਕਰਮ ਕਠਨ ਕਰ ਤਾ ਕੋ ਜੌ ਕਰਿ ਧ੍ਯਾਨ ਲਗਾਯੋ।","roman":"Man bach karam kathan kar taa ko jau kari dhyaan lagaayo |","meaning_en":"","page":874},{"gurmukhi":"ਕਰਿ ਬਹੁ ਨ੍ਯਾਸ ਕਠਨ ਜਪੁ ਸਾਧ੍ਯੋ ਦਰਸਨਿ ਦੀਯੋ ਭਵਾਨੀ।","roman":"Kari bahu nyaas kathan japu saadhyo darasni deeyo bhavaanee |","meaning_en":"","page":874},{"gurmukhi":"ਤਤਛਿਨ ਪਰਮ ਗ੍ਯਾਨ ਉਪਦੇਸ੍ਯੋ ਲੋਕ ਚਤੁਰ ਦਸ ਰਾਨੀ।","roman":"Tatchhin param gyaan updesyo lok chatur das raanee |","meaning_en":"","page":874},{"gurmukhi":"ਤਿਹ ਛਿਨ ਸਰਬ ਸਾਸਤ੍ਰ ਮੁਖ ਉਚਰੇ ਤਤ ਅਤਤ ਪਛਾਨਾ।","roman":"Tih chhin sarab saasatr mukh uchre tat atat pachhaanaa |","meaning_en":"","page":874},{"gurmukhi":"ਅਵਰ ਅਤਤ ਸਬੈ ਕਰ ਜਾਨੇ ਏਕ ਤਤ ਠਹਰਾਨਾ।","roman":"Avar atat sabai kar jaane ek tat thahraanaa |","meaning_en":"","page":874},{"gurmukhi":"ਅਨਭਵ ਜੋਤਿ ਅਨੂਪ ਪ੍ਰਕਾਸੀ ਅਨਹਦ ਨਾਦ ਬਜਾਯੋ।","roman":"Anbhav joti anoop prakaasee anhad naad bajaayo |","meaning_en":"","page":874},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਜੀਤਿ ਰਾਜਨ ਕਹੁ ਸੁਭਟ ਅਭੈ ਪਦ ਪਾਯੋ। ੯੧।","roman":"Des bides jeeti raajan kahu subhat abhai pad paayo | 91 |","meaning_en":"","page":874}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"","page":874},{"type":"verse","number":[92],"number_text":"੯੨।","page":874,"lines":[{"gurmukhi":"ਐਸੇ ਅਮਰਪਦ ਕਹੁ ਪਾਇ।","roman":"Aise amarpad kahu paai |","meaning_en":"","page":874},{"gurmukhi":"ਦੇਸ ਅਉਰ ਬਿਦੇਸ ਭੂਪਤਿ ਜੀਤਿ ਲੀਨ ਬੁਲਾਇ।","roman":"Des aur bides bhoopti jeeti leen bulaai |","meaning_en":"","page":874},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਭਰੇ ਗੁਮਾਨ ਨਿਸਾਨ ਸਰਬ ਬਜਾਇ।","roman":"Bhaati bhaati bhare gumaan nisaan sarab bajaai |","meaning_en":"","page":874},{"gurmukhi":"ਚਉਪ ਚਉਪ ਚਲੇ ਚਮੂੰਪਤਿ ਚਿਤ ਚਉਪ ਬਢਾਇ।","roman":"Chaup chaup chale chamoonpti chit chaup badhaai |","meaning_en":"","page":874},{"gurmukhi":"ਆਨਿ ਆਨਿ ਸਬੈ ਲਗੇ ਪਗ ਭੂਪ ਕੇ ਜੁਹਰਾਇ।","roman":"Aani aani sabai lage pag bhoop ke juhraai |","meaning_en":"","page":874},{"gurmukhi":"ਆਵ ਆਵ ਸੁਭਾਵ ਸੋ ਕਹਿ ਲੀਨ ਕੰਠ ਲਗਾਇ।","roman":"Aav aav subhaav so kahi leen kanth lagaai |","meaning_en":"","page":874},{"gurmukhi":"ਹੀਰ ਚੀਰ ਸੁ ਬਾਜ ਦੈ ਗਜ ਰਾਜ ਦੈ ਪਹਿਰਾਇ।","roman":"Heer cheer su baaj dai gaj raaj dai pahiraai |","meaning_en":"","page":874},{"gurmukhi":"ਸਾਧ ਦੈ ਸਨਮਾਨ ਕੈ ਕਰ ਲੀਨ ਚਿਤ ਚੁਰਾਇ। ੯੨।","roman":"Saadh dai sanmaan kai kar leen chit churaai | 92 |","meaning_en":"","page":874}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | kaaphee | tvaprasaadi","meaning_en":"","page":874,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[93],"number_text":"੯੩।","page":874,"lines":[{"gurmukhi":"ਇਮ ਕਰ ਦਾਨ ਦੈ ਸਨਮਾਨ।","roman":"Im kar daan dai sanmaan |","meaning_en":"","page":874},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਿਮੋਹਿ ਭੂਪਤਿ ਭੂਪ ਬੁਧ ਨਿਧਾਨ।","roman":"Bhaati bhaati bimohi bhoopti bhoop budh nidhaan |","meaning_en":"","page":874},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿਨ ਸਾਜ ਦੈ ਬਰ ਬਾਜ ਅਉ ਗਜਰਾਜ।","roman":"Bhaati bhaatin saaj dai bar baaj au gajraaj |","meaning_en":"","page":874},{"gurmukhi":"ਆਪਨੇ ਕੀਨੋ ਨ੍ਰਿਪੰ ਸਬ ਪਾਰਸੈ ਮਹਾਰਾਜ।","roman":"Aapne keeno nripan sab paarsai mahaaraaj |","meaning_en":"","page":874},{"gurmukhi":"ਲਾਲ ਜਾਲ ਪ੍ਰਵਾਲ ਬਿਦ੍ਰਮ ਹੀਰ ਚੀਰ ਅਨੰਤ।","roman":"Laal jaal pravaal bidram heer cheer anant |","meaning_en":"","page":874},{"gurmukhi":"ਲਛ ਲਛ ਸ੍ਵਰਣ ਸਿੰਙੀ ਦਿਜ ਏਕ ਏਕ ਮਿਲੰਤ।","roman":"Lachh lachh svaran sinngee dij ek ek milant |","meaning_en":"","page":874},{"gurmukhi":"ਮੋਹਿ ਭੂਪਿਤ ਭੂਮਿ ਕੈ ਇਕ ਕੀਨ ਜਗ ਬਨਾਇ।","roman":"Mohi bhoopit bhoomi kai ik keen jag banaai |","meaning_en":"","page":874},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸਭਾ ਬਨਾਇ ਸੁ ਬੈਠਿ ਭੂਪਤਿ ਆਇ। ੯੩।","roman":"Bhaati bhaati sabhaa banaai su baithi bhoopti aai | 93 |","meaning_en":"","page":874}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":874,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਬੈਠੇ ਸਭਾ ਬਨਾਈ।","roman":"Ik din baithe sabhaa banaaee |","meaning_en":"","page":874},{"gurmukhi":"ਬਡੇ ਬਡੇ ਛਤ੍ਰੀ ਬਸੁਧਾ ਕੇ ਲੀਨੇ ਨਿਕਟਿ ਬੁਲਾਈ।","roman":"Bade bade chhatree basudhaa ke leene nikti bulaaee |","meaning_en":"","page":874},{"gurmukhi":"ਅਰੁ ਜੇ ਹੁਤੇ ਦੇਸ ਦੇਸਨ ਮਤਿ ਤੇ ਭੀ ਸਰਬ ਬੁਲਾਏ।","roman":"Aru je hute des desan mati te bhee sarab bulaae |","meaning_en":"","page":874},{"gurmukhi":"ਸੁਨਿ ਇਹ ਭਾਤਿ ਸਰਬ ਜਟਧਾਰੀ ਦੇਸ ਦੇਸ ਤੇ ਆਏ।","roman":"Suni ih bhaati sarab jatdhaaree des des te aae |","meaning_en":"","page":874},{"gurmukhi":"ਨਾਨਾ ਭਾਤਿ ਜਟਨ ਕਹ ਧਾਰੇ ਅਰੁ ਮੁਖ ਬਿਭੂਤ ਲਗਾਏ।","roman":"Naanaa bhaati jatan kah dhaare aru mukh bibhoot lagaae |","meaning_en":"","page":875},{"gurmukhi":"ਬਲਕੁਲ ਅੰਗਿ ਦੀਰਘ ਨਖ ਸੋਭਤ ਮ੍ਰਿਗਪਤਿ ਦੇਖ ਲਜਾਏ।","roman":"Balkul angi deeragh nakh sobhat mrigapti dekh lajaae |","meaning_en":"","page":875},{"gurmukhi":"ਮੁੰਦ੍ਰਤ ਨੇਤ੍ਰ ਊਰਧ ਕਰ ਓਪਤ ਪਰਮ ਕਾਛਨੀ ਕਾਛੇ।","roman":"Mundrat netr ooradh kar opat param kaachhnee kaachhe |","meaning_en":"","page":875},{"gurmukhi":"ਨਿਸ ਦਿਨ ਜਪ੍ਯੋ ਕਰਤ ਦਤਾਤ੍ਰੈ ਮਹਾ ਮੁਨੀਸਰ ਆਛੇ। ੯੪।","roman":"Nis din japyo karat dataatrai mahaa muneesar aachhe | 94 |","meaning_en":"","page":875}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ","roman":"Paarasnaath baach","meaning_en":"","page":875},{"type":"heading","kind":"chhand","name":"ਧਨਾਸਰੀ","gurmukhi":"ਧਨਾਸਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Dhanaasree | tvaprasaadi","meaning_en":"","page":875,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[95],"number_text":"੯੫।","page":875,"lines":[{"gurmukhi":"ਕੈ ਤੁਮ ਹਮ ਕੋ ਪਰਚੌ ਦਿਖਾਓ।","roman":"Kai tum ham ko parchau dikhaao |","meaning_en":"","page":875},{"gurmukhi":"ਨਾਤਰ ਜਿਤੇ ਤੁਮ ਹੋ ਜਟਧਾਰੀ ਸਬਹੀ ਜਟਾ ਮੁੰਡਾਓ।","roman":"Naatar jite tum ho jatdhaaree sabhee jataa mundaao |","meaning_en":"","page":875},{"gurmukhi":"ਜੋਗੀ ਜੋਗੁ ਜਟਨ ਕੇ ਭੀਤਰ ਜੇ ਕਰ ਕਛੂਅਕ ਹੋਈ।","roman":"Jogee jogu jatan ke bheetar je kar kachhooak hoee |","meaning_en":"","page":875},{"gurmukhi":"ਤਉ ਹਰਿ ਧ੍ਯਾਨ ਛੋਰਿ ਦਰ ਦਰ ਤੇ ਭੀਖ ਨ ਮਾਂਗੈ ਕੋਈ।","roman":"Tau hari dhyaan chhori dar dar te bheekh na maangai koee |","meaning_en":"","page":875},{"gurmukhi":"ਜੇ ਕਰ ਮਹਾ ਤਤ ਕਹੁ ਚੀਨੈ ਪਰਮ ਤਤ ਕਹੁ ਪਾਵੈ।","roman":"Je kar mahaa tat kahu cheenai param tat kahu paavai |","meaning_en":"","page":875},{"gurmukhi":"ਤਬ ਯਹ ਮੋਨ ਸਾਧਿ ਮਨਿ ਬੈਠੇ ਅਨਤ ਨ ਖੋਜਨ ਧਾਵੈ।","roman":"Tab yah mon saadhi mani baithe anat na khojan dhaavai |","meaning_en":"","page":875},{"gurmukhi":"ਜਾਕੀ ਰੂਪ ਰੇਖ ਨਹੀ ਜਾਨੀਐ ਸਦਾ ਅਦ੍ਵੈਖ ਕਹਾਯੋ।","roman":"Jaakee roop rekh nahee jaaneeai sadaa advaikh kahaayo |","meaning_en":"","page":875},{"gurmukhi":"ਜਉਨ ਅਭੇਖ ਰੇਖ ਨਹੀ ਸੋ ਕਹੁ ਭੇਖ ਬਿਖੈ ਕਿਉ ਆਯੋ। ੯੫।","roman":"Jaun abhekh rekh nahee so kahu bhekh bikhai kiu aayo | 95 |","meaning_en":"","page":875}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | saarang | tvaprasaadi","meaning_en":"","page":875,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[96],"number_text":"੯੬।","page":875,"lines":[{"gurmukhi":"ਜੇ ਜੇ ਤਿਨ ਮੈ ਹੁਤੇ ਸਯਾਨੇ।","roman":"Je je tin mai hute sayaane |","meaning_en":"","page":875},{"gurmukhi":"ਪਾਰਸ ਪਰਮ ਤਤ ਕੇ ਬੇਤਾ ਮਹਾ ਪਰਮ ਕਰ ਮਾਨੇ।","roman":"Paaras param tat ke betaa mahaa param kar maane |","meaning_en":"","page":875},{"gurmukhi":"ਸਬਹਨਿ ਸੀਸ ਨ੍ਯਾਇ ਕਰਿ ਜੋਰੇ ਇਹ ਬਿਧਿ ਸੰਗਿ ਬਖਾਨੇ।","roman":"Sabahni sees nyaai kari jore ih bidhi sangi bakhaane |","meaning_en":"","page":875},{"gurmukhi":"ਜੋ ਜੋ ਗੁਰੂ ਕਹਾ ਸੋ ਕੀਨਾ ਅਉਰ ਹਮ ਕਛੂ ਨ ਜਾਨੇ।","roman":"Jo jo guroo kahaa so keenaa aur ham kachhoo na jaane |","meaning_en":"","page":875},{"gurmukhi":"ਸੁਨਹੋ ਮਹਾਰਾਜ ਰਾਜਨ ਕੇ ਜੋ ਤੁਮ ਬਚਨ ਬਖਾਨੇ।","roman":"Sunho mahaaraaj raajan ke jo tum bachan bakhaane |","meaning_en":"","page":875},{"gurmukhi":"ਸੋ ਹਮ ਦਤ ਬਕਤ੍ਰ ਤੇ ਸੁਨ ਕਰਿ ਸਾਚ ਹੀਐ ਅਨੁਮਾਨੇ।","roman":"So ham dat bakatr te sun kari saach heeai anumaane |","meaning_en":"","page":875},{"gurmukhi":"ਜਾਨੁਕ ਪਰਮ ਅੰਮ੍ਰਿਤ ਤੇ ਨਿਕਸੇ ਮਹਾ ਰਸਨ ਰਸ ਸਾਨੇ।","roman":"Jaanuk param anmrit te nikse mahaa rasan ras saane |","meaning_en":"","page":875},{"gurmukhi":"ਜੋ ਜੋ ਬਚਨ ਭਏ ਇਹ ਮੁਖਿ ਤੇ ਸੋ ਸੋ ਸਬ ਹਮ ਮਾਨੇ। ੯੬।","roman":"Jo jo bachan bhae ih mukhi te so so sab ham maane | 96 |","meaning_en":"","page":875}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":875},{"type":"verse","number":[97],"number_text":"੯੭।","page":875,"lines":[{"gurmukhi":"ਜੋਗੀ ਜੋਗੁ ਜਟਨ ਮੋ ਨਾਹੀ।","roman":"Jogee jogu jatan mo naahee |","meaning_en":"","page":875},{"gurmukhi":"ਭ੍ਰਮ ਭ੍ਰਮ ਮਰਤ ਕਹਾ ਪਚਿ ਪਚਿ ਕਹਿ ਦੇਖਿ ਸਮਝ ਮਨ ਮਾਹੀ।","roman":"Bhram bhram marat kahaa pachi pachi kahi dekhi samajh man maahee |","meaning_en":"","page":875},{"gurmukhi":"ਜੋ ਜਨ ਮਹਾ ਤਤ ਕਹੁ ਜਾਨੈ ਪਰਮ ਗ੍ਯਾਨ ਕਹੁ ਪਾਵੈ।","roman":"Jo jan mahaa tat kahu jaanai param gyaan kahu paavai |","meaning_en":"","page":875},{"gurmukhi":"ਤਬ ਯਹ ਏਕ ਠਉਰ ਮਨੁ ਰਾਖੈ ਦਰਿ ਦਰਿ ਭ੍ਰਮਤ ਨ ਧਾਵੈ।","roman":"Tab yah ek thaur manu raakhai dari dari bhramat na dhaavai |","meaning_en":"","page":875},{"gurmukhi":"ਕਹਾ ਭਯੋ ਗ੍ਰਿਹ ਤਜਿ ਉਠਿ ਭਾਗੇ ਬਨ ਮੈ ਕੀਨ ਨਿਵਾਸਾ।","roman":"Kahaa bhayo grih taji uthi bhaage ban mai keen nivaasaa |","meaning_en":"","page":875},{"gurmukhi":"ਮਨ ਤੋ ਰਹਾ ਸਦਾ ਘਰ ਹੀ ਮੋ ਸੋ ਨਹੀ ਭਯੋ ਉਦਾਸਾ।","roman":"Man to rahaa sadaa ghar hee mo so nahee bhayo udaasaa |","meaning_en":"","page":875},{"gurmukhi":"ਅਧਿਕ ਪ੍ਰਪੰਚ ਦਿਖਾਇਆ ਠਗਾ ਜਗ ਜਾਨਿ ਜੋਗ ਕੋ ਜੋਰਾ।","roman":"Adhik prapanch dikhaaiaa thagaa jag jaani jog ko joraa |","meaning_en":"","page":875},{"gurmukhi":"ਤੁਮ ਜੀਅ ਲਖਾ ਤਜੀ ਹਮ ਮਾਯਾ ਮਾਯਾ ਤੁਮੈ ਨ ਛੋਰਾ। ੯੭।","roman":"Tum jeea lakhaa tajee ham maayaa maayaa tumai na chhoraa | 97 |","meaning_en":"","page":875}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":876},{"type":"verse","number":[98],"number_text":"੯੮।","page":876,"lines":[{"gurmukhi":"ਭੇਖੀ ਜੋਗ ਨ ਭੇਖ ਦਿਖਾਏ।","roman":"Bhekhee jog na bhekh dikhaae |","meaning_en":"","page":876},{"gurmukhi":"ਨਾਹਨ ਜਟਾ ਬਿਭੂਤ ਨਖਨ ਮੈ ਨਾਹਿਨ ਬਸਤ੍ਰ ਰੰਗਾਏ।","roman":"Naahan jataa bibhoot nakhan mai naahin basatr rangaae |","meaning_en":"","page":876},{"gurmukhi":"ਜੋ ਬਨਿ ਬਸੈ ਜੋਗ ਕਹੁ ਪਈਐ ਪੰਛੀ ਸਦਾ ਬਸਤ ਬਨਿ।","roman":"Jo bani basai jog kahu paeeai panchhee sadaa basat bani |","meaning_en":"","page":876},{"gurmukhi":"ਕੁੰਚਰ ਸਦਾ ਧੂਰਿ ਸਿਰਿ ਮੇਲਤ ਦੇਖਹੁ ਸਮਝ ਤੁਮ ਹੀ ਮਨਿ।","roman":"Kunchar sadaa dhoori siri melat dekhhu samajh tum hee mani |","meaning_en":"","page":876},{"gurmukhi":"ਦਾਦੁਰ ਮੀਨ ਸਦਾ ਤੀਰਥ ਮੋ ਕਰ੍ਯੋ ਕਰਤ ਇਸਨਾਨਾ।","roman":"Daadur meen sadaa teerath mo karyo karat isnaanaa |","meaning_en":"","page":876},{"gurmukhi":"ਧ੍ਯਾਨ ਬਿੜਾਲ ਬਕੀ ਬਕ ਲਾਵਤ ਤਿਨ ਕਿਆ ਜੋਗੁ ਪਛਾਨਾ।","roman":"Dhyaan biraal bakee bak laavat tin kiaa jogu pachhaanaa |","meaning_en":"","page":876},{"gurmukhi":"ਜੈਸੇ ਕਸਟ ਠਗਨ ਕਰ ਠਾਟਤ ਐਸੇ ਹਰਿ ਹਿਤ ਕੀਜੈ।","roman":"Jaise kasat thagan kar thaatat aise hari hit keejai |","meaning_en":"","page":876},{"gurmukhi":"ਤਬ ਹੀ ਮਹਾ ਗ੍ਯਾਨ ਕੋ ਜਾਨੈ ਪਰਮ ਪਯੂਖਹਿ ਪੀਜੈ। ੯੮।","roman":"Tab hee mahaa gyaan ko jaanai param payookhhi peejai | 98 |","meaning_en":"","page":876}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"","page":876},{"type":"verse","number":[99],"number_text":"੯੯।","page":876,"lines":[{"gurmukhi":"ਸੁਨਿ ਸੁਨਿ ਐਸੇ ਬਚਨ ਸਿਯਾਨੇ।","roman":"Suni suni aise bachan siyaane |","meaning_en":"","page":876},{"gurmukhi":"ਉਠਿ ਉਠਿ ਮਹਾ ਬੀਰ ਪਾਰਸ ਕੇ ਪਾਇਨ ਸੋ ਲਪਟਾਨੇ।","roman":"Uthi uthi mahaa beer paaras ke paain so laptaane |","meaning_en":"","page":876},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਮੂੜ ਅਗਿਆਨੀ ਤਿਨ ਤਿਨ ਬੈਨ ਨ ਮਾਨੇ।","roman":"Je je hute moor agiaanee tin tin bain na maane |","meaning_en":"","page":876},{"gurmukhi":"ਉਠਿ ਉਠਿ ਲਗੇ ਕਰਨ ਬਕਬਾਦਹ ਮੂਰਖ ਮੁਗਧ ਇਆਨੇ।","roman":"Uthi uthi lage karan bakbaadah moorakh mugadh iaane |","meaning_en":"","page":876},{"gurmukhi":"ਉਠਿ ਉਠਿ ਭਜੇ ਕਿਤੇ ਕਾਨਨ ਕੋ ਕੇਤਕਿ ਜਲਹਿ ਸਮਾਨੇ।","roman":"Uthi uthi bhaje kite kaanan ko ketki jalhi samaane |","meaning_en":"","page":876},{"gurmukhi":"ਕੇਤਕ ਭਏ ਜੁਧ ਕਹਿ ਪ੍ਰਾਪਤਿ ਸੁਨਤ ਸਬਦੁ ਘਹਰਾਨੇ।","roman":"Ketak bhae judh kahi praapti sunat sabdu ghahraane |","meaning_en":"","page":876},{"gurmukhi":"ਕੇਤਕ ਆਨਿ ਆਨਿ ਸਨਮੁਖਿ ਭਏ ਕੇਤਕ ਛੋਰਿ ਪਰਾਨੇ।","roman":"Ketak aani aani sanmukhi bhae ketak chhori paraane |","meaning_en":"","page":876},{"gurmukhi":"ਕੇਤਕ ਜੂਝਿ ਸੋਭੇ ਰਣ ਮੰਡਲ ਬਾਸਵ ਲੋਕਿ ਸਿਧਾਨੇ। ੯੯।","roman":"Ketak joojhi sobhe ran mandal baasav loki sidhaane | 99 |","meaning_en":"","page":876}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਤਿਲੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਤਿਲੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Bisanpad | tilang | tvaprasaadi kathtaa","meaning_en":"","page":876,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ"},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":876,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਸੰਖ ਸਬਦ ਘਹਰਾਏ।","roman":"Jab hee sankh sabad ghahraae |","meaning_en":"","page":876},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਸੂਰ ਜਟਧਾਰੀ ਤਿਨ ਤਿਨ ਤੁਰੰਗ ਨਚਾਏ।","roman":"Je je hute soor jatdhaaree tin tin turang nachaae |","meaning_en":"","page":876},{"gurmukhi":"ਚਕ੍ਰਤ ਭਈ ਗਗਨ ਕੀ ਤਰੁਨੀ ਦੇਵ ਅਦੇਵ ਤ੍ਰਸਾਏ।","roman":"Chakrat bhaee gagan kee tarunee dev adev trasaae |","meaning_en":"","page":876},{"gurmukhi":"ਨਿਰਖਤ ਭਯੋ ਸੂਰ ਰਥ ਥੰਭਤ ਨੈਨ ਨਿਮੇਖ ਨ ਲਾਏ।","roman":"Nirkhat bhayo soor rath thanbhat nain nimekh na laae |","meaning_en":"","page":876},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਛਡੇ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Sasatr asatr naanaa bidhi chhade baan prayogh chalaae |","meaning_en":"","page":876},{"gurmukhi":"ਮਾਨਹੁ ਮਾਹ ਮੇਘ ਬੂੰਦਨ ਜ੍ਯੋਂ ਬਾਣ ਬ੍ਯੂਹ ਬਰਸਾਏ।","roman":"Maanhu maah megh boondan jyon baan byooh barsaae |","meaning_en":"","page":876},{"gurmukhi":"ਚਟਪਟ ਚਰਮ ਬਰਮ ਪਰ ਚਟਕੇ ਦਾਝਤ ਤ੍ਰਿਣਾ ਲਜਾਏ।","roman":"Chatpat charam baram par chatke daajhat trinaa lajaae |","meaning_en":"","page":876},{"gurmukhi":"ਸ੍ਰੋਣਤ ਭਰੇ ਬਸਤ੍ਰ ਸੋਭਿਤ ਜਨੁ ਚਾਚਰ ਖੇਲਿ ਸਿਧਾਏ। ੧੦੦।","roman":"Sronat bhare basatr sobhit janu chaachar kheli sidhaae | 100 |","meaning_en":"","page":876}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਿਦਾਰਾ","gurmukhi":"ਬਿਸਨਪਦ। ਕਿਦਾਰਾ","roman":"Bisanpad | kidaaraa","meaning_en":"","page":876},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":876,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਆਹਵ ਘੋਰ।","roman":"Ih bidhi bhayo aahav ghor |","meaning_en":"","page":876},{"gurmukhi":"ਭਾਪਿ ਭਾਤਿ ਗਿਰੇ ਧਰਾ ਪਰ ਸੂਰ ਸੁੰਦਰ ਕਿਸੋਰ।","roman":"Bhaapi bhaati gire dharaa par soor sundar kisor |","meaning_en":"","page":876},{"gurmukhi":"ਕੋਪ ਕੋਪ ਹਠੀ ਘਟੀ ਰਣਿ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਚਲਾਇ।","roman":"Kop kop hathee ghatee rani sasatr asatr chalaai |","meaning_en":"","page":876},{"gurmukhi":"ਜੂਝਿ ਜੂਝਿ ਗਏ ਦਿਵਾਲਯ ਢੋਲ ਬੋਲ ਬਜਾਇ।","roman":"Joojhi joojhi gae divaalay dhol bol bajaai |","meaning_en":"","page":876},{"gurmukhi":"ਹਾਇ ਹਾਇ ਭਈ ਜਹਾ ਤਹ ਭਾਜਿ ਭਾਜਿ ਸੁ ਬੀਰ।","roman":"Haai haai bhaee jahaa tah bhaaji bhaaji su beer |","meaning_en":"","page":876},{"gurmukhi":"ਪੈਠਿ ਪੈਠਿ ਗਏ ਤ੍ਰੀਆਲੈ ਹਾਰਿ ਹਾਰਿ ਅਧੀਰ।","roman":"Paithi paithi gae treeaalai haari haari adheer |","meaning_en":"","page":877},{"gurmukhi":"ਅਪ੍ਰਮਾਨ ਛੁਟੇ ਸਰਾਨ ਦਿਸਾਨ ਭਯੋ ਅੰਧਿਆਰ।","roman":"Apramaan chhute saraan disaan bhayo andhiaar |","meaning_en":"","page":877},{"gurmukhi":"ਟੂਕ ਟੂਕ ਪਰੇ ਜਹਾ ਤਹ ਮਾਰਿ ਮਾਰਿ ਜੁਝਾਰ। ੧੦੧।","roman":"Took took pare jahaa tah maari maari jujhaar | 101 |","meaning_en":"","page":877}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਦੇਵਗੰਧਾਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਦੇਵਗੰਧਾਰੀ","roman":"Bisanpad | devgandhaaree","meaning_en":"","page":877},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":877,"lines":[{"gurmukhi":"ਮਾਰੂ ਸਬਦੁ ਸੁਹਾਵਨ ਬਾਜੈ।","roman":"Maaroo sabdu suhaavan baajai |","meaning_en":"","page":877},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਸੁਭਟ ਰਣਿ ਸੁੰਦਰ ਗਹਿ ਗਹਿ ਆਯੁਦ ਗਾਜੇ।","roman":"Je je hute subhat rani sundar gahi gahi aayud gaaje |","meaning_en":"","page":877},{"gurmukhi":"ਕਵਚ ਪਹਰਿ ਪਾਖਰ ਸੋ ਡਾਰੀ ਅਉਰੈ ਆਯੁਧ ਸਾਜੇ।","roman":"Kavach pahri paakhar so daaree aurai aayudh saaje |","meaning_en":"","page":877},{"gurmukhi":"ਭਰੇ ਗੁਮਾਨ ਸੁਭਟ ਸਿੰਘਨ ਜ੍ਯੋਂ ਆਹਵ ਭੂਮਿ ਬਿਰਾਜੇ।","roman":"Bhare gumaan subhat singhan jyon aahav bhoomi biraaje |","meaning_en":"","page":877},{"gurmukhi":"ਗਹਿ ਗਹਿ ਚਲੇ ਗਦਾ ਗਾਜੀ ਸਬ ਸੁਭਟ ਅਯੋਧਨ ਕਾਜੇ।","roman":"Gahi gahi chale gadaa gaajee sab subhat ayodhan kaaje |","meaning_en":"","page":877},{"gurmukhi":"ਆਹਵ ਭੂਮਿ ਸੂਰ ਅਸ ਸੋਭੇ ਨਿਰਖਿ ਇੰਦ੍ਰ ਦੁਤਿ ਲਾਜੇ।","roman":"Aahav bhoomi soor as sobhe nirkhi indr duti laaje |","meaning_en":"","page":877},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹੂਐ ਗਿਰੇ ਧਰਣਿ ਪਰ ਆਹਵ ਛੋਰਿ ਨ ਭਾਜੇ।","roman":"Took took hooai gire dharni par aahav chhori na bhaaje |","meaning_en":"","page":877},{"gurmukhi":"ਪ੍ਰਾਪਤਿ ਭਏ ਦੇਵ ਮੰਦਰ ਕਹੁ ਸਸਤ੍ਰਨ ਸੁਭਟ ਨਿਵਾਜੇ। ੧੦੨।","roman":"Praapti bhae dev mandar kahu sastran subhat nivaaje | 102 |","meaning_en":"","page":877}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਲਿਆਨ","gurmukhi":"ਬਿਸਨਪਦ। ਕਲਿਆਨ","roman":"Bisanpad | kaliaan","meaning_en":"","page":877},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":877,"lines":[{"gurmukhi":"ਦਹਦਿਸ ਧਾਵ ਭਏ ਜੁਝਾਰੇ।","roman":"Dahdis dhaav bhae jujhaare |","meaning_en":"","page":877},{"gurmukhi":"ਮੁਦਗਰ ਗੁਫਨ ਗੁਰਜ ਗੋਲਾਲੇ ਪਟਸਿ ਪਰਘ ਪ੍ਰਹਾਰੇ।","roman":"Mudgar guphan guraj golaale patsi paragh prahaare |","meaning_en":"","page":877},{"gurmukhi":"ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਸੁਭਟ ਰਨ ਮੰਡਲਿ ਜਾਨੁ ਬਸੰਤ ਖਿਲਾਰੇ।","roman":"Giri giri pare subhat ran mandli jaanu basant khilaare |","meaning_en":"","page":877},{"gurmukhi":"ਉਠਿ ਉਠਿ ਭਏ ਜੁਧ ਕਉ ਪ੍ਰਾਪਤਿ ਰੋਹ ਭਰੇ ਰਜਵਾਰੇ।","roman":"Uthi uthi bhae judh kau praapti roh bhare rajvaare |","meaning_en":"","page":877},{"gurmukhi":"ਭਖਿ ਭਖਿ ਬੀਰ ਪੀਸ ਦਾਤਨ ਕਹ ਰਣ ਮੰਡਲੀ ਹਕਾਰੇ।","roman":"Bhakhi bhakhi beer pees daatan kah ran mandlee hakaare |","meaning_en":"","page":877},{"gurmukhi":"ਬਰਛੀ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਜਾਇਧੁ ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਸੰਭਾਰੇ।","roman":"Barchhee baan kripaan gajaaidhu asatr sasatr sanbhaare |","meaning_en":"","page":877},{"gurmukhi":"ਭਸਮੀ ਭੂਤ ਭਏ ਗੰਧ੍ਰਬ ਗਣ ਦਾਝਤ ਦੇਵ ਪੁਕਾਰੇ।","roman":"Bhasmee bhoot bhae gandhrab gan daajhat dev pukaare |","meaning_en":"","page":877},{"gurmukhi":"ਹਮ ਮਤ ਮੰਦ ਚਰਣ ਸਰਣਾਗਤਿ ਕਾਹਿ ਨ ਲੇਤ ਉਬਾਰੇ। ੧੦੩।","roman":"Ham mat mand charan sarnaagti kaahi na let ubaare | 103 |","meaning_en":"","page":877}]},{"type":"heading","kind":"chhand","name":"ਮਾਰੂ","gurmukhi":"ਮਾਰੂ","roman":"Maaroo","meaning_en":"","page":877},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":877,"lines":[{"gurmukhi":"ਦੋਊ ਦਿਸ ਸੁਭਟ ਜਬੈ ਜੁਰਿ ਆਏ।","roman":"Do'oo dis subhat jabai juri aae |","meaning_en":"","page":877},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਮ੍ਰਿਦੰਗ ਬਜਤ ਸੁਨਿ ਸਾਵਨ ਮੇਘ ਲਜਾਏ।","roman":"Dundbhi dhol mridang bajat suni saavan megh lajaae |","meaning_en":"","page":877},{"gurmukhi":"ਦੇਖਨ ਦੇਵ ਅਦੇਵ ਮਹਾ ਹਵ ਚੜੇ ਬਿਮਾਨ ਸੁਹਾਏ।","roman":"Dekhan dev adev mahaa hav chare bimaan suhaae |","meaning_en":"","page":877},{"gurmukhi":"ਕੰਚਨ ਜਟਤ ਖਚੇ ਰਤਨਨ ਲਖਿ ਗੰਧ੍ਰਬ ਨਗਰ ਰਿਸਾਏ।","roman":"Kanchan jatat khache ratnan lakhi gandhrab nagar risaae |","meaning_en":"","page":877},{"gurmukhi":"ਕਾਛਿ ਕਛਿ ਕਾਛ ਕਛੇ ਕਛਨੀ ਚੜਿ ਕੋਪ ਭਰੇ ਨਿਜਕਾਏ।","roman":"Kaachhi kachhi kaachh kachhe kachhnee chari kop bhare nijkaae |","meaning_en":"","page":877},{"gurmukhi":"ਕੋਊ ਕੋਊ ਰਹੇ ਸੁਭਟ ਰਣ ਮੰਡਲਿ ਕੇਈ ਕੇਈ ਛਾਡਿ ਪਰਾਏ।","roman":"Ko'oo ko'oo rahe subhat ran mandli ke'ee ke'ee chhaadi paraae |","meaning_en":"","page":877},{"gurmukhi":"ਝਿਮਝਿਮ ਮਹਾ ਮੇਘ ਪਰਲੈ ਜ੍ਯੋਂ ਬ੍ਰਿੰਦ ਬਿਸਿਖ ਬਰਸਾਏ।","roman":"Jhimjhim mahaa megh parlai jyon brind bisikh barsaae |","meaning_en":"","page":877},{"gurmukhi":"ਐਸੋ ਨਿਰਖਿ ਬਡੇ ਕਵਤਕ ਕਹ ਪਾਰਸ ਆਪ ਸਿਧਾਏ। ੧੦੪।","roman":"Aiso nirkhi bade kavtak kah paaras aap sidhaae | 104 |","meaning_en":"","page":877}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਭੈਰੋ","gurmukhi":"ਬਿਸਨਪਦ। ਭੈਰੋ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | bhairo | tvaprasaadi","meaning_en":"","page":877,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":877,"lines":[{"gurmukhi":"ਦੈ ਰੇ ਦੈ ਰੇ ਦੀਹ ਦਮਾਮਾ।","roman":"Dai re dai re deeh damaamaa |","meaning_en":"","page":877},{"gurmukhi":"ਕਰਹੌ ਰੁੰਡ ਮੁੰਡ ਬਸੁਧਾ ਪਰ ਲਖਤ ਸ੍ਵਰਗ ਕੀ ਬਾਮਾ।","roman":"Karhau rund mund basudhaa par lakhat svarag kee baamaa |","meaning_en":"","page":877},{"gurmukhi":"ਧੁਕਿ ਧੁਕਿ ਪਰਹਿ ਧਰਣਿ ਭਾਰੀ ਭਟ ਬੀਰ ਬੈਤਾਲ ਰਜਾਊ।","roman":"Dhuki dhuki parhi dharni bhaaree bhat beer baitaal rajaaoo |","meaning_en":"","page":877},{"gurmukhi":"ਭੂਤ ਪਿਸਾਚ ਡਾਕਣੀ ਜੋਗਣ ਕਾਕਣ ਰੁਹਰ ਪਿਵਾਊ।","roman":"Bhoot pisaach daaknee jogan kaakan ruhar pivaaoo |","meaning_en":"","page":877},{"gurmukhi":"ਭਕਿ ਭਕਿ ਉਠੇ ਭੀਮ ਭੈਰੋ ਰਣਿ ਅਰਧ ਉਰਧ ਸੰਘਾਰੋ।","roman":"Bhaki bhaki uthe bheem bhairo rani aradh uradh sanghaaro |","meaning_en":"","page":878},{"gurmukhi":"ਇੰਦ੍ਰ ਚੰਦ ਸੂਰਜ ਬਰਣਾਦਿਕ ਆਜ ਸਭੈ ਚੁਨਿ ਮਾਰੋ।","roman":"Indr chand sooraj barnaadik aaj sabhai chuni maaro |","meaning_en":"","page":878},{"gurmukhi":"ਮੋਹਿ ਬਰ ਦਾਨ ਦੇਵਤਾ ਦੀਨਾ ਜਿਹ ਸਰਿ ਅਉਰ ਨ ਕੋਈ।","roman":"Mohi bar daan devtaa deenaa jih sari aur na koee |","meaning_en":"","page":878},{"gurmukhi":"ਮੈ ਹੀ ਭਯੋ ਜਗਤ ਕੋ ਕਰਤਾ ਜੋ ਮੈ ਕਰੌ ਸੁ ਹੋਈ। ੧੦੫।","roman":"Mai hee bhayo jagat ko kartaa jo mai karau su hoee | 105 |","meaning_en":"","page":878}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਗਉਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਗਉਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Bisanpad | gauree | tvaprasaadi kathtaa","meaning_en":"","page":878,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ"},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":878,"lines":[{"gurmukhi":"ਮੋ ਤੇ ਆਉਰ ਬਲੀ ਕੋ ਹੈ।","roman":"Mo te aaur balee ko hai |","meaning_en":"","page":878},{"gurmukhi":"ਜਉਨ ਮੋ ਤੇ ਜੰਗ ਜੀਤੇ ਜੁਧ ਮੈ ਕਰ ਜੈ।","roman":"Jaun mo te jang jeete judh mai kar jai |","meaning_en":"","page":878},{"gurmukhi":"ਇੰਦ੍ਰ ਚੰਦ ਉਪਿੰਦ੍ਰ ਕੌ ਪਲ ਮਧਿ ਜੀਤੌ ਜਾਇ।","roman":"Indr chand upindr kau pal madhi jeetau jaai |","meaning_en":"","page":878},{"gurmukhi":"ਅਉਰ ਐਸੋ ਕੋ ਭਯੋ ਰਣ ਮਧਿ ਜੀਤੇ ਆਇ।","roman":"Aur aiso ko bhayo ran madhi jeete aai |","meaning_en":"","page":878},{"gurmukhi":"ਸਾਤ ਸਿੰਧ ਸੁਕਾਇ ਡਾਰੋ ਨੈਕੁ ਰੋਸੁ ਕਰੋ।","roman":"Saat sindh sukaai daaro naiku rosu karo |","meaning_en":"","page":878},{"gurmukhi":"ਜਛ ਗੰਧ੍ਰਬ ਕਿੰਨ੍ਰ ਕੋਰ ਕਰੋਰ ਮੋਰਿ ਧਰੋ।","roman":"Jachh gandhrab kinnr kor karor mori dharo |","meaning_en":"","page":878},{"gurmukhi":"ਦੇਵ ਔਰ ਅਦੇਵ ਜੀਤੇ ਕਰੇ ਸਬੈ ਗੁਲਾਮ।","roman":"Dev aur adev jeete kare sabai gulaam |","meaning_en":"","page":878},{"gurmukhi":"ਦਿਬ ਦਾਨ ਦਯੋ ਮੁਝੈ ਛੁਐ ਸਕੈ ਕੋ ਮੁਹਿ ਛਾਮ।੧੦੬।","roman":"Dib daan dayo mujhai chhuai sakai ko muhi chhaam | 106 |","meaning_en":"","page":878}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਮਾਰੂ","gurmukhi":"ਬਿਸਨਪਦ। ਮਾਰੂ","roman":"Bisanpad | maaroo","meaning_en":"","page":878},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":878,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਪਾਰਸ ਰੋਸ ਬਢਾਯੋ।","roman":"Yau kahi paaras ros badhaayo |","meaning_en":"","page":878},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਬਜਾਇ ਮਹਾ ਧੁਨਿ ਸਾਮੁਹਿ ਸੰਨ੍ਯਾਸਨਿ ਧਾਯੋ।","roman":"Dundbhi dhol bajaai mahaa dhuni saamuhi sannyaasni dhaayo |","meaning_en":"","page":878},{"gurmukhi":"ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਛਡੈ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Asatr sasatr naanaa bidhi chhadai baan prayogh chalaae |","meaning_en":"","page":878},{"gurmukhi":"ਸੁਭਟ ਸਨਾਹਿ ਪਤ੍ਰ ਚਲਦਲ ਜ੍ਯੋਂ ਬਾਨਨ ਬੇਧਿ ਉਡਾਏ।","roman":"Subhat sanaahi patr chaldal jyon baanan bedhi udaae |","meaning_en":"","page":878},{"gurmukhi":"ਦੁਹਦਿਸ ਬਾਨ ਪਾਨ ਤੇ ਛੂਟੇ ਦਿਨਪਤਿ ਦੇਹ ਦੁਰਾਨਾ।","roman":"Duhdis baan paan te chhoote dinapti deh duraanaa |","meaning_en":"","page":878},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਏਕ ਜਨੁ ਹੁਐ ਗਏ ਚਾਲ ਚਹੂੰ ਚਕ ਮਾਨਾ।","roman":"Bhoomi akaas ek janu huai gae chaal chahoon chak maanaa |","meaning_en":"","page":878},{"gurmukhi":"ਇੰਦਰ ਚੰਦ੍ਰ ਮੁਨਿਵਰ ਸਬ ਕਾਪੇ ਬਸੁ ਦਿਗਿਪਾਲ ਡਰਾਨੀਯ।","roman":"Indar chandr munivar sab kaape basu digipaal daraaneey |","meaning_en":"","page":878},{"gurmukhi":"ਬਰਨ ਕੁਬੇਰ ਛਾਡਿ ਪੁਰ ਭਾਜੇ ਦੁਤੀਯ ਪ੍ਰਲੈ ਕਰਿ ਮਾਨੀਯ। ੧੦੭।","roman":"Baran kuber chhaadi pur bhaaje duteey pralai kari maaneey | 107 |","meaning_en":"","page":878}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਮਾਰੂ","gurmukhi":"ਬਿਸਨਪਦ। ਮਾਰੂ","roman":"Bisanpad | maaroo","meaning_en":"","page":878},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":878,"lines":[{"gurmukhi":"ਸੁਰਪੁਰ ਨਾਰਿ ਬਧਾਵਾ ਮਾਨਾ।","roman":"Surpur naari badhaavaa maanaa |","meaning_en":"","page":878},{"gurmukhi":"ਬਰਿ ਹੈ ਆਜ ਮਹਾ ਸੁਭਟਨ ਕੌ ਸਮਰ ਸੁਯੰਬਰ ਜਾਨਾ।","roman":"Bari hai aaj mahaa subhtan kau samar suyanbar jaanaa |","meaning_en":"","page":878},{"gurmukhi":"ਲਖਿ ਹੈ ਏਕ ਪਾਇ ਠਢੀ ਹਮ ਜਿਮ ਜਿਮ ਸੁਭਟ ਜੁਝੈ ਹੈ।","roman":"Lakhi hai ek paai thadhee ham jim jim subhat jujhai hai |","meaning_en":"","page":878},{"gurmukhi":"ਤਿਮ ਤਿਮ ਘਾਲਿ ਪਾਲਕੀ ਆਪਨ ਅਮਰਪੁਰੀ ਲੈ ਜੈ ਹੈ।","roman":"Tim tim ghaali paalkee aapan amarpuree lai jai hai |","meaning_en":"","page":878},{"gurmukhi":"ਚੰਦਨ ਚਾਰੁ ਚਿਤ੍ਰ ਚੰਦਨ ਕੇ ਚੰਚਲ ਅੰਗ ਚੜਾਊ।","roman":"Chandan chaaru chitr chandan ke chanchal ang charaaoo |","meaning_en":"","page":878},{"gurmukhi":"ਜਾ ਦਿਨ ਸਮਰ ਸੁਅੰਬਰ ਕਰਿ ਕੈ ਪਰਮ ਪਿਅਰ ਵਹਿ ਪਾਊ।","roman":"Jaa din samar suanbar kari kai param piar vahi paaoo |","meaning_en":"","page":878},{"gurmukhi":"ਤਾ ਦਿਨ ਦੇਹ ਸਫਲ ਕਰਿ ਮਾਨੋ ਅੰਗ ਸੀਗਾਰ ਧਰੋ।","roman":"Taa din deh saphal kari maano ang seegaar dharo |","meaning_en":"","page":878},{"gurmukhi":"ਜਾ ਦਿਨ ਸਮਰ ਸੁਯੰਬਰ ਸਖੀ ਰੀ ਪਾਰਸ ਨਾਥ ਬਰੋ। ੧੦੮।","roman":"Jaa din samar suyanbar sakhee ree paaras naath baro | 108 |","meaning_en":"","page":878}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"","page":878},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":878,"lines":[{"gurmukhi":"ਚਹੁ ਦਿਸ ਮਾਰੂ ਸਬਦ ਬਜੇ।","roman":"Chahu dis maaroo sabad baje |","meaning_en":"","page":878},{"gurmukhi":"ਗਹਿ ਗਹਿ ਗਦਾ ਗੁਰਜ ਗਾਜੀ ਸਬ ਹਠਿ ਰਣਿ ਆਨਿ ਗਜੇ।","roman":"Gahi gahi gadaa guraj gaajee sab hathi rani aani gaje |","meaning_en":"","page":879},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਸੈਹਥੀ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Baan kamaan kripaan saihthee baan prayogh chalaae |","meaning_en":"","page":879},{"gurmukhi":"ਜਾਨੁਕ ਮਹਾ ਮੇਘ ਬੂੰਦਨ ਜ੍ਯੋਂ ਬਿਸਿਖ ਬ੍ਯੂਹਿ ਬਰਸਾਏ।","roman":"Jaanuk mahaa megh boondan jyon bisikh byoohi barsaae |","meaning_en":"","page":879},{"gurmukhi":"ਚਟਪਟ ਚਰਮ ਬਰਮ ਸਬ ਬੇਧੇ ਸਟਪਟ ਪਾਰ ਪਰਾਨੇ।","roman":"Chatpat charam baram sab bedhe satpat paar paraane |","meaning_en":"","page":879},{"gurmukhi":"ਖਟਪਟ ਸਰਬ ਭੂਮਿ ਕੇ ਬੇਧੇ ਨਾਗਨ ਲੋਕ ਸਿਧਾਨੇ।","roman":"Khatpat sarab bhoomi ke bedhe naagan lok sidhaane |","meaning_en":"","page":879},{"gurmukhi":"ਝਮਕਤ ਖੜਗ ਕਾਢਿ ਨਾਨਾ ਬਿਧਿ ਸੈਹਥੀ ਸੁਭਟ ਚਲਾਵਤ।","roman":"Jhamkat kharag kaadhi naanaa bidhi saihthee subhat chalaavat |","meaning_en":"","page":879},{"gurmukhi":"ਜਾਨੁਕ ਪ੍ਰਗਟ ਬਾਟ ਸੁਰ ਪੁਰ ਕੀ ਨੀਕੇ ਹਿਰਦੇ ਦਿਖਾਵਤ। ੧੦੯।","roman":"Jaanuk pragat baat sur pur kee neeke hirde dikhaavat | 109 |","meaning_en":"","page":879}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":879},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":879,"lines":[{"gurmukhi":"ਬਾਨਨ ਬੇਧੇ ਅਮਿਤ ਸੰਨਿਆਸੀ।","roman":"Baanan bedhe amit sanniaasee |","meaning_en":"","page":879},{"gurmukhi":"ਤੇ ਤਜ ਦੇਹ ਨੇਹ ਸੰਪਤਿ ਕੋ ਭਏ ਸੁਰਗ ਕੇ ਬਾਸੀ।","roman":"Te taj deh neh sanpti ko bhae surag ke baasee |","meaning_en":"","page":879},{"gurmukhi":"ਚਰਮ ਬਰਮ ਰਥ ਧੁਜਾ ਪਤਾਕਾ ਬਹੁ ਬਿਧਿ ਕਾਟਿ ਗਿਰਾਏ।","roman":"Charam baram rath dhujaa pataakaa bahu bidhi kaati giraae |","meaning_en":"","page":879},{"gurmukhi":"ਸੋਭਤ ਭਏ ਇੰਦ੍ਰ ਪੁਰ ਜਮ ਪੁਰ ਸੁਰ ਪੁਰ ਨਿਰਖ ਲਜਾਏ।","roman":"Sobhat bhae indr pur jam pur sur pur nirakh lajaae |","meaning_en":"","page":879},{"gurmukhi":"ਭੂਖਨ ਬਸਤ੍ਰ ਰੰਗ ਰੰਗਨ ਕੇ ਛੁਟਿ ਛੁਟਿ ਭੂਮਿ ਗਿਰੇ।","roman":"Bhookhan basatr rang rangan ke chhuti chhuti bhoomi gire |","meaning_en":"","page":879},{"gurmukhi":"ਜਨੁਕ ਅਸੋਕ ਬਾਗ ਦਿਵਪਤਿ ਕੇ ਪੁਹਪ ਬਸੰਤਿ ਝਰੇ।","roman":"Januk asok baag divapti ke puhap basanti jhare |","meaning_en":"","page":879},{"gurmukhi":"ਕਟਿ ਕਟਿ ਗਿਰੇ ਗਜਨ ਕੁੰਭ ਸਥਲ ਮੁਕਤਾ ਬਿਥੁਰਿ ਪਰੇ।","roman":"Kati kati gire gajan kunbh sathal muktaa bithuri pare |","meaning_en":"","page":879},{"gurmukhi":"ਜਾਨੁਕ ਅੰਮ੍ਰਿਤ ਕੁੰਡ ਮੁਖ ਛੁਟੈ ਜਲ ਕਨ ਸੁਭਗ ਝਰੇ। ੧੧੦।","roman":"Jaanuk anmrit kund mukh chhutai jal kan subhag jhare | 110 |","meaning_en":"","page":879}]},{"type":"heading","kind":"chhand","name":"ਦੇਵ ਗੰਧਾਰੀ। ਦੂਜੀ ਤਰਹ","gurmukhi":"ਦੇਵ ਗੰਧਾਰੀ। ਦੂਜੀ ਤਰਹ","roman":"Dev gandhaaree | doojee tarah","meaning_en":"","page":879},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":879,"lines":[{"gurmukhi":"ਦੁਹ ਦਿਸ ਪਰੇ ਬੀਰ ਹਕਾਰਿ।","roman":"Duh dis pare beer hakaari |","meaning_en":"","page":879},{"gurmukhi":"ਕਾਢਿ ਕਾਢਿ ਕ੍ਰਿਪਾਣ ਧਾਵਤ ਮਾਰੁ ਮਾਰੁ ਉਚਾਰਿ।","roman":"Kaadhi kaadhi kripaan dhaavat maaru maaru uchaari |","meaning_en":"","page":879},{"gurmukhi":"ਪਾਨ ਰੋਕਿ ਸਰੋਖ ਰਾਵਤ ਕ੍ਰੁਧ ਜੁਧ ਫਿਰੇ।","roman":"Paan roki sarokh raavat krudh judh phire |","meaning_en":"","page":879,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਗਾਹਿ ਗਾਹਿ ਗਜੀ ਰਥੀ ਰਣਿ ਅੰਤਿ ਭੂਮਿ ਗਿਰੇ।","roman":"Gaahi gaahi gajee rathee rani anti bhoomi gire |","meaning_en":"","page":879},{"gurmukhi":"ਤਾਨਿ ਤਾਨਿ ਸੰਧਾਨ ਬਾਨ ਪ੍ਰਮਾਨ ਕਾਨ ਸੁਬਾਹਿ।","roman":"Taani taani sandhaan baan pramaan kaan subaahi |","meaning_en":"","page":879},{"gurmukhi":"ਬਾਹਿ ਬਾਹਿ ਫਿਰੇ ਸੁਬਾਹਨ ਛਤ੍ਰ ਧਰਮ ਨਿਬਾਹਿ।","roman":"Baahi baahi phire subaahan chhatr dharam nibaahi |","meaning_en":"","page":879},{"gurmukhi":"ਬੇਧਿ ਬੇਧਿ ਸੁ ਬਾਨ ਅੰਗ ਜੁਆਨ ਜੁਝੇ ਐਸ।","roman":"Bedhi bedhi su baan ang juaan jujhe ais |","meaning_en":"","page":879},{"gurmukhi":"ਭੂਰਿ ਭਾਰਥ ਕੇ ਸਮੇ ਸਰ ਸੇਜ ਭੀਖਮ ਜੈਸ। ੧੧੧।","roman":"Bhoori bhaarath ke same sar sej bheekham jais | 111 |","meaning_en":"","page":879}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"","page":879},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":879,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਬਹੁਤੁ ਸੰਨਿਆਸੀ ਮਾਰੇ।","roman":"Ih bidhi bahutu sanniaasee maare |","meaning_en":"","page":879},{"gurmukhi":"ਕੇਤਿਕ ਬਾਧਿ ਬਾਰਿ ਮੋ ਬੋਰੇ ਕਿਤੇ ਅਗਨਿ ਮੋ ਸਾਰੇ।","roman":"Ketik baadhi baari mo bore kite agni mo saare |","meaning_en":"","page":879},{"gurmukhi":"ਕੇਤਨ ਏਕ ਹਾਥ ਕਟਿ ਡਾਰੇ ਕੇਤਿਨ ਕੇ ਦ੍ਵੈ ਹਾਥ।","roman":"Ketan ek haath kati daare ketin ke dvai haath |","meaning_en":"","page":879},{"gurmukhi":"ਤਿਲ ਤਿਲ ਪਾਇ ਰਥੀ ਕਟਿ ਡਾਰੇ ਕਟੇ ਕਿਤਨ ਕੇ ਮਾਥ।","roman":"Til til paai rathee kati daare kate kitan ke maath |","meaning_en":"","page":879},{"gurmukhi":"ਛਤ੍ਰ ਚਮ੍ਰ ਰਥ ਬਾਜ ਕਿਤਨੇ ਕੇ ਕਾਟਿ ਕਾਟਿ ਰਣਿ ਡਾਰੇ।","roman":"Chhatr chamr rath baaj kitne ke kaati kaati rani daare |","meaning_en":"","page":879},{"gurmukhi":"ਕੇਤਨ ਮੁਕਟ ਲਕੁਟ ਲੈ ਤੋਰੇ ਕੇਤਨ ਜੂਟ ਉਪਾਰੇ।","roman":"Ketan mukat lakut lai tore ketan joot upaare |","meaning_en":"","page":879},{"gurmukhi":"ਭਕਿ ਭਕਿ ਗਿਰੇ ਭਿੰਭਰ ਬਸੁਧਾ ਪਰ ਘਾਇ ਅੰਗ ਭਿਭਰਾਰੇ।","roman":"Bhaki bhaki gire bhinbhar basudhaa par ghaai ang bhibhraare |","meaning_en":"","page":879},{"gurmukhi":"ਜਾਨੁਕ ਅੰਤ ਬਸੰਤ ਸਮੈ ਮਿਲਿ ਚਾਚਰ ਖੇਲ ਸਿਧਾਰੇ। ੧੧੨।","roman":"Jaanuk ant basant samai mili chaachar khel sidhaare | 112 |","meaning_en":"","page":879}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਅਡਾਨ","gurmukhi":"ਬਿਸਨਪਦ। ਅਡਾਨ","roman":"Bisanpad | adaan","meaning_en":"","page":880},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":880,"lines":[{"gurmukhi":"ਚੁਪਰੇ ਚਾਰੁ ਚਿਕਨੇ ਕੇਸ।","roman":"Chupre chaaru chikne kes |","meaning_en":"","page":880},{"gurmukhi":"ਆਨਿ ਆਨਿ ਫਿਰੀ ਚਹੂੰ ਦਿਸਿ ਨਾਰਿ ਨਾਗਰਿ ਭੇਸ।","roman":"Aani aani phiree chahoon disi naari naagri bhes |","meaning_en":"","page":880},{"gurmukhi":"ਚਿਬਕ ਚਾਰੁ ਸੁ ਧਾਰ ਬੇਸਰ ਡਾਰਿ ਕਾਜਰ ਨੈਨ।","roman":"Chibak chaaru su dhaar besar daari kaajar nain |","meaning_en":"","page":880},{"gurmukhi":"ਜੀਵ ਜੰਤਨ ਕਾ ਚਲੀ ਚਿਤ ਲੇਤ ਚੋਰ ਸੁ ਮੈਨ।","roman":"Jeev jantan kaa chalee chit let chor su main |","meaning_en":"","page":880},{"gurmukhi":"ਦੇਖ ਰੀ ਸੁਕੁਮਾਰ ਸੁੰਦਰ ਆਜੁ ਬਰ ਹੈ ਬੀਰ।","roman":"Dekh ree sukumaar sundar aaju bar hai beer |","meaning_en":"","page":880},{"gurmukhi":"ਬੀਨ ਬੀਨ ਧਰੋ ਸਬੰਗਨ ਸੁਧ ਕੇਸਰਿ ਚੀਰ।","roman":"Been been dharo sabangan sudh kesri cheer |","meaning_en":"","page":880},{"gurmukhi":"ਚੀਨ ਚੀਨ ਬਰਿ ਹੈ ਸੁਬਾਹ ਸੁ ਮਧ ਜੁਧ ਉਛਾਹ।","roman":"Cheen cheen bari hai subaah su madh judh uchhaah |","meaning_en":"","page":880},{"gurmukhi":"ਤੇਗ ਤੀਰਨ ਬਾਨ ਬਰਛਨ ਜੀਤ ਕਰਿ ਹੈ ਬਯਾਹ। ੧੧੩।","roman":"Teg teeran baan barchhan jeet kari hai bayaah | 113 |","meaning_en":"","page":880}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":880},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":880,"lines":[{"gurmukhi":"ਕਹਾ ਲੌ ਉਪਮਾ ਇਤੀ ਕਰੌ।","roman":"Kahaa lau upmaa itee karau |","meaning_en":"","page":880},{"gurmukhi":"ਗ੍ਰੰਥ ਬਢਨ ਕੇ ਕਾਜ ਸੁਨਹੁ ਜੂ ਚਿਤ ਮੈ ਅਧਿਕ ਡਰੌ।","roman":"Granth badhan ke kaaj sunhu joo chit mai adhik darau |","meaning_en":"","page":880},{"gurmukhi":"ਤਉ ਸੁਧਾਰਿ ਬਿਚਾਰ ਕਥਾ ਕਹਿ ਕਹਿ ਸੰਛੇਪ ਬਖਾਨੋ।","roman":"Tau sudhaari bichaar kathaa kahi kahi sanchhep bakhaano |","meaning_en":"","page":880},{"gurmukhi":"ਜੈਸੇ ਤਵ ਪ੍ਰਤਾਪ ਕੇ ਬਲ ਤੇ ਜਥਾ ਸਕਤਿ ਅਨੁਮਾਨੋ।","roman":"Jaise tav prataap ke bal te jathaa sakti anumaano |","meaning_en":"","page":880},{"gurmukhi":"ਜਬ ਪਾਰਸ ਇਹ ਬਿਧਿ ਰਨ ਮੰਡ੍ਯੋ ਨਾਨਾ ਸਸਤ੍ਰ ਚਲਾਏ।","roman":"Jab paaras ih bidhi ran mandyo naanaa sasatr chalaae |","meaning_en":"","page":880},{"gurmukhi":"ਹਤੇ ਸੁ ਹਤੇ ਜੀਅ ਲੈ ਭਾਜੇ ਚਹੁੰ ਦਿਸ ਗਏ ਪਰਾਏ।","roman":"Hate su hate jeea lai bhaaje chahun dis gae paraae |","meaning_en":"","page":880},{"gurmukhi":"ਜੇ ਹਠ ਤਿਆਗਿ ਆਨਿ ਪਗ ਲਾਗੇ ਤੇ ਸਬ ਲਏ ਬਚਾਈ।","roman":"Je hath tiaagi aani pag laage te sab lae bachaaee |","meaning_en":"","page":880},{"gurmukhi":"ਭੂਖਨ ਬਸਨ ਬਹੁਤੁ ਬਿਧਿ ਦੀਨੇ ਦੈ ਦੈ ਬਹੁਤ ਬਡਾਈ। ੧੧੪।","roman":"Bhookhan basan bahutu bidhi deene dai dai bahut badaaee | 114 |","meaning_en":"","page":880}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"","page":880},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":880,"lines":[{"gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਡੋ ਰਣ ਪਾਰ੍ਯੋ।","roman":"Paaras naath bado ran paaryo |","meaning_en":"","page":880},{"gurmukhi":"ਆਪਨ ਪ੍ਰਚੁਰ ਜਗਤ ਮਤੁ ਕੀਨਾ ਦੇਵਦਤ ਕੋ ਟਾਰ੍ਯੋ।","roman":"Aapan prachur jagat matu keenaa devdat ko taaryo |","meaning_en":"","page":880},{"gurmukhi":"ਲੈ ਲੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਭਾਤਿ ਅਨਿਕ ਅਰਿ ਮਾਰੇ।","roman":"Lai lai sasatr asatr naanaa bidhi bhaati anik ari maare |","meaning_en":"","page":880},{"gurmukhi":"ਜੀਤੇ ਪਰਮ ਪੁਰਖ ਪਾਰਸ ਕੇ ਸਗਲ ਜਟਾ ਧਰ ਹਾਰੇ।","roman":"Jeete param purakh paaras ke sagal jataa dhar haare |","meaning_en":"","page":880},{"gurmukhi":"ਬੇਖ ਬੇਖ ਭਟ ਪਰੇ ਧਰਨ ਗਿਰਿ ਬਾਣ ਪ੍ਰਯੋਘਨ ਘਾਏ।","roman":"Bekh bekh bhat pare dharan giri baan prayoghan ghaae |","meaning_en":"","page":880},{"gurmukhi":"ਜਾਨੁਕ ਪਰਮ ਲੋਕ ਪਾਵਨ ਕਹੁ ਪ੍ਰਾਨਨ ਪੰਖ ਲਗਾਏ।","roman":"Jaanuk param lok paavan kahu praanan pankh lagaae |","meaning_en":"","page":880},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹ੍ਵੈ ਗਿਰੇ ਕਵਚ ਕਟਿ ਪਰਮ ਪ੍ਰਭਾ ਕਹੁ ਪਾਈ।","roman":"Took took hvai gire kavach kati param prabhaa kahu paaee |","meaning_en":"","page":880},{"gurmukhi":"ਜਣੁ ਦੈ ਚਲੇ ਨਿਸਾਣ ਸੁਰਗ ਕਹ ਕੁਲਹਿ ਕਲੰਕ ਮਿਟਾਈ। ੧੧੫।","roman":"Janu dai chale nisaan surag kah kulhi kalank mitaaee | 115 |","meaning_en":"","page":880}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੂਹੀ","gurmukhi":"ਬਿਸਨਪਦ। ਸੂਹੀ","roman":"Bisanpad | soohee","meaning_en":"","page":880},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":880,"lines":[{"gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਡੋ ਰਣ ਜੀਤੋ।","roman":"Paaras naath bado ran jeeto |","meaning_en":"","page":880},{"gurmukhi":"ਜਾਨੁਕ ਭਈ ਦੂਸਰ ਕਰਣਾਰਜੁਨ ਭਾਰਥ ਸੋ ਹੁਇ ਬੀਤੋ।","roman":"Jaanuk bhaee doosar karnaarjun bhaarath so hui beeto |","meaning_en":"","page":880},{"gurmukhi":"ਬਹੁ ਬਿਧਿ ਚਲੈ ਪ੍ਰਵਾਹਿ ਸ੍ਰੋਣ ਕੇ ਰਥ ਗਜ ਅਸਵ ਬਹਾਏ।","roman":"Bahu bidhi chalai pravaahi sron ke rath gaj asav bahaae |","meaning_en":"","page":880},{"gurmukhi":"ਭੈ ਕਰ ਜਾਨ ਭਯੋ ਬਡ ਆਹਵ ਸਾਤ ਸਮੁੰਦਰ ਲਜਾਏ।","roman":"Bhai kar jaan bhayo bad aahav saat samundar lajaae |","meaning_en":"","page":880},{"gurmukhi":"ਜਹ ਤਹ ਚਲੇ ਭਾਜ ਸੰਨਿਆਸੀ ਬਾਣਨ ਅੰਗ ਪ੍ਰਹਾਰੇ।","roman":"Jah tah chale bhaaj sanniaasee baanan ang prahaare |","meaning_en":"","page":880},{"gurmukhi":"ਜਾਨੁਕ ਬਜ੍ਰ ਇੰਦ੍ਰ ਕੇ ਭੈ ਤੇ ਪਬ ਸਪਛ ਸਿਧਾਰੇ।","roman":"Jaanuk bajr indr ke bhai te pab sapachh sidhaare |","meaning_en":"","page":880},{"gurmukhi":"ਜਿਹ ਤਿਹ ਗਿਰਤ ਸ੍ਰੋਣ ਕੀ ਧਾਰਾ ਅਰਿ ਘੂਮਤ ਭਿਭਰਾਤ।","roman":"Jih tih girat sron kee dhaaraa ari ghoomat bhibhraat |","meaning_en":"","page":881},{"gurmukhi":"ਨਿੰਦਾ ਕਰਤ ਛਤ੍ਰੀਯ ਧਰਮ ਕੀ ਭਜਤ ਦਸੋ ਦਿਸ ਜਾਤ। ੧੧੬।","roman":"Nindaa karat chhatreey dharam kee bhajat daso dis jaat | 116 |","meaning_en":"","page":881}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"","page":881},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":881,"lines":[{"gurmukhi":"ਜੇਤਕ ਜੀਅਤ ਬਚੇ ਸੰਨ੍ਯਾਸੀ।","roman":"Jetak jeeat bache sannyaasee |","meaning_en":"","page":881},{"gurmukhi":"ਤ੍ਰਾਸ ਮਰਤ ਫਿਰਿ ਬਹੁਰਿ ਨ ਆਏ ਹੋਤ ਭਏ ਬਨਬਾਸੀ।","roman":"Traas marat phiri bahuri na aae hot bhae banbaasee |","meaning_en":"","page":881},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਢੂੰਢ ਬਨ ਬੇਹੜ ਤਹ ਤਹ ਪਕਰਿ ਸੰਘਾਰੇ।","roman":"Des bides dhoondh ban behar tah tah pakri sanghaare |","meaning_en":"","page":881},{"gurmukhi":"ਖੋਜਿ ਪਤਾਲ ਅਕਾਸ ਸੁਰਗ ਕਹੁ ਜਹਾ ਤਹਾ ਚੁਨਿ ਮਾਰੇ।","roman":"Khoji pataal akaas surag kahu jahaa tahaa chuni maare |","meaning_en":"","page":881},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਾਸ ਕਰੇ ਸੰਨਿਆਸੀ ਆਪਨ ਮਤਹ ਮਤਾਯੋ।","roman":"Ih bidhi naas kare sanniaasee aapan matah mataayo |","meaning_en":"","page":881},{"gurmukhi":"ਆਪਨ ਨ੍ਯਾਸ ਸਿਖਾਇ ਸਬਨ ਕਹੁ ਆਪਨ ਮੰਤ੍ਰ ਚਲਾਯੋ।","roman":"Aapan nyaas sikhaai saban kahu aapan mantr chalaayo |","meaning_en":"","page":881},{"gurmukhi":"ਜੇ ਜੇ ਗਹੇ ਤਿਨ ਤੇ ਘਾਇਲ ਤਿਨ ਕੀ ਜਟਾ ਮੁੰਡਾਈ।","roman":"Je je gahe tin te ghaail tin kee jataa mundaaee |","meaning_en":"","page":881},{"gurmukhi":"ਦੋਹੀ ਦੂਰ ਦਤ ਕੀ ਕੀਨੀ ਆਪਨ ਫੇਰਿ ਦੁਹਾਈ। ੧੧੭।","roman":"Dohee door dat kee keenee aapan pheri duhaaee | 117 |","meaning_en":"","page":881}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਬਸੰਤ","gurmukhi":"ਬਿਸਨਪਦ। ਬਸੰਤ","roman":"Bisanpad | basant","meaning_en":"","page":881},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":881,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਫਾਗ ਕ੍ਰਿਪਾਨਨ ਖੇਲੇ।","roman":"Ih bidhi phaag kripaanan khele |","meaning_en":"","page":881},{"gurmukhi":"ਸੋਭਤ ਢਾਲ ਮਾਲ ਡਫ ਮਾਲੈ ਮੂਠ ਗੁਲਾਲਨ ਸੇਲੇ।","roman":"Sobhat dhaal maal daph maalai mooth gulaalan sele |","meaning_en":"","page":881},{"gurmukhi":"ਜਾਨੁ ਤੁਫੰਗ ਭਰਤ ਪਿਚਕਾਰੀ ਸੂਰਨ ਅੰਗ ਲਗਾਵਤ।","roman":"Jaanu tuphang bharat pichkaaree sooran ang lagaavat |","meaning_en":"","page":881},{"gurmukhi":"ਨਿਕਸਤ ਸ੍ਰੋਣ ਅਧਿਕ ਛਬਿ ਉਪਜਤ ਕੇਸਰ ਜਾਨੁ ਸੁਹਾਵਤ।","roman":"Niksat sron adhik chhabi upjat kesar jaanu suhaavat |","meaning_en":"","page":881},{"gurmukhi":"ਸ੍ਰੋਣਤ ਭਰੀ ਜਟਾ ਅਤਿ ਸੋਭਤ ਛਬਹਿ ਨ ਜਾਤ ਕਹ੍ਯੋ।","roman":"Sronat bharee jataa ati sobhat chhabhi na jaat kahyo |","meaning_en":"","page":881},{"gurmukhi":"ਮਾਨਹੁ ਪਰਮ ਪ੍ਰੇਮ ਸੌ ਡਾਰ੍ਯੋ ਈਂਗਰ ਲਾਗਿ ਰਹ੍ਯੋ।","roman":"Maanhu param prem sau daaryo eengar laagi rahyo |","meaning_en":"","page":881},{"gurmukhi":"ਜਹ ਤਹ ਗਿਰਤ ਭਏ ਨਾਨਾ ਬਿਧਿ ਸਾਂਗਨ ਸਤ੍ਰੁ ਪਰੋਏ।","roman":"Jah tah girat bhae naanaa bidhi saangan satru paroe |","meaning_en":"","page":881},{"gurmukhi":"ਜਾਨੁਕ ਖੇਲ ਧਮਾਰ ਪਸਾਰਿ ਕੈ ਅਧਿਕ ਸ੍ਰਮਿਤ ਹ੍ਵੈ ਸੋਏ। ੧੧੮।","roman":"Jaanuk khel dhamaar pasaari kai adhik sramit hvai soe | 118 |","meaning_en":"","page":881}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"","page":881},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":881,"lines":[{"gurmukhi":"ਦਸ ਸੈ ਬਰਖ ਰਾਜ ਤਿਨ ਕੀਨਾ।","roman":"Das sai barakh raaj tin keenaa |","meaning_en":"","page":881},{"gurmukhi":"ਕੈ ਕੈ ਦੂਰ ਦਤ ਕੇ ਮਤ ਕਹੁ ਰਾਜ ਜੋਗ ਦੋਊ ਲੀਨਾ।","roman":"Kai kai door dat ke mat kahu raaj jog do'oo leenaa |","meaning_en":"","page":881},{"gurmukhi":"ਜੇ ਜੇ ਛਪੇ ਲੁਕੇ ਕਹੂੰ ਬਾਚੇ ਰਹਿ ਰਹਿ ਵਹੈ ਗਏ।","roman":"Je je chhape luke kahoon baache rahi rahi vahai gae |","meaning_en":"","page":881},{"gurmukhi":"ਐਸੇ ਏਕ ਨਾਮ ਲੈਬੇ ਕੋ ਜਗ ਮੋ ਰਹਤ ਭਏ।","roman":"Aise ek naam laibe ko jag mo rahat bhae |","meaning_en":"","page":881},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸੌ ਰਾਜ ਕਰਤ ਯੌ ਭਾਤਿ ਭਾਤਿ ਧਨ ਜੋਰ੍ਯੋ।","roman":"Bhaati bhaati sau raaj karat yau bhaati bhaati dhan joryo |","meaning_en":"","page":881},{"gurmukhi":"ਜਹਾ ਜਹਾ ਮਾਨਸ ਸ੍ਰਉਨਨ ਸੁਨ ਤਹਾ ਤਹਾ ਤੇ ਤੋਰ੍ਯੋ।","roman":"Jahaa jahaa maanas sraunan sun tahaa tahaa te toryo |","meaning_en":"","page":881},{"gurmukhi":"ਇਹ ਬਿਧਿ ਜੀਤ ਦੇਸ ਪੁਰ ਦੇਸਨ ਜੀਤ ਨਿਸਾਨ ਬਜਾਯੋ।","roman":"Ih bidhi jeet des pur desan jeet nisaan bajaayo |","meaning_en":"","page":881},{"gurmukhi":"ਆਪਨ ਕਰਣ ਕਾਰਣ ਕਰਿ ਮਾਨ੍ਯੋ ਕਾਲ ਪੁਰਖ ਬਿਸਰਾਯੋ। ੧੧੯।","roman":"Aapan karan kaaran kari maanyo kaal purakh bisraayo | 119 |","meaning_en":"","page":881}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਮਲ ਛੰਦ","gurmukhi":"ਰੂਆਮਲ ਛੰਦ","roman":"Rooaamal chhand","meaning_en":"","page":881},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":881,"lines":[{"gurmukhi":"ਦਸ ਸਹੰਸ੍ਰ ਪ੍ਰਮਾਣ ਬਰਖਨ ਕੀਨ ਰਾਜ ਸੁਧਾਰਿ।","roman":"Das sahansr pramaan barkhan keen raaj sudhaari |","meaning_en":"","page":881},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਧਰਾਨ ਲੈ ਅਰੁ ਸਤ੍ਰੁ ਸਰਬ ਸੰਘਾਰਿ।","roman":"Bhaati bhaati dharaan lai aru satru sarab sanghaari |","meaning_en":"","page":881},{"gurmukhi":"ਜੀਤਿ ਜੀਤਿ ਅਨੂਪ ਭੂਪ ਅਨੂਪ ਰੂਪ ਅਪਾਰ।","roman":"Jeeti jeeti anoop bhoop anoop roop apaar |","meaning_en":"","page":881},{"gurmukhi":"ਭੂਪ ਮੇਧ ਠਟ੍ਯੋ ਨ੍ਰਿਪੋਤਮ ਏਕ ਜਗ ਸੁਧਾਰਿ। ੧੨੦।","roman":"Bhoop medh thatyo nripotam ek jag sudhaari | 120 |","meaning_en":"","page":881}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":882,"lines":[{"gurmukhi":"ਦੇਸ ਦੇਸਨ ਕੇ ਨਰੇਸਨ ਬਾਧਿ ਕੈ ਇਕ ਬਾਰਿ।","roman":"Des desan ke naresan baadhi kai ik baari |","meaning_en":"","page":882},{"gurmukhi":"ਰੋਹ ਦੇਸ ਬਿਖੈ ਗਯੋ ਲੈ ਪੁਤ੍ਰ ਮਿਤ੍ਰ ਕੁਮਾਰ।","roman":"Roh des bikhai gayo lai putr mitr kumaar |","meaning_en":"","page":882},{"gurmukhi":"ਨਾਰਿ ਸੰਜੁਤ ਬੈਠਿ ਬਿਧਵਤ ਕੀਨ ਜਗ ਅਰੰਭ।","roman":"Naari sanjut baithi bidhvat keen jag aranbh |","meaning_en":"","page":882},{"gurmukhi":"ਬੋਲਿ ਬੋਲਿ ਕਰੋਰ ਰਿਤਜ ਔਰ ਬਿਪ ਅਸੰਭ। ੧੨੧।","roman":"Boli boli karor ritaj aur bip asanbh | 121 |","meaning_en":"","page":882}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":882,"lines":[{"gurmukhi":"ਰਾਜਮੇਧ ਕਰ੍ਯੋ ਲਗੈ ਆਰੰਭ ਭੂਪ ਅਪਾਰ।","roman":"Raajmedh karyo lagai aaranbh bhoop apaar |","meaning_en":"","page":882},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸਮ੍ਰਿਧ ਜੋਰਿ ਸੁਮਿਤ੍ਰ ਪੁਤ੍ਰ ਕੁਮਾਰ।","roman":"Bhaati bhaati samridh jori sumitr putr kumaar |","meaning_en":"","page":882},{"gurmukhi":"ਭਾਤਿ ਅਨੇਕਨ ਕੇ ਜੁਰੇ ਜਨ ਆਨਿ ਕੈ ਤਿਹ ਦੇਸ।","roman":"Bhaati anekan ke jure jan aani kai tih des |","meaning_en":"","page":882},{"gurmukhi":"ਛੀਨਿ ਛੀਨਿ ਲਏ ਨ੍ਰਿਪਾਬਰ ਦੇਸ ਦਿਰਬ ਅਵਿਨੇਸ। ੧੨੨।","roman":"Chheeni chheeni lae nripaabar des dirab avines | 122 |","meaning_en":"","page":882}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":882,"lines":[{"gurmukhi":"ਦੇਖ ਕੇ ਇਹ ਭਾਤਿ ਸਰਬ ਸੁ ਭੂਪ ਸੰਪਤਿ ਨੈਣ।","roman":"Dekh ke ih bhaati sarab su bhoop sanpti nain |","meaning_en":"","page":882},{"gurmukhi":"ਗਰਬ ਸੋ ਭੁਜ ਦੰਡ ਕੈ ਇਹ ਭਾਤਿ ਬੋਲਾ ਬੈਣ।","roman":"Garab so bhuj dand kai ih bhaati bolaa bain |","meaning_en":"","page":882},{"gurmukhi":"ਭੂਪ ਮੇਧ ਕਰੋ ਸਬੈ ਤੁਮ ਆਜ ਜਗ ਅਰੰਭ।","roman":"Bhoop medh karo sabai tum aaj jag aranbh |","meaning_en":"","page":882},{"gurmukhi":"ਸਤਜੁਗ ਮਾਹਿ ਭਯੋ ਜਿਹੀ ਬਿਧਿ ਕੀਨ ਰਾਜੈ ਜੰਭ। ੧੨੩।","roman":"Satjug maahi bhayo jihee bidhi keen raajai janbh | 123 |","meaning_en":"","page":882}]},{"type":"heading","kind":"speaker","name":"ਮੰਤ੍ਰੀਯ ਬਾਚ","gurmukhi":"ਮੰਤ੍ਰੀਯ ਬਾਚ","roman":"Mantreey baach","meaning_en":"","page":882},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":882,"lines":[{"gurmukhi":"ਲਛ ਜਉ ਨ੍ਰਿਪ ਮਾਰੀਯੈ ਤਬ ਹੋਤ ਹੈ ਨ੍ਰਿਪ ਮੇਧ।","roman":"Lachh jau nrip maareeyai tab hot hai nrip medh |","meaning_en":"","page":882},{"gurmukhi":"ਏਕ ਏਕ ਅਨੇਕ ਸੰਪਤਿ ਦੀਜੀਯੈ ਭਵਿਖੇਧ।","roman":"Ek ek anek sanpti deejeeyai bhavikhedh |","meaning_en":"","page":882},{"gurmukhi":"ਲਛ ਲਛ ਤੁਰੰਗ ਏਕਹਿ ਦੀਜੀਐ ਅਬਿਚਾਰ।","roman":"Lachh lachh turang ekhi deejeeai abichaar |","meaning_en":"","page":882},{"gurmukhi":"ਜਗ ਪੂਰਣ ਹੋਤੁ ਹੈ ਸੁਨ ਰਾਜ ਰਾਜ ਵਤਾਰ। ੧੨੪।","roman":"Jag pooran hotu hai sun raaj raaj vataar | 124 |","meaning_en":"","page":882}]},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":882,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸੁਮ੍ਰਿਧ ਸੰਪਤਿ ਦੀਜੀਯੈ ਇਕ ਬਾਰ।","roman":"Bhaati bhaati sumridh sanpti deejeeyai ik baar |","meaning_en":"","page":882},{"gurmukhi":"ਲਛ ਹਸਤ ਤੁਰੰਗ ਦ੍ਵੈ ਲਛ ਸੁਵਰਨ ਭਾਰ ਅਪਾਰ।","roman":"Lachh hasat turang dvai lachh suvran bhaar apaar |","meaning_en":"","page":882},{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਦਿਜੇਕ ਏਕਹਿ ਦੀਜੀਯੈ ਅਬਿਲੰਬ।","roman":"Koti koti dijek ekhi deejeeyai abilanb |","meaning_en":"","page":882},{"gurmukhi":"ਜਗ ਪੂਰਣ ਹੋਇ ਤਉ ਸੁਨ ਰਾਜ ਰਾਜ ਅਸੰਭ। ੧੨੫।","roman":"Jag pooran hoi tau sun raaj raaj asanbh | 125 |","meaning_en":"","page":882}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ","roman":"Paarasnaath baach","meaning_en":"","page":882},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":882},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":882,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਕੀ ਨ ਇਤੀ ਕਮੀ ਜਉ ਟੁਟ ਹੈ ਬਹੁ ਬਰਖ।","roman":"Suvran kee na itee kamee jau tut hai bahu barakh |","meaning_en":"","page":882},{"gurmukhi":"ਹਸਤ ਕੀ ਨ ਕਮੀ ਮੁਝੈ ਹਯ ਸਾਰ ਲੀਜੈ ਪਰਖ।","roman":"Hasat kee na kamee mujhai hay saar leejai parakh |","meaning_en":"","page":882},{"gurmukhi":"ਅਉਰ ਜਉ ਧਨ ਚਾਹੀਯੈ ਸੋ ਲੀਜੀਯੈ ਅਬਿਚਾਰ।","roman":"Aur jau dhan chaaheeyai so leejeeyai abichaar |","meaning_en":"","page":882},{"gurmukhi":"ਚਿਤ ਮੈ ਨ ਕਛੂ ਕਰੋ ਸੁਨ ਮੰਤ੍ਰ ਮਿਤ੍ਰ ਅਵਤਾਰ। ੧੨੬।","roman":"Chit mai na kachhoo karo sun mantr mitr avtaar | 126 |","meaning_en":"","page":882}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":882,"lines":[{"gurmukhi":"ਯਉ ਜਬੈ ਨ੍ਰਿਪ ਉਚਰ੍ਯੋ ਤਬ ਮੰਤ੍ਰਿ ਬਰ ਸੁਨਿ ਬੈਨ।","roman":"Yau jabai nrip uchryo tab mantri bar suni bain |","meaning_en":"","page":882},{"gurmukhi":"ਹਾਥ ਜੋਰਿ ਸਲਾਮ ਕੈ ਨ੍ਰਿਪ ਨੀਚ ਕੈ ਜੁਗ ਨੈਨ।","roman":"Haath jori salaam kai nrip neech kai jug nain |","meaning_en":"","page":882},{"gurmukhi":"ਅਉਰ ਏਕ ਸੁਨੋ ਨ੍ਰਿਪੋਤਮ ਉਚਰੋ ਇਕ ਗਾਥ।","roman":"Aur ek suno nripotam uchro ik gaath |","meaning_en":"","page":882},{"gurmukhi":"ਜੋਨ ਮਧਿ ਸੁਨੀ ਪੁਰਾਰਨਨ ਅਉਰ ਸਿੰਮ੍ਰਿਤ ਸਾਥ। ੧੨੭।","roman":"Jon madhi sunee puraarnan aur sinmrit saath | 127 |","meaning_en":"","page":882}]},{"type":"heading","kind":"speaker","name":"ਮੰਤ੍ਰੀ ਬਾਚ","gurmukhi":"ਮੰਤ੍ਰੀ ਬਾਚ","roman":"Mantree baach","meaning_en":"","page":883},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":883},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":883,"lines":[{"gurmukhi":"ਅਉਰ ਜੋ ਸਭ ਦੇਸ ਕੇ ਨ੍ਰਿਪ ਜੀਤੀਯੈ ਸੁਨਿ ਭੂਪ।","roman":"Aur jo sabh des ke nrip jeeteeyai suni bhoop |","meaning_en":"","page":883},{"gurmukhi":"ਪਰਮ ਰੂਪ ਪਵਿਤ੍ਰ ਗਾਤ ਅਪਵਿਤ੍ਰ ਹਰਣ ਸਰੂਪ।","roman":"Param roop pavitr gaat apvitr haran saroop |","meaning_en":"","page":883},{"gurmukhi":"ਐਸ ਜਉ ਸੁਨਿ ਭੂਪ ਭੂਪਤਿ ਸਭ ਪੂਛੀਆ ਤਿਹ ਗਾਥ।","roman":"Ais jau suni bhoop bhoopti sabh poochheeaa tih gaath |","meaning_en":"","page":883},{"gurmukhi":"ਪੂਛ ਆਉ ਸਬੈ ਨ੍ਰਿਪਾਲਨ ਹਉ ਕਹੋ ਤੁਹ ਸਾਥ। ੧੨੮।","roman":"Poochh aau sabai nripaalan hau kaho tuh saath | 128 |","meaning_en":"","page":883}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":883,"lines":[{"gurmukhi":"ਯੌ ਕਹੇ ਜਬ ਬੈਨ ਭੂਪਤਿ ਮੰਤ੍ਰਿ ਬਰ ਸੁਨਿ ਧਾਇ।","roman":"Yau kahe jab bain bhoopti mantri bar suni dhaai |","meaning_en":"","page":883},{"gurmukhi":"ਪੰਚ ਲਛ ਬੁਲਾਇ ਭੂਪਤਿ ਪੂਛ ਸਰਬ ਬੁਲਾਇ।","roman":"Panch lachh bulaai bhoopti poochh sarab bulaai |","meaning_en":"","page":883},{"gurmukhi":"ਅਉਰ ਸਾਤ ਹੂੰ ਲੋਕ ਭੀਤਰ ਦੇਹੁ ਅਉਰ ਬਤਾਇ।","roman":"Aur saat hoon lok bheetar dehu aur bataai |","meaning_en":"","page":883},{"gurmukhi":"ਜਉਨ ਜਉਨ ਨ ਜੀਤਿਆ ਨ੍ਰਿਪ ਰੋਸ ਕੈ ਨ੍ਰਿਪ ਰਾਇ। ੧੨੯।","roman":"Jaun jaun na jeetiaa nrip ros kai nrip raai | 129 |","meaning_en":"","page":883}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":883,"lines":[{"gurmukhi":"ਦੇਖਿ ਦੇਖਿ ਰਹੇ ਸਬੈ ਤਰ ਕੋ ਨ ਦੇਤ ਬਿਚਾਰ।","roman":"Dekhi dekhi rahe sabai tar ko na det bichaar |","meaning_en":"","page":883},{"gurmukhi":"ਐਸ ਕਉਨ ਰਹਾ ਧਰਾ ਪਰ ਦੇਹੁ ਤਾਹਿ ਉਚਾਰ।","roman":"Ais kaun rahaa dharaa par dehu taahi uchaar |","meaning_en":"","page":883},{"gurmukhi":"ਏਕ ਏਕ ਬੁਲਾਇ ਭੂਪਤਿ ਪੂਛ ਸਰਬ ਬੁਲਾਇ।","roman":"Ek ek bulaai bhoopti poochh sarab bulaai |","meaning_en":"","page":883},{"gurmukhi":"ਕੋ ਅਜੀਤ ਰਹਾ ਨਹੀ ਜਿਹ ਠਉਰ ਦੇਹੁ ਬਤਾਇ। ੧੩੦।","roman":"Ko ajeet rahaa nahee jih thaur dehu bataai | 130 |","meaning_en":"","page":883}]},{"type":"heading","kind":"speaker","name":"ਏਕ ਨ੍ਰਿਪ ਬਾਚ","gurmukhi":"ਏਕ ਨ੍ਰਿਪ ਬਾਚ","roman":"Ek nrip baach","meaning_en":"","page":883},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":883},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":883,"lines":[{"gurmukhi":"ਏਕ ਭੂਪਤਿ ਉਚਰੋ ਸੁਨਿ ਲੇਹੁ ਰਾਜਾ ਬੈਨ।","roman":"Ek bhoopti uchro suni lehu raajaa bain |","meaning_en":"","page":883},{"gurmukhi":"ਜਾਨ ਮਾਫ ਕਰੋ ਕਹੋ ਤਬ ਰਾਜ ਰਾਜ ਸੁ ਨੈਨ।","roman":"Jaan maaph karo kaho tab raaj raaj su nain |","meaning_en":"","page":883},{"gurmukhi":"ਏਕ ਹੈ ਮੁਨਿ ਸਿੰਧੁ ਮੈ ਅਰੁ ਮਛ ਕੇ ਉਰ ਮਾਹਿ।","roman":"Ek hai muni sindhu mai aru machh ke ur maahi |","meaning_en":"","page":883},{"gurmukhi":"ਮੋਹਿ ਰਾਵ ਬਿਬੇਕ ਭਾਖੌ ਤਾਹਿ ਭੂਪਤਿ ਨਾਹਿ। ੧੩੧।","roman":"Mohi raav bibek bhaakhau taahi bhoopti naahi | 131 |","meaning_en":"","page":883}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":883,"lines":[{"gurmukhi":"ਏਕ ਦ੍ਯੋਸ ਜਟਧਰੀ ਨ੍ਰਿਪ ਕੀਨੁ ਛੀਰ ਪ੍ਰਵੇਸ।","roman":"Ek dyos jatadhree nrip keenu chheer praves |","meaning_en":"","page":883},{"gurmukhi":"ਚਿਤ੍ਰ ਰੂਪ ਹੁਤੀ ਤਹਾ ਇਕ ਨਾਰਿ ਨਾਗਰ ਭੇਸ।","roman":"Chitr roop hutee tahaa ik naari naagar bhes |","meaning_en":"","page":883},{"gurmukhi":"ਤਾਸੁ ਦੇਖਿ ਸਿਵੇਸ ਕੋ ਗਿਰ ਬਿੰਦ ਸਿੰਧ ਮਝਾਰ।","roman":"Taasu dekhi sives ko gir bind sindh majhaar |","meaning_en":"","page":883},{"gurmukhi":"ਮਛ ਪੇਟ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠਿ ਹੈ ਨ੍ਰਿਪ ਬਾਰ। ੧੩੨।","roman":"Machh pet machhandr jogee baithi hai nrip baar | 132 |","meaning_en":"","page":883}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":883,"lines":[{"gurmukhi":"ਤਾਸੁ ਤੇ ਚਲ ਪੁਛੀਐ ਨ੍ਰਿਪ ਸਰਬ ਬਾਤ ਬਿਬੇਕ।","roman":"Taasu te chal puchheeai nrip sarab baat bibek |","meaning_en":"","page":883},{"gurmukhi":"ਏਨ ਤੋਹਿ ਬਤਾਇ ਹੈ ਨ੍ਰਿਪ ਭਾਖਿ ਹੋ ਜੁ ਅਨੇਕ।","roman":"En tohi bataai hai nrip bhaakhi ho ju anek |","meaning_en":"","page":883},{"gurmukhi":"ਐਸ ਬਾਤ ਸੁਨੀ ਜਬੈ ਤਬ ਰਾਜ ਰਾਜ ਅਵਤਾਰ।","roman":"Ais baat sunee jabai tab raaj raaj avtaar |","meaning_en":"","page":883},{"gurmukhi":"ਸਿੰਧੁ ਖੋਜਨ ਕੋ ਚਲਾ ਲੈ ਜਗਤ ਕੇ ਸਬ ਜਾਰ। ੧੩੩।","roman":"Sindhu khojan ko chalaa lai jagat ke sab jaar | 133 |","meaning_en":"","page":883}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":883,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਮੰਗਾਇ ਜਾਲਨ ਸੰਗ ਲੈ ਦਲ ਸਰਬ।","roman":"Bhaati bhaati mangaai jaalan sang lai dal sarab |","meaning_en":"","page":883},{"gurmukhi":"ਜੀਤ ਦੁੰਦਭ ਦੈ ਚਲਾ ਨ੍ਰਿਪ ਜਾਨਿ ਕੈ ਜੀਅ ਗਰਬ।","roman":"Jeet dundabh dai chalaa nrip jaani kai jeea garab |","meaning_en":"","page":883},{"gurmukhi":"ਮੰਤ੍ਰੀ ਮਿਤ੍ਰ ਕੁਮਾਰਿ ਸੰਪਤ ਸਰਬ ਮਧਿ ਬੁਲਾਇ।","roman":"Mantree mitr kumaari sanpat sarab madhi bulaai |","meaning_en":"","page":883},{"gurmukhi":"ਸਿੰਧ ਜਾਰ ਡਰੇ ਜਹਾ ਤਹਾ ਮਛ ਸਤ੍ਰੁ ਡਰਾਇ। ੧੩੪।","roman":"Sindh jaar dare jahaa tahaa machh satru daraai | 134 |","meaning_en":"","page":883}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":884,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਨ ਮਛ ਕਛਪ ਅਉਰ ਜੀਵ ਅਪਾਰ।","roman":"Bhaati bhaatan machh kachhap aur jeev apaar |","meaning_en":"","page":884},{"gurmukhi":"ਬਧਿ ਜਾਰਨ ਹ੍ਵੈ ਕਢੇ ਤਬ ਤਿਆਗਿ ਪ੍ਰਾਨ ਸੁ ਧਾਰ।","roman":"Badhi jaaran hvai kadhe tab tiaagi praan su dhaar |","meaning_en":"","page":884},{"gurmukhi":"ਸਿੰਧੁ ਤੀਰ ਗਏ ਜਬੈ ਜਲ ਜੀਵ ਏਕੈ ਬਾਰ।","roman":"Sindhu teer gae jabai jal jeev ekai baar |","meaning_en":"","page":884},{"gurmukhi":"ਐਸ ਭਾਤਿ ਭਏ ਬਖਾਨਤ ਸਿੰਧੁ ਪੈ ਮਤ ਸਾਰ। ੧੩੫।","roman":"Ais bhaati bhae bakhaanat sindhu pai mat saar | 135 |","meaning_en":"","page":884}]},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":884,"lines":[{"gurmukhi":"ਬਿਪ ਕੋ ਧਰਿ ਸਿੰਧੁ ਮੂਰਤਿ ਆਇਯੋ ਤਿਹ ਪਾਸਿ।","roman":"Bip ko dhari sindhu moorti aaiyo tih paasi |","meaning_en":"","page":884},{"gurmukhi":"ਰਤਨ ਹੀਰ ਪ੍ਰਵਾਲ ਮਾਨਕ ਦੀਨ ਹੈ ਅਨਿਆਸ।","roman":"Ratan heer pravaal maanak deen hai aniaas |","meaning_en":"","page":884},{"gurmukhi":"ਜੀਵ ਕਾਹਿ ਸੰਘਾਰੀਐ ਸੁਨਿ ਲੀਜੀਐ ਨ੍ਰਿਪ ਬੈਨ।","roman":"Jeev kaahi sanghaareeai suni leejeeai nrip bain |","meaning_en":"","page":884},{"gurmukhi":"ਜਉਨ ਕਾਰਜ ਕੋ ਚਲੇ ਤੁਮ ਸੋ ਨਹੀ ਇਹ ਠੈਨ। ੧੩੬।","roman":"Jaun kaaraj ko chale tum so nahee ih thain | 136 |","meaning_en":"","page":884}]},{"type":"heading","kind":"speaker","name":"ਸਿੰਧੁ ਬਾਚ","gurmukhi":"ਸਿੰਧੁ ਬਾਚ","roman":"Sindhu baach","meaning_en":"","page":884},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":884},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":884,"lines":[{"gurmukhi":"ਛੀਰ ਸਾਗਰ ਹੈ ਜਹਾ ਸੁਨ ਰਾਜ ਰਾਜ ਵਤਾਰ।","roman":"Chheer saagar hai jahaa sun raaj raaj vataar |","meaning_en":"","page":884},{"gurmukhi":"ਮਛ ਉਦਰ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠ ਹੈ ਬ੍ਰਤ ਧਾਰਿ।","roman":"Machh udar machhandr jogee baith hai brat dhaari |","meaning_en":"","page":884},{"gurmukhi":"ਡਾਰਿ ਜਾਰ ਨਿਕਾਰ ਤਾਕਹਿ ਪੂਛ ਲੇਹੁ ਬਨਾਇ।","roman":"Daari jaar nikaar taakhi poochh lehu banaai |","meaning_en":"","page":884},{"gurmukhi":"ਜੋ ਕਹਾ ਸੋ ਕੀਜੀਐ ਨ੍ਰਿਪ ਇਹੀ ਸਤਿ ਉਪਾਇ। ੧੩੭।","roman":"Jo kahaa so keejeeai nrip ihee sati upaai | 137 |","meaning_en":"","page":884}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":884,"lines":[{"gurmukhi":"ਜੋਰਿ ਬੀਰਨ ਨਾਖ ਸਿੰਧਹ ਆਗ ਚਾਲ ਸੁਬਾਹ।","roman":"Jori beeran naakh sindhah aag chaal subaah |","meaning_en":"","page":884},{"gurmukhi":"ਹੂਰ ਪੂਰ ਰਹੀ ਜਹਾ ਤਹਾ ਜਤ੍ਰ ਤਤ੍ਰ ਉਛਾਹ।","roman":"Hoor poor rahee jahaa tahaa jatr tatr uchhaah |","meaning_en":"","page":884},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਜੰਤ੍ਰ ਬਾਜਤ ਅਉਰ ਘੁਰਤ ਨਿਸਾਨ।","roman":"Bhaati bhaati bajantr baajat aur ghurat nisaan |","meaning_en":"","page":884},{"gurmukhi":"ਛੀਰ ਸਿੰਧੁ ਹੁਤੋ ਜਹਾ ਤਿਹ ਠਾਮ ਪਹੁਚੇ ਆਨਿ। ੧੩੮।","roman":"Chheer sindhu huto jahaa tih thaam pahuche aani | 138 |","meaning_en":"","page":884}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":884,"lines":[{"gurmukhi":"ਸੂਤ੍ਰ ਜਾਰ ਬਨਾਇ ਕੈ ਤਿਹ ਮਧਿ ਡਾਰਿ ਅਪਾਰ।","roman":"Sootr jaar banaai kai tih madhi daari apaar |","meaning_en":"","page":884},{"gurmukhi":"ਅਉਰ ਜੀਵ ਘਨੇ ਗਹੇ ਨ ਵਿਲੋਕਯੋ ਸਿਵ ਬਾਰ।","roman":"Aur jeev ghane gahe na vilokyo siv baar |","meaning_en":"","page":884},{"gurmukhi":"ਹਾਰਿ ਹਾਰਿ ਫਿਰੇ ਸਬੈ ਭਟ ਆਨਿ ਭੂਪਤਿ ਤੀਰ।","roman":"Haari haari phire sabai bhat aani bhoopti teer |","meaning_en":"","page":884},{"gurmukhi":"ਅਉਰ ਜੀਵ ਘਨੇ ਗਹੇ ਪਰ ਸੋ ਨ ਪਾਵ ਫਕੀਰ। ੧੩੯।","roman":"Aur jeev ghane gahe par so na paav phakeer | 139 |","meaning_en":"","page":884}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":884,"lines":[{"gurmukhi":"ਮਛ ਪੇਟਿ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠ ਹੈ ਬਿਨੁ ਆਸ।","roman":"Machh peti machhandr jogee baith hai binu aas |","meaning_en":"","page":884},{"gurmukhi":"ਜਾਰ ਭੇਟ ਸਕੈ ਨ ਵਾ ਕੋ ਮੋਨਿ ਅੰਗ ਸੁ ਬਾਸ।","roman":"Jaar bhet sakai na vaa ko moni ang su baas |","meaning_en":"","page":884},{"gurmukhi":"ਏਕ ਜਾਰ ਸੁਨਾ ਨਯੋ ਤਿਹ ਡਾਰੀਐ ਅਬਿਚਾਰ।","roman":"Ek jaar sunaa nayo tih daareeai abichaar |","meaning_en":"","page":884},{"gurmukhi":"ਸਤਿ ਬਾਤ ਕਹੋ ਤੁਮੈ ਸੁਨਿ ਰਾਜ ਰਾਜ ਵਤਾਰ। ੧੪੦।","roman":"Sati baat kaho tumai suni raaj raaj vataar | 140 |","meaning_en":"","page":884}]},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":884,"lines":[{"gurmukhi":"ਗਿਆਨ ਨਾਮੁ ਸੁਨਾ ਹਮੋ ਤਿਹ ਜਾਰ ਕੋ ਨ੍ਰਿਪ ਰਾਇ।","roman":"Giaan naamu sunaa hamo tih jaar ko nrip raai |","meaning_en":"","page":884},{"gurmukhi":"ਤਉਨ ਤਾ ਮੈ ਡਾਰਿ ਕੈ ਮੁਨਿ ਰਾਜ ਲੇਹੁ ਗਹਾਇ।","roman":"Taun taa mai daari kai muni raaj lehu gahaai |","meaning_en":"","page":884},{"gurmukhi":"ਯੌ ਨ ਹਾਥਿ ਪਰੇ ਮੁਨੀਸੁਰ ਬੀਤ ਹੈ ਬਹੁ ਬਰਖ।","roman":"Yau na haathi pare muneesur beet hai bahu barakh |","meaning_en":"","page":884},{"gurmukhi":"ਸਤਿ ਬਾਤ ਕਹੌ ਤੁਮੈ ਸੁਨ ਲੀਜੀਐ ਭਰਤਰਖ। ੧੪੧।","roman":"Sati baat kahau tumai sun leejeeai bharatrakh | 141 |","meaning_en":"","page":884}]},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":884,"lines":[{"gurmukhi":"ਯੌ ਨ ਪਾਨਿ ਪਰੇ ਮੁਨਾਬਰ ਹੋਹਿੰ ਕੋਟਿ ਉਪਾਇ।","roman":"Yau na paani pare munaabar hohin koti upaai |","meaning_en":"","page":884},{"gurmukhi":"ਡਾਰ ਕੇ ਤੁਮ ਗ੍ਯਾਨ ਜਾਰ ਸੁ ਤਾਸੁ ਲੇਹੁ ਗਹਾਇ।","roman":"Daar ke tum gyaan jaar su taasu lehu gahaai |","meaning_en":"","page":884},{"gurmukhi":"ਗ੍ਯਾਨ ਜਾਰ ਜਬੈ ਨ੍ਰਿਪੰਬਰ ਡਾਰ੍ਯੋ ਤਿਹ ਬੀਚ।","roman":"Gyaan jaar jabai nripanbar daaryo tih beech |","meaning_en":"","page":884},{"gurmukhi":"ਤਉਨ ਜਾਰ ਗਹੋ ਮੁਨਾਬਰ ਜਾਨੁ ਦੂਜ ਦਧੀਚ। ੧੪੨।","roman":"Taun jaar gaho munaabar jaanu dooj dadheech | 142 |","meaning_en":"","page":884}]},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":885,"lines":[{"gurmukhi":"ਮਛ ਸਹਿਤ ਮਛਿੰਦ੍ਰ ਜੋਗੀ ਬਧਿ ਜਾਰ ਮਝਾਰ।","roman":"Machh sahit machhindr jogee badhi jaar majhaar |","meaning_en":"","page":885},{"gurmukhi":"ਮਛ ਲੋਕ ਬਿਲੋਕਿ ਕੈ ਸਬ ਹ੍ਵੈ ਗਏ ਬਿਸੰਭਾਰ।","roman":"Machh lok biloki kai sab hvai gae bisanbhaar |","meaning_en":"","page":885},{"gurmukhi":"ਦ੍ਵੈ ਮਹੂਰਤ ਬਿਤੀ ਜਬੈ ਸੁਧਿ ਪਾਇ ਕੈ ਕਛੁ ਅੰਗਿ।","roman":"Dvai mahoorat bitee jabai sudhi paai kai kachhu angi |","meaning_en":"","page":885},{"gurmukhi":"ਭੂਪ ਦ੍ਵਾਰ ਗਏ ਸਭੈ ਭਟ ਬਾਧਿ ਅਸਤ੍ਰ ਉਤੰਗ। ੧੪੩।","roman":"Bhoop dvaar gae sabhai bhat baadhi asatr utang | 143 |","meaning_en":"","page":885}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":885,"lines":[{"gurmukhi":"ਮਛ ਉਦਰ ਲਗੇ ਸੁ ਚੀਰਨ ਕਿਉਹੂੰ ਨ ਚੀਰਾ ਜਾਇ।","roman":"Machh udar lage su cheeran kiuhoon na cheeraa jaai |","meaning_en":"","page":885},{"gurmukhi":"ਹਾਰਿ ਹਾਰਿ ਪਰੈ ਜਬੈ ਤਬ ਪੂਛ ਮਿਤ੍ਰ ਬੁਲਾਇ।","roman":"Haari haari parai jabai tab poochh mitr bulaai |","meaning_en":"","page":885},{"gurmukhi":"ਅਉਰ ਕਉਨ ਬਿਚਾਰੀਐ ਉਪਚਾਰ ਤਾਕਰ ਆਜ।","roman":"Aur kaun bichaareeai upchaar taakar aaj |","meaning_en":"","page":885},{"gurmukhi":"ਦ੍ਰਿਸਟਿ ਜਾ ਤੇ ਪਰੈ ਮੁਨੀਸ੍ਵਰ ਸਰੇ ਹਮਰੋ ਕਾਜੁ। ੧੪੪।","roman":"Dristi jaa te parai muneesvar sare hamro kaaju | 144 |","meaning_en":"","page":885}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":885},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":885,"lines":[{"gurmukhi":"ਮਛ ਪੇਟ ਕਿਹੂੰ ਨ ਫੁਟੇ ਸਬ ਕਰ ਹਟੇ ਉਪਾਇ।","roman":"Machh pet kihoon na phute sab kar hate upaai |","meaning_en":"","page":885},{"gurmukhi":"ਗ੍ਯਾਨ ਗੁਰੂ ਤਿਨ ਕੋ ਹੁਤੋ ਪੂਛਾ ਤਹਿ ਬਨਾਇ। ੧੪੫।","roman":"Gyaan guroo tin ko huto poochhaa tahi banaai | 145 |","meaning_en":"","page":885}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"","page":885},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":885,"lines":[{"gurmukhi":"ਭਟ ਤ੍ਯਾਗ ਕੈ ਸਬ ਗਰਬ। ਨ੍ਰਿਪ ਤੀਰ ਬੋਲੋ ਸਰਬ।","roman":"Bhat tyaag kai sab garab | nrip teer bolo sarab |","meaning_en":"","page":885},{"gurmukhi":"ਨ੍ਰਿਪ ਪੂਛੀਐ ਗੁਰ ਗ੍ਯਾਨ। ਕਹਿ ਦੇਇ ਤੋਹਿ ਬਿਧਾਨ। ੧੪੬।","roman":"Nrip poochheeai gur gyaan | kahi dei tohi bidhaan | 146 |","meaning_en":"","page":885}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":885,"lines":[{"gurmukhi":"ਬਿਧਿ ਪੂਰਿ ਕੈ ਸੁਭ ਚਾਰ। ਅਰੁ ਗ੍ਯਾਨ ਰੀਤਿ ਬਿਚਾਰਿ।","roman":"Bidhi poori kai subh chaar | aru gyaan reeti bichaari |","meaning_en":"","page":885},{"gurmukhi":"ਗੁਰ ਭਾਖੀਐ ਮੁਹਿ ਭੇਵ। ਕਿਮ ਦੇਖੀਐ ਮੁਨਿ ਦੇਵ। ੧੪੭।","roman":"Gur bhaakheeai muhi bhev | kim dekheeai muni dev | 147 |","meaning_en":"","page":885}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":885,"lines":[{"gurmukhi":"ਗੁਰ ਗ੍ਯਾਨ ਬੋਲ੍ਯੋ ਬੈਨ। ਸੁਭ ਬਾਚ ਸੋ ਸੁਖ ਦੈਨ।","roman":"Gur gyaan bolyo bain | subh baach so sukh dain |","meaning_en":"","page":885},{"gurmukhi":"ਛੁਰਕਾ ਬਿਬੇਕ ਲੈ ਹਾਥ। ਇਹ ਫਾਰੀਐ ਤਿਹ ਸਾਥ। ੧੪੮।","roman":"Chhurkaa bibek lai haath | ih phaareeai tih saath | 148 |","meaning_en":"","page":885}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":885,"lines":[{"gurmukhi":"ਤਬ ਕਾਮ ਤੈਸੋ ਈ ਕੀਨ। ਗੁਰ ਗ੍ਯਾਨ ਜ੍ਯੋਂ ਸਿਖ ਦੀਨ।","roman":"Tab kaam taiso ee keen | gur gyaan jyon sikh deen |","meaning_en":"","page":885},{"gurmukhi":"ਗਹਿ ਕੈ ਬਿਬੇਕਹਿ ਹਾਥ। ਤਿਹ ਚੀਰਿਆ ਤਿਹ ਸਾਥ। ੧੪੯।","roman":"Gahi kai bibekhi haath | tih cheeriaa tih saath | 149 |","meaning_en":"","page":885}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":885,"lines":[{"gurmukhi":"ਜਬ ਚੀਰਿ ਪੇਟ ਬਨਾਇ। ਤਬ ਦੇਖਏ ਜਗ ਰਾਇ।","roman":"Jab cheeri pet banaai | tab dekhae jag raai |","meaning_en":"","page":885},{"gurmukhi":"ਜੁਤ ਧ੍ਯਾਨ ਮੁੰਦ੍ਰਤ ਨੈਨ। ਬਿਨੁ ਆਸ ਚਿਤ ਨ ਡੁਲੈਨ। ੧੫੦।","roman":"Jut dhyaan mundrat nain | binu aas chit na dulain | 150 |","meaning_en":"","page":885}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":885,"lines":[{"gurmukhi":"ਸਤ ਧਾਤ ਪੁਤ੍ਰਾ ਕੀਨ। ਮੁਨਿ ਦ੍ਰਿਸਟਿ ਤਰ ਧਰ ਦੀਨ।","roman":"Sat dhaat putraa keen | muni dristi tar dhar deen |","meaning_en":"","page":885},{"gurmukhi":"ਜਬ ਛੂਟਿ ਰਿਖਿ ਕੇ ਧ੍ਯਾਨ। ਤਬ ਭਏ ਭਸਮ ਪ੍ਰਮਾਨ। ੧੫੧।","roman":"Jab chhooti rikhi ke dhyaan | tab bhae bhasam pramaan | 151 |","meaning_en":"","page":885}]},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":885,"lines":[{"gurmukhi":"ਜੋ ਅਉਰ ਦ੍ਰਿਗ ਤਰਿ ਆਉ। ਸੋਊ ਜੀਅਤ ਜਾਨ ਨ ਪਾਉ।","roman":"Jo aur drig tari aau | so'oo jeeat jaan na paau |","meaning_en":"","page":885},{"gurmukhi":"ਸੋ ਭਸਮ ਹੋਵਤ ਜਾਨੁ। ਬਿਨੁ ਪ੍ਰੀਤਿ ਭਗਤ ਨ ਮਾਨੁ। ੧੫੨।","roman":"So bhasam hovat jaanu | binu preeti bhagat na maanu | 152 |","meaning_en":"","page":885}]},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":885,"lines":[{"gurmukhi":"ਜਬ ਭਏ ਪੁਤ੍ਰਾ ਭਸਮ। ਜਨ ਅੰਧਤਾ ਰਵਿ ਰਸਮ।","roman":"Jab bhae putraa bhasam | jan andhtaa ravi rasam |","meaning_en":"","page":885},{"gurmukhi":"ਪੁਨਿ ਪੂਛੀਆ ਤਿਹਾ ਜਾਇ। ਮੁਨਿ ਰਾਜ ਭੇਦ ਬਤਾਇ। ੧੫੩।","roman":"Puni poochheeaa tihaa jaai | muni raaj bhed bataai | 153 |","meaning_en":"","page":885}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"","page":886},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":886,"lines":[{"gurmukhi":"ਕਉਨ ਭੂਪ ਭੂਮਿ ਮੈ ਬਤਾਇ ਮੋਹਿ ਦੀਜੀਯੈ।","roman":"Kaun bhoop bhoomi mai bataai mohi deejeeyai |","meaning_en":"","page":886},{"gurmukhi":"ਜੋ ਮੋਹਿ ਤ੍ਰਾਸਿ ਨ ਤ੍ਰਸ੍ਯੋ ਕ੍ਰਿਪਾ ਰਿਖੀਸ ਕੀਜੀਯੈ।","roman":"Jo mohi traasi na trasyo kripaa rikhees keejeeyai |","meaning_en":"","page":886},{"gurmukhi":"ਸੁ ਅਉਰ ਕਉਨ ਹੈ ਹਠੀ ਸੁ ਜਉਨ ਮੋ ਨ ਜੀਤਿਯੋ।","roman":"Su aur kaun hai hathee su jaun mo na jeetiyo |","meaning_en":"","page":886},{"gurmukhi":"ਅਤ੍ਰਾਸ ਕਉਨ ਠਉਰ ਹੈ ਜਹਾ ਨ ਮੋਹ ਬੀਤਿਯੋ। ੧੫੪।","roman":"Atraas kaun thaur hai jahaa na moh beetiyo | 154 |","meaning_en":"","page":886}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":886,"lines":[{"gurmukhi":"ਨ ਸੰਕ ਚਿਤ ਆਨੀਯੈ ਨਿਸੰਕ ਭਾਖ ਦੀਜੀਯੈ।","roman":"Na sank chit aaneeyai nisank bhaakh deejeeyai |","meaning_en":"","page":886},{"gurmukhi":"ਸੁ ਕੋ ਅਜੀਤ ਹੈ ਰਹਾ ਉਚਾਰ ਤਾਸੁ ਕੀਜੀਯੈ।","roman":"Su ko ajeet hai rahaa uchaar taasu keejeeyai |","meaning_en":"","page":886},{"gurmukhi":"ਨਰੇਸ ਦੇਸ ਦੇਸ ਕੇ ਅਸੇਸ ਜੀਤ ਮੈ ਲੀਏ।","roman":"Nares des des ke ases jeet mai lee'e |","meaning_en":"","page":886},{"gurmukhi":"ਛਿਤੇਸ ਭੇਸ ਭੇਸ ਕੇ ਗੁਲਾਮ ਆਨਿ ਹੂਐ ਰਹੇ। ੧੫੫।","roman":"Chhites bhes bhes ke gulaam aani hooai rahe | 155 |","meaning_en":"","page":886}]},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":886,"lines":[{"gurmukhi":"ਅਸੇਖ ਰਾਜ ਕਾਜ ਮੋ ਲਗਾਇ ਕੈ ਦੀਏ।","roman":"Asekh raaj kaaj mo lagaai kai dee'e |","meaning_en":"","page":886},{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਨਾਤਿ ਕੈ ਅਛਿਨ ਪੁਨ ਮੈ ਕੀਏ।","roman":"Anant teerath naati kai achhin pun mai kee'e |","meaning_en":"","page":886},{"gurmukhi":"ਅਨੰਤ ਛਤ੍ਰੀਆਨ ਛੈ ਦੁਰੰਤ ਰਾਜ ਮੈ ਕਰੋ।","roman":"Anant chhatreeaan chhai durant raaj mai karo |","meaning_en":"","page":886},{"gurmukhi":"ਸੋ ਕੋ ਤਿਹੁੰ ਜਹਾਨ ਮੈ ਸਮਾਜ ਜਉਨ ਤੇ ਟਰੋ। ੧੫੬।","roman":"So ko tihun jahaan mai samaaj jaun te taro | 156 |","meaning_en":"","page":886}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":886,"lines":[{"gurmukhi":"ਅਨੰਗ ਰੰਗ ਰੰਗ ਕੇ ਸੁਰੰਗ ਬਾਜ ਮੈ ਹਰੇ।","roman":"Anang rang rang ke surang baaj mai hare |","meaning_en":"","page":886},{"gurmukhi":"ਬਸੇਖ ਰਾਜਸੂਇ ਜਗ ਬਾਜਮੇਧ ਮੈ ਕਰੇ।","roman":"Basekh raajsooi jag baajmedh mai kare |","meaning_en":"","page":886},{"gurmukhi":"ਨ ਭੂਮਿ ਐਸ ਕੋ ਰਹੀ ਨ ਜਗ ਖੰਭ ਜਾਨੀਯੈ।","roman":"Na bhoomi ais ko rahee na jag khanbh jaaneeyai |","meaning_en":"","page":886},{"gurmukhi":"ਜਗਤ੍ਰ ਕਰਣ ਕਾਰਣ ਕਰਿ ਦੁਤੀਯ ਮੋਹਿ ਮਾਨੀਯੈ। ੧੫੭।","roman":"Jagatr karan kaaran kari duteey mohi maaneeyai | 157 |","meaning_en":"","page":886}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":886,"lines":[{"gurmukhi":"ਸੁ ਅਤ੍ਰ ਛਤ੍ਰ ਜੇ ਧਰੇ ਸੁ ਛਤ੍ਰ ਸੂਰ ਸੇਵਹੀ।","roman":"Su atr chhatr je dhare su chhatr soor sevhee |","meaning_en":"","page":886},{"gurmukhi":"ਅਦੰਡ ਖੰਡ ਖੰਡ ਕੇ ਸੁਦੰਡ ਮੋਹਿ ਦੇਵ ਹੀ।","roman":"Adand khand khand ke sudand mohi dev hee |","meaning_en":"","page":886},{"gurmukhi":"ਸੁ ਐਸ ਅਉਰ ਕੌਨ ਹੈ ਪ੍ਰਤਾਪਵਾਨ ਜਾਨੀਐ।","roman":"Su ais aur kaun hai prataapvaan jaaneeai |","meaning_en":"","page":886},{"gurmukhi":"ਤ੍ਰਿਲੋਕ ਆਜ ਕੇ ਬਿਖੈ ਜੋਗਿੰਦਰ ਮੋਹਿ ਮਾਨੀਐ। ੧੫੮।","roman":"Trilok aaj ke bikhai jogindar mohi maaneeai | 158 |","meaning_en":"","page":886}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"","page":886},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":886},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":886,"lines":[{"gurmukhi":"ਕਹਾ ਭਯੋ ਜੋ ਸਭ ਹੀ ਜਗ ਜੀਤਿ ਸੁ ਲੋਗਨ ਕੋ ਬਹੁ ਤ੍ਰਾਸ ਦਿਖਾਯੋ।","roman":"Kahaa bhayo jo sabh hee jag jeeti su logan ko bahu traas dikhaayo |","meaning_en":"","page":886},{"gurmukhi":"ਅਉਰ ਕਹਾ ਜੁ ਪੈ ਦੇਸ ਬਿਦੇਸਨ ਮਾਹਿ ਭਲੇ ਗਜ ਗਾਹਿ ਬਧਾਯੋ।","roman":"Aur kahaa ju pai des bidesan maahi bhale gaj gaahi badhaayo |","meaning_en":"","page":886},{"gurmukhi":"ਜੋ ਮਨੁ ਜੀਤਤ ਹੈ ਸਭ ਦੇਸ ਵਹੈ ਤੁਮਰੈ ਨ੍ਰਿਪ ਹਾਥਿ ਨ ਆਯੋ।","roman":"Jo manu jeetat hai sabh des vahai tumrai nrip haathi na aayo |","meaning_en":"","page":886},{"gurmukhi":"ਲਾਜ ਗਈ ਕਛੁ ਕਾਜ ਸਰ੍ਯੋ ਨਹੀ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਨ ਪਾਯੋ। ੧੫੯।","roman":"Laaj gaee kachhu kaaj saryo nahee lok gayo parlok na paayo | 159 |","meaning_en":"","page":886}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":886,"lines":[{"gurmukhi":"ਭੂਮਿ ਕੋ ਕਉਨ ਗੁਮਾਨ ਹੈ ਭੂਪਤਿ ਸੋ ਨਹੀ ਕਾਹੂੰ ਕੇ ਸੰਗ ਚਲੈ ਹੈ।","roman":"Bhoomi ko kaun gumaan hai bhoopti so nahee kaahoon ke sang chalai hai |","meaning_en":"","page":886},{"gurmukhi":"ਹੈ ਛਲਵੰਤ ਬਡੀ ਬਸੁਧਾ ਯਹਿ ਕਾਹੂੰ ਕੀ ਹੈ ਨਹ ਕਾਹੂੰ ਹੁਐ ਹੈ।","roman":"Hai chhalvant badee basudhaa yahi kaahoon kee hai nah kaahoon huai hai |","meaning_en":"","page":886},{"gurmukhi":"ਭਉਨ ਭੰਡਾਰ ਸਬੈ ਬਰ ਨਾਰਿ ਸੁ ਅੰਤਿ ਤੁਝੈ ਕੋਊ ਸਾਥ ਨ ਦੈ ਹੈ।","roman":"Bhaun bhandaar sabai bar naari su anti tujhai ko'oo saath na dai hai |","meaning_en":"","page":886},{"gurmukhi":"ਆਨ ਕੀ ਬਾਤ ਚਲਾਤ ਹੋ ਕਾਹੇ ਕਉ ਸੰਗਿ ਕੀ ਦੇਹ ਨ ਸੰਗਿ ਸਿਧੈ ਹੈ। ੧੬੦।","roman":"Aan kee baat chalaat ho kaahe kau sangi kee deh na sangi sidhai hai | 160 |","meaning_en":"","page":886}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":887,"lines":[{"gurmukhi":"ਰਾਜ ਕੇ ਸਾਜ ਕੋ ਕਉਨ ਗੁਮਾਨ ਨਿਦਾਨ ਜੁ ਆਪਨ ਸੰਗ ਨ ਜੈ ਹੈ।","roman":"Raaj ke saaj ko kaun gumaan nidaan ju aapan sang na jai hai |","meaning_en":"","page":887},{"gurmukhi":"ਭਉਨ ਭੰਡਾਰ ਭਰੇ ਘਰ ਬਾਰ ਸੁ ਏਕ ਹੀ ਬਾਰ ਬਿਗਾਨ ਕਹੈ ਹੈ।","roman":"Bhaun bhandaar bhare ghar baar su ek hee baar bigaan kahai hai |","meaning_en":"","page":887},{"gurmukhi":"ਪੁਤ੍ਰ ਕਲਤ੍ਰ ਸੁ ਮਿਤ੍ਰ ਸਖਾ ਕੋਈ ਅੰਤਿ ਸਮੈ ਤੁਹਿ ਸਾਥ ਨ ਦੈ ਹੈ।","roman":"Putr kalatr su mitr sakhaa koee anti samai tuhi saath na dai hai |","meaning_en":"","page":887},{"gurmukhi":"ਚੇਤ ਰੇ ਚੇਤ ਅਚੇਤ ਮਹਾ ਪਸੁ ਸੰਗ ਬੀਯੋ ਸੋ ਭੀ ਸੰਗ ਨ ਜੈ ਹੈ। ੧੬੧।","roman":"Chet re chet achet mahaa pasu sang beeyo so bhee sang na jai hai | 161 |","meaning_en":"","page":887}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":887,"lines":[{"gurmukhi":"ਕਉਨ ਭਰੋਸ ਭਟਾਨ ਕੋ ਭੂਪਤਿ ਭਾਰ ਪਰੇ ਜਿਨਿ ਭਾਰ ਸਹੈਂਗੇ।","roman":"Kaun bharos bhataan ko bhoopti bhaar pare jini bhaar sahainge |","meaning_en":"","page":887},{"gurmukhi":"ਭਾਜ ਹੈ ਭੀਰ ਭਯਾਨਕ ਹੁਐ ਕਰ ਭਾਰਥ ਸੋ ਨਹੀ ਭੇਰ ਚਹੈਂਗੇ।","roman":"Bhaaj hai bheer bhayaanak huai kar bhaarath so nahee bher chahainge |","meaning_en":"","page":887},{"gurmukhi":"ਏਕ ਉਪਚਾਰ ਨ ਚਾਲ ਹੈ ਰਾਜਨ ਮਿਤ੍ਰ ਸਬੈ ਮ੍ਰਿਤ ਨੀਰ ਬਹੈਂਗੇ।","roman":"Ek upchaar na chaal hai raajan mitr sabai mrit neer bahainge |","meaning_en":"","page":887},{"gurmukhi":"ਪੁਤ੍ਰ ਕਲਤ੍ਰ ਸਭੈ ਤੁਮਰੇ ਨ੍ਰਿਪ ਛੂਟਤ ਪ੍ਰਾਨ ਮਸਾਨ ਕਹੈਂਗੇ। ੧੬੨।","roman":"Putr kalatr sabhai tumre nrip chhootat praan masaan kahainge | 162 |","meaning_en":"","page":887}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","roman":"Paarasnaath baach machhindr so","meaning_en":"","page":887},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"","page":887},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":887,"lines":[{"gurmukhi":"ਮੁਨਿ ਕਉਨ ਹੈ ਵਹ ਰਾਉ। ਤਿਹ ਆਜ ਮੋਹਿ ਬਤਾਉ।","roman":"Muni kaun hai vah raau | tih aaj mohi bataau |","meaning_en":"","page":887},{"gurmukhi":"ਤਿਹ ਜੀਤ ਹੋ ਜਬ ਜਾਇ। ਤਬ ਭਾਖੀਅਉ ਮੁਹਿ ਰਾਇ। ੧੬੩।","roman":"Tih jeet ho jab jaai | tab bhaakheeau muhi raai | 163 |","meaning_en":"","page":887}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"","page":887},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"","page":887},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":887,"lines":[{"gurmukhi":"ਸੁਨ ਰਾਜ ਰਾਜਨ ਹੰਸ। ਭਵ ਭੂਮਿ ਕੇ ਅਵਤੰਸ।","roman":"Sun raaj raajan hans | bhav bhoomi ke avtans |","meaning_en":"","page":887},{"gurmukhi":"ਤੁਹਿ ਜੀਤਏ ਸਬ ਰਾਇ। ਪਰ ਸੋ ਨ ਜੀਤਯੋ ਜਾਇ। ੧੬੪।","roman":"Tuhi jeetae sab raai | par so na jeetyo jaai | 164 |","meaning_en":"","page":887}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":887,"lines":[{"gurmukhi":"ਅਬਿਬੇਕ ਹੈ ਤਿਹ ਨਾਉ। ਤਵ ਹੀਯ ਮੈ ਤਿਹ ਠਾਉ।","roman":"Abibek hai tih naau | tav heey mai tih thaau |","meaning_en":"","page":887},{"gurmukhi":"ਤਿਹ ਜੀਤ ਕਹੀ ਨ ਭੂਪ। ਵਹ ਹੈ ਸਰੂਪ ਅਨੂਪ। ੧੬੫।","roman":"Tih jeet kahee na bhoop | vah hai saroop anoop | 165 |","meaning_en":"","page":887}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":887},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":887,"lines":[{"gurmukhi":"ਬਲਿ ਮਹੀਪ ਜਿਨ ਛਲ੍ਯੋ ਬ੍ਰਹਮ ਬਾਵਨ ਬਸ ਕਿਨੋ।","roman":"Bali maheep jin chhalyo braham baavan bas kino |","meaning_en":"","page":887},{"gurmukhi":"ਕਿਸਨ ਬਿਸਨ ਜਿਨ ਹਰੇ ਦੰਡ ਰਘੁਪਤਿ ਤੇ ਲਿਨੋ।","roman":"Kisan bisan jin hare dand raghupti te lino |","meaning_en":"","page":887},{"gurmukhi":"ਦਸ ਗ੍ਰੀਵਹਿ ਜਿਨਿ ਹਰਾ ਸੁਭਟ ਸੁੰਭਾਸੁਰ ਖੰਡ੍ਯੋ।","roman":"Das greevhi jini haraa subhat sunbhaasur khandyo |","meaning_en":"","page":887},{"gurmukhi":"ਮਹਖਾਸੁਰ ਮਰਦੀਆ ਮਾਨ ਮਧੁ ਕੀਟ ਬਿਹੰਡ੍ਯੋ।","roman":"Mahkhaasur mardeeaa maan madhu keet bihandyo |","meaning_en":"","page":887},{"gurmukhi":"ਸੋਊ ਮਦਨ ਰਾਜ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਮੰਤ੍ਰੀ ਕੀਯੋ।","roman":"So'oo madan raaj raajaa nripti nrip abibek mantree keeyo |","meaning_en":"","page":887},{"gurmukhi":"ਜਿਹ ਦੇਵ ਦਈਤ ਗੰਧ੍ਰਬ ਮੁਨਿ ਜੀਤਿ ਅਡੰਡ ਡੰਡਹਿ ਲੀਯੋ। ੧੬੬।","roman":"Jih dev daeet gandhrab muni jeeti adand dandhi leeyo | 166 |","meaning_en":"","page":887}]},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":887,"lines":[{"gurmukhi":"ਜਵਨ ਕ੍ਰੁਧ ਜੁਧ ਕਰਣ ਕੈਰਵ ਰਣ ਘਾਏ।","roman":"Javan krudh judh karan kairav ran ghaae |","meaning_en":"","page":887},{"gurmukhi":"ਜਾਸੁ ਕੋਪ ਕੇ ਕੀਨ ਸੀਸ ਦਸ ਸੀਸ ਗਵਾਏ।","roman":"Jaasu kop ke keen sees das sees gavaae |","meaning_en":"","page":887},{"gurmukhi":"ਜਉਨ ਕ੍ਰੁਧ ਕੇ ਕੀਏ ਦੇਵ ਦਾਨਵ ਰਣਿ ਲੁਝੇ।","roman":"Jaun krudh ke kee'e dev daanav rani lujhe |","meaning_en":"","page":887},{"gurmukhi":"ਜਾਸੁ ਕ੍ਰੋਧ ਕੇ ਕੀਨ ਖਸਟ ਕੁਲ ਜਾਦਵ ਜੁਝੇ।","roman":"Jaasu krodh ke keen khasat kul jaadav jujhe |","meaning_en":"","page":887},{"gurmukhi":"ਸੋਊ ਤਾ ਸਮਾਨੁ ਸੈਨਾਧਿਪਤਿ ਜਿਦਿਨ ਰੋਸ ਵਹੁ ਆਇ ਹੈ।","roman":"So'oo taa samaanu sainaadhipti jidin ros vahu aai hai |","meaning_en":"","page":887},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨਹੋ ਨ੍ਰਿਪਤਿ ਅਵਰ ਸਮੁਹਿ ਕੋ ਜਾਇ ਹੈ। ੧੬੭।","roman":"Binu ik bibek sunho nripti avar samuhi ko jaai hai | 167 |","meaning_en":"","page":887}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","roman":"Paarasnaath baach machhindr so","meaning_en":"","page":888},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":888},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":888,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਮਛਿੰਦ੍ਰ ਬੈਨ ਕਹੋ ਤੁਹਿ ਬਾਤ ਬਿਚਛਨ।","roman":"Sunhu machhindr bain kaho tuhi baat bichchhan |","meaning_en":"","page":888},{"gurmukhi":"ਇਕ ਬਿਬੇਕ ਅਬਿਬੇਕ ਜਗਤ ਦ੍ਵੈ ਨ੍ਰਿਪਤਿ ਸੁਲਛਨ।","roman":"Ik bibek abibek jagat dvai nripti sulchhan |","meaning_en":"","page":888},{"gurmukhi":"ਬਡ ਜੋਧਾ ਦੁਹੂੰ ਸੰਗ ਬਡੇ ਦੋਊ ਆਪ ਧਨੁਰਧਰ।","roman":"Bad jodhaa duhoon sang bade do'oo aap dhanurdhar |","meaning_en":"","page":888},{"gurmukhi":"ਏਕ ਜਾਤਿ ਇਕ ਪਾਤਿ ਏਕ ਹੀ ਮਾਤ ਜੋਧਾਬਰ।","roman":"Ek jaati ik paati ek hee maat jodhaabar |","meaning_en":"","page":888},{"gurmukhi":"ਇਕ ਤਾਤ ਏਕ ਹੀ ਬੰਸ ਪੁਨਿ ਬੈਰ ਭਾਵ ਦੁਹ ਕਿਮ ਗਹੋ।","roman":"Ik taat ek hee bans puni bair bhaav duh kim gaho |","meaning_en":"","page":888},{"gurmukhi":"ਤਿਹ ਨਾਮ ਠਾਮ ਆਭਰਣ ਰਥ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਸਬ ਮੁਨਿ ਕਹੋ। ੧੬੮।","roman":"Tih naam thaam aabhran rath sasatr asatr sab muni kaho | 168 |","meaning_en":"","page":888}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"","page":888},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":888},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":888,"lines":[{"gurmukhi":"ਅਸਿਤ ਬਰਣ ਅਬਿਬੇਕ ਅਸਿਤ ਬਾਜੀ ਰਥ ਸੋਭਤ।","roman":"Asit baran abibek asit baajee rath sobhat |","meaning_en":"","page":888},{"gurmukhi":"ਅਸਿਤ ਬਸਤ੍ਰ ਤਿਹ ਅੰਗਿ ਨਿਰਖਿ ਨਾਰੀ ਨਰ ਲੋਭਤ।","roman":"Asit basatr tih angi nirkhi naaree nar lobhat |","meaning_en":"","page":888},{"gurmukhi":"ਅਸਿਤ ਸਾਰਥੀ ਅਗ੍ਰ ਅਸਿਤ ਆਭਰਣ ਰਥੋਤਮ।","roman":"Asit saarthee agr asit aabhran rathotam |","meaning_en":"","page":888},{"gurmukhi":"ਅਸਿਤ ਧਨੁਖ ਕਰਿ ਅਸਿਤ ਧੁਜਾ ਜਾਨੁਕ ਪੁਰਖੋਤਮ।","roman":"Asit dhanukh kari asit dhujaa jaanuk purkhotam |","meaning_en":"","page":888},{"gurmukhi":"ਇਹ ਛਬਿ ਨਰੇਸ ਅਬਿਬੇਕ ਨ੍ਰਿਪ ਜਗਤ ਜਯੰਕਰ ਮਾਨੀਯੈ।","roman":"Ih chhabi nares abibek nrip jagat jayankar maaneeyai |","meaning_en":"","page":888},{"gurmukhi":"ਅਨਜਿਤ ਜਾਸੁ ਕਹ ਨ ਤਜੋ ਕ੍ਰਿਸਨ ਰੂਪ ਤਿਹ ਜਾਨੀਯੈ। ੧੬੯।","roman":"Anjit jaasu kah na tajo krisan roop tih jaaneeyai | 169 |","meaning_en":"","page":888}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":888,"lines":[{"gurmukhi":"ਪੁਹਪ ਧਨੁਖ ਅਲਿ ਪਨਚ ਮਤਸ ਜਿਹ ਧੁਜਾ ਬਿਰਾਜੈ।","roman":"Puhap dhanukh ali panach matas jih dhujaa biraajai |","meaning_en":"","page":888},{"gurmukhi":"ਬਾਜਤ ਝਾਝਰ ਤੂਰ ਮਧੁਰ ਬੀਨਾ ਧੁਨਿ ਬਾਜੈ।","roman":"Baajat jhaajhar toor madhur beenaa dhuni baajai |","meaning_en":"","page":888},{"gurmukhi":"ਸਬ ਬਜੰਤ੍ਰ ਜਿਹ ਸੰਗ ਬਜਤ ਸੁੰਦਰ ਛਬ ਸੋਹਤ।","roman":"Sab bajantr jih sang bajat sundar chhab sohat |","meaning_en":"","page":888},{"gurmukhi":"ਸੰਗ ਸੈਨ ਅਬਲਾ ਸੰਬੂਹ ਸੁਰ ਨਰ ਮੁਨਿ ਮੋਹਤ।","roman":"Sang sain ablaa sanbooh sur nar muni mohat |","meaning_en":"","page":888},{"gurmukhi":"ਅਸ ਮਦਨ ਰਾਜ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਕ੍ਰੁਧ ਕਰਿ ਧਾਇ ਹੈ।","roman":"As madan raaj raajaa nripti jidin krudh kari dhaai hai |","meaning_en":"","page":888},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਤਾ ਕੇ ਸਮੁਹਿ ਅਉਰ ਦੂਸਰ ਕੋ ਜਾਇ ਹੈ। ੧੭੦।","roman":"Binu ik bibek taa ke samuhi aur doosar ko jaai hai | 170 |","meaning_en":"","page":888}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":888,"lines":[{"gurmukhi":"ਕਰਤ ਨ੍ਰਿਤ ਸੁੰਦਰੀ ਬਜਤ ਬੀਨਾ ਧੁਨਿ ਮੰਗਲ।","roman":"Karat nrit sundree bajat beenaa dhuni mangal |","meaning_en":"","page":888},{"gurmukhi":"ਉਪਜਤ ਰਾਗ ਸੰਬੂਹ ਬਜਤ ਬੈਰਾਰੀ ਬੰਗਲਿ।","roman":"Upjat raag sanbooh bajat bairaaree bangli |","meaning_en":"","page":888},{"gurmukhi":"ਭੈਰਵ ਰਾਗ ਬਸੰਤ ਦੀਪ ਹਿੰਡੋਲ ਮਹਾ ਸੁਰ।","roman":"Bhairav raag basant deep hindol mahaa sur |","meaning_en":"","page":888},{"gurmukhi":"ਉਘਟਤ ਤਾਨ ਤਰੰਗ ਸੁਨਤ ਰੀਝਤ ਧੁਨਿ ਸੁਰ ਨਰ।","roman":"Ughtat taan tarang sunat reejhat dhuni sur nar |","meaning_en":"","page":888},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਰਿਤੁ ਰਾਜ ਨ੍ਰਿਪ ਜਿਦਿਨ ਰੋਸ ਕਰਿ ਧਾਇ ਹੈ।","roman":"Ih chhabi prabhaav ritu raaj nrip jidin ros kari dhaai hai |","meaning_en":"","page":888},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਤਾ ਕੇ ਨ੍ਰਿਪਤਿ ਅਉਰ ਸਮੁਹਿ ਕੋ ਜਾਇ ਹੈ। ੧੭੧।","roman":"Binu ik bibek taa ke nripti aur samuhi ko jaai hai | 171 |","meaning_en":"","page":888}]},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":889,"lines":[{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਸੁਧ ਮਲਾਰ ਬਿਭਾਸ ਸਰਬਿ ਗਨਿ।","roman":"Sorthi saarang sudh malaar bibhaas sarbi gani |","meaning_en":"","page":889},{"gurmukhi":"ਰਾਮਕਲੀ ਹਿੰਡੋਲ ਗੌਡ ਗੂਜਰੀ ਮਹਾ ਧੁਨਿ।","roman":"Raamaklee hindol gaud goojree mahaa dhuni |","meaning_en":"","page":889},{"gurmukhi":"ਲਲਤ ਪਰਜ ਗਵਰੀ ਮਲਾਰ ਕਾਨੜਾ ਮਹਾ ਛਬਿ।","roman":"Lalat paraj gavree malaar kaanraa mahaa chhabi |","meaning_en":"","page":889},{"gurmukhi":"ਜਾਹਿ ਬਿਲੋਕਤ ਬੀਰ ਸਰਬ ਤੁਮਰੇ ਜੈ ਹੈ ਦਬਿ।","roman":"Jaahi bilokat beer sarab tumre jai hai dabi |","meaning_en":"","page":889},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਰੇਸ ਰਿਤੁ ਰਾਜ ਨ੍ਰਿਪ ਮਦਨ ਸੂਅਨ ਜਬ ਗਰਜ ਹੈ।","roman":"Ih bidhi nares ritu raaj nrip madan sooan jab garaj hai |","meaning_en":"","page":889},{"gurmukhi":"ਬਿਨੁ ਇਕ ਗ੍ਯਾਨ ਸੁਨ ਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਦੂਸਰ ਕੋ ਬਰਜਿ ਹੈ। ੧੭੨।","roman":"Binu ik gyaan sun ho nripti su aur doosar ko barji hai | 172 |","meaning_en":"","page":889}]},{"type":"verse","number":[173],"number_text":"੧੭੩।","page":889,"lines":[{"gurmukhi":"ਕਊਧਤ ਦਾਮਨਿ ਸਘਨ ਸਘਨ ਘੋਰਤ ਚਹੁਦਿਸ ਘਨ।","roman":"Kaoodhat daamni saghan saghan ghorat chahudis ghan |","meaning_en":"","page":889},{"gurmukhi":"ਮੋਹਿਤ ਭਾਮਿਨ ਸਘਨ ਡਰਤ ਬਿਰਹਨਿ ਤ੍ਰਿਯ ਲਖਿ ਮਨਿ।","roman":"Mohit bhaamin saghan darat birahni triy lakhi mani |","meaning_en":"","page":889},{"gurmukhi":"ਬੋਲਤ ਦਾਦੁਰ ਮੋਰ ਸਘਨ ਝਿਲੀ ਝਿੰਕਾਰਤ।","roman":"Bolat daadur mor saghan jhilee jhinkaarat |","meaning_en":"","page":889},{"gurmukhi":"ਦੇਖਤ ਦ੍ਰਿਗਨ ਪ੍ਰਭਾਵ ਅਮਿਤ ਮੁਨਿ ਮਨ ਬ੍ਰਿਤ ਹਾਰਤ।","roman":"Dekhat drigan prabhaav amit muni man brit haarat |","meaning_en":"","page":889},{"gurmukhi":"ਇਹ ਬਿਧਿ ਹੁਲਾਸ ਮਦਨਜ ਦੂਸਰ ਜਿਦਿਨ ਚਟਕ ਦੈ ਸਟਕ ਹੈ।","roman":"Ih bidhi hulaas madnaj doosar jidin chatak dai satak hai |","meaning_en":"","page":889},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨਹੋ ਨ੍ਰਿਪਤਿ ਅਉਰ ਦੂਸਰ ਕੋ ਹਟਕ ਹੇ। ੧੭੩।","roman":"Binu ik bibek sunho nripti aur doosar ko hatak he | 173 |","meaning_en":"","page":889}]},{"type":"verse","number":[174],"number_text":"੧੭੪।","page":889,"lines":[{"gurmukhi":"ਤ੍ਰਿਤੀਆ ਪੁਤ੍ਰ ਅਨੰਦ ਜਿਦਿਨ ਸਸਤ੍ਰਨ ਕਹੁ ਧਰਿ ਹੈ।","roman":"Triteeaa putr anand jidin sastran kahu dhari hai |","meaning_en":"","page":889},{"gurmukhi":"ਕਰਿ ਹੈ ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਸੁ ਰਣ ਸੁਰ ਨਰ ਮੁਨਿ ਡਰਿ ਹੈ।","roman":"Kari hai chitr bachitr su ran sur nar muni dari hai |","meaning_en":"","page":889},{"gurmukhi":"ਕੋ ਭਟ ਧਰਿ ਹੈ ਧੀਰ ਜਿਦਿਨ ਸਾਮੁਹਿ ਵਹ ਐ ਹੈ।","roman":"Ko bhat dhari hai dheer jidin saamuhi vah ai hai |","meaning_en":"","page":889},{"gurmukhi":"ਸਭ ਕੋ ਤੇਜ ਪ੍ਰਤਾਪ ਛਿਨਕ ਭੀਤਰ ਹਰ ਲੈ ਹੈ।","roman":"Sabh ko tej prataap chhinak bheetar har lai hai |","meaning_en":"","page":889},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਨੰਦ ਦੁਰ ਧਰਖ ਭਟ ਜਿਦਿਨ ਸਸਤ੍ਰ ਗਹ ਮਿਕ ਹੈ।","roman":"Ih bidhi anand dur dharakh bhat jidin sasatr gah mik hai |","meaning_en":"","page":889},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨਿ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਦੂਸਰਿ ਟਿਕ ਹੈ। ੧੭੪।","roman":"Binu ik dheeraj suni re nripti su aur na doosri tik hai | 174 |","meaning_en":"","page":889}]},{"type":"verse","number":[175],"number_text":"੧੭੫।","page":889,"lines":[{"gurmukhi":"ਰਤਨ ਜਟਤ ਰਥ ਸੁਭਤ ਖਚਿਤ ਬਜ੍ਰਨ ਮੁਕਤਾਫਲ।","roman":"Ratan jatat rath subhat khachit bajran muktaaphal |","meaning_en":"","page":889},{"gurmukhi":"ਹੀਰ ਚੀਰ ਆਭਰਣ ਧਰੇ ਸਾਰਥੀ ਮਹਾਬਲ।","roman":"Heer cheer aabhran dhare saarthee mahaabal |","meaning_en":"","page":889},{"gurmukhi":"ਕਨਕ ਦੇਖ ਕੁਰਰਾਤ ਕਠਨ ਕਾਮਿਨ ਬ੍ਰਿਤ ਹਾਰਤ।","roman":"Kanak dekh kurraat kathan kaamin brit haarat |","meaning_en":"","page":889},{"gurmukhi":"ਤਨਿ ਪਟੰਬਰ ਜਰਕਸੀ ਪਰਮ ਭੂਖਨ ਤਨ ਧਾਰਤ।","roman":"Tani patanbar jaraksee param bhookhan tan dhaarat |","meaning_en":"","page":889},{"gurmukhi":"ਇਹ ਛਬਿ ਅਨੰਦ ਮਦਨਜ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਗਰਜ ਦਲ ਗਾਹਿ ਹੈ।","roman":"Ih chhabi anand madnaj nripti jidin garaj dal gaahi hai |","meaning_en":"","page":889},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨਿ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਸਮੁਹ ਕੋ ਜਾਹਿ ਹੈ। ੧੭੫।","roman":"Binu ik dheeraj suni re nripti su aur samuh ko jaahi hai | 175 |","meaning_en":"","page":889}]},{"type":"verse","number":[176],"number_text":"੧੭੬।","page":889,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਸਾਰਥੀ ਧੂਮ੍ਰ ਬਾਜੀਰਥ ਛਾਜਤ।","roman":"Dhoomr baran saarthee dhoomr baajeerath chhaajat |","meaning_en":"","page":889},{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਆਭਰਣ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮੁਨਿ ਲਾਜਤ।","roman":"Dhoomr baran aabhran nirkhi sur nar muni laajat |","meaning_en":"","page":889},{"gurmukhi":"ਧੂਮ੍ਰ ਨੈਨ ਧੂਮਰੋ ਗਾਤ ਧੂਮਰ ਤਿਹ ਭੂਖਨ।","roman":"Dhoomr nain dhoomro gaat dhoomar tih bhookhan |","meaning_en":"","page":889},{"gurmukhi":"ਧੂਮ੍ਰ ਬਦਨ ਤੇ ਬਮਤ ਸਰਬ ਸਤ੍ਰੂ ਕੁਲ ਦੂਖਨ।","roman":"Dhoomr badan te bamat sarab satroo kul dookhan |","meaning_en":"","page":889},{"gurmukhi":"ਅਸ ਭਰਮ ਮਦਨ ਚਤੁਰਥ ਸੁਵਨ ਜਿਦਿਨ ਰੋਸ ਕਰਿ ਧਾਇ ਹੈ।","roman":"As bharam madan chaturath suvan jidin ros kari dhaai hai |","meaning_en":"","page":889},{"gurmukhi":"ਦਲ ਲੂਟ ਕੂਟ ਤੁਮਰੋ ਨ੍ਰਿਪਤਿ ਸੁ ਸਰਬ ਛਿਨਕ ਮਹਿ ਜਾਇ ਹੈ। ੧੭੬।","roman":"Dal loot koot tumro nripti su sarab chhinak mahi jaai hai | 176 |","meaning_en":"","page":889}]},{"type":"verse","number":[177],"number_text":"੧੭੭।","page":890,"lines":[{"gurmukhi":"ਅਉਰ ਅਉਰ ਜੇ ਸੁਭਟਿ ਗਨੋ ਤਿਹ ਨਾਮ ਬਿਚਛਨ।","roman":"Aur aur je subhti gano tih naam bichchhan |","meaning_en":"","page":890},{"gurmukhi":"ਬਡ ਜੋਧਾ ਬਡ ਸੂਰ ਬਡੇ ਜਿਤਵਾਰ ਸੁਲੱਛਨ।","roman":"Bad jodhaa bad soor bade jitvaar sulcchhan |","meaning_en":"","page":890},{"gurmukhi":"ਕਲਹਿ ਨਾਮ ਇਕ ਨਾਰਿ ਮਹਾ ਕਲ ਰੂਪ ਕਲਹ ਕਰ।","roman":"Kalhi naam ik naari mahaa kal roop kalah kar |","meaning_en":"","page":890},{"gurmukhi":"ਲੋਗ ਚਤੁਰਦਸ ਮਾਝਿ ਜਾਸੁ ਛੋਰਾ ਨਹੀ ਸੁਰ ਨਰ।","roman":"Log chaturdas maajhi jaasu chhoraa nahee sur nar |","meaning_en":"","page":890},{"gurmukhi":"ਸਬ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਭੀਤਰ ਨਿਪੁਣ ਅਤਿ ਪ੍ਰਭਾਵ ਤਿਹ ਜਾਨੀਐ।","roman":"Sab sasatr asatr bheetar nipun ati prabhaav tih jaaneeai |","meaning_en":"","page":890},{"gurmukhi":"ਸਬ ਦੇਸ ਭੇਸ ਅਰੁ ਰਾਜ ਸਬ ਤ੍ਰਾਸ ਜਵਨ ਕੋ ਮਾਨੀਐ। ੧੭੭।","roman":"Sab des bhes aru raaj sab traas javan ko maaneeai | 177 |","meaning_en":"","page":890}]},{"type":"verse","number":[178],"number_text":"੧੭੮।","page":890,"lines":[{"gurmukhi":"ਬੈਰ ਨਾਮ ਇਕ ਬੀਰ ਮਹਾ ਦੁਰ ਧਰਖ ਅਜੈ ਰਣਿ।","roman":"Bair naam ik beer mahaa dur dharakh ajai rani |","meaning_en":"","page":890},{"gurmukhi":"ਕਬਹੁ ਦੀਨ ਨਹੀ ਪੀਠਿ ਅਨਿਕ ਜੀਤੇ ਜਿਹ ਨ੍ਰਿਪ ਗਣ।","roman":"Kabhu deen nahee peethi anik jeete jih nrip gan |","meaning_en":"","page":890},{"gurmukhi":"ਲੋਚਨ ਸ੍ਰੌਣਤ ਬਰਣ ਅਰੁਣ ਸਬ ਸਸਤ੍ਰ ਅੰਗਿ ਤਿਹ।","roman":"Lochan sraunat baran arun sab sasatr angi tih |","meaning_en":"","page":890},{"gurmukhi":"ਰਵਿ ਪ੍ਰਕਾਸ ਸਰ ਧੁਜਾ ਅਰੁਣ ਲਾਜਤ ਲਖਿ ਛਬਿ ਜਿਹ।","roman":"Ravi prakaas sar dhujaa arun laajat lakhi chhabi jih |","meaning_en":"","page":890},{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੈਰ ਬੀਰਾ ਬਡੈ ਜਿਦਿਨ ਕ੍ਰੁਧ ਕਰਿ ਗਰਜਿ ਹੈ।","roman":"Ih bhaati bair beeraa badai jidin krudh kari garji hai |","meaning_en":"","page":890},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਦੂਸਰ ਬਰਜਿ ਹੈ। ੧੭੮।","roman":"Binu ek saanti sun re nripti su aur na doosar barji hai | 178 |","meaning_en":"","page":890}]},{"type":"verse","number":[179],"number_text":"੧੭੯।","page":890,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਧੁਜਾ ਰਥ ਧੂਮ੍ਰ ਧੂਮ੍ਰ ਸਾਰਥੀ ਬਿਰਾਜਤ।","roman":"Dhoomr dhujaa rath dhoomr dhoomr saarthee biraajat |","meaning_en":"","page":890},{"gurmukhi":"ਧੂਮ੍ਰ ਬਸਤ੍ਰ ਤਨ ਧਰੋ ਨਿਰਖਿ ਧੂਅਰੋ ਮਨਿ ਲਾਜਤ।","roman":"Dhoomr basatr tan dharo nirkhi dhooaro mani laajat |","meaning_en":"","page":890},{"gurmukhi":"ਧੂਮ੍ਰ ਧਨੁਖ ਕਰ ਛਕ੍ਯੋ ਬਾਨ ਧੂਮਰੇ ਸੁਹਾਏ।","roman":"Dhoomr dhanukh kar chhakyo baan dhoomre suhaae |","meaning_en":"","page":890},{"gurmukhi":"ਸੁਰ ਨਰ ਨਾਗ ਭੁਜੰਗ ਜਛ ਅਰੁ ਅਸੁਰ ਲਜਾਏ।","roman":"Sur nar naag bhujang jachh aru asur lajaae |","meaning_en":"","page":890},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਆਲਸ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟ ਹੈ।","roman":"Ih chhabi prabhaav aalas nripti jidin judh kah jut hai |","meaning_en":"","page":890},{"gurmukhi":"ਉਦਮ ਬਿਹੀਨ ਸੁਨ ਰੇ ਨ੍ਰਿਪਤਿ ਅਉਰ ਸਕਲ ਦਲ ਫੁਟ ਹੈ। ੧੭੯।","roman":"Udam biheen sun re nripti aur sakal dal phut hai | 179 |","meaning_en":"","page":890}]},{"type":"verse","number":[180],"number_text":"੧੮੦।","page":890,"lines":[{"gurmukhi":"ਹਰਿਤ ਧੁਜਾ ਅਰੁ ਧਨੁਖ ਹਰਿਤ ਬਾਜੀ ਰਥ ਸੋਭੰਤ।","roman":"Harit dhujaa aru dhanukh harit baajee rath sobhant |","meaning_en":"","page":890},{"gurmukhi":"ਹਰਤ ਬਸਤ੍ਰ ਤਨ ਧਰੇ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮਨ ਮੋਹੰਤ।","roman":"Harat basatr tan dhare nirkhi sur nar man mohant |","meaning_en":"","page":890},{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਭ੍ਰਮਨ ਬਘੂਲਾ ਲਖਿ ਲਜਿਤ।","roman":"Pavan beg rath chalat bhraman baghoolaa lakhi lajit |","meaning_en":"","page":890},{"gurmukhi":"ਸੁਨਤ ਸ੍ਰਵਨ ਚਕ ਸਬਦ ਮੇਘ ਮਨ ਮਹਿ ਸੁਖੁ ਸਜਿਤ।","roman":"Sunat sravan chak sabad megh man mahi sukhu sajit |","meaning_en":"","page":890},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਤਾਪ ਮਦ ਨਾਮ ਨ੍ਰਿਪ ਜਿਦਿਨ ਤੁਰੰਗ ਨਚਾਇ ਹੈ।","roman":"Ih chhabi prataap mad naam nrip jidin turang nachaai hai |","meaning_en":"","page":890},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨ ਲੈ ਨ੍ਰਿਪਤਿ ਸਸੁ ਸਮਰਿ ਨ ਦੂਸਰ ਜਾਇ ਹੈ। ੧੮੦।","roman":"Binu ik bibek sun lai nripti sasu samri na doosar jaai hai | 180 |","meaning_en":"","page":890}]},{"type":"verse","number":[181],"number_text":"੧੮੧।","page":890,"lines":[{"gurmukhi":"ਅਸਿਤ ਧੁਜਾ ਸਾਰਥੀ ਅਸਿਤ ਬਸਤ੍ਰੈ ਅਰੁ ਬਾਜੀ।","roman":"Asit dhujaa saarthee asit bastrai aru baajee |","meaning_en":"","page":890},{"gurmukhi":"ਅਸਿਤ ਕਵਚ ਤਨ ਕਸੇ ਤਜਤ ਬਾਣਨ ਕੀ ਰਾਜੀ।","roman":"Asit kavach tan kase tajat baanan kee raajee |","meaning_en":"","page":890},{"gurmukhi":"ਅਸਿਤ ਸਕਲ ਤਿਹ ਬਰਣ ਅਸਿਤ ਲੋਚਨ ਦੁਖ ਮਰਦਨ।","roman":"Asit sakal tih baran asit lochan dukh mardan |","meaning_en":"","page":890},{"gurmukhi":"ਅਸਿਤ ਮਣਿਣ ਕੇ ਸਕਲ ਅੰਗਿ ਭੁਖਣ ਰੁਚਿ ਬਰਧਨ।","roman":"Asit manin ke sakal angi bhukhan ruchi bardhan |","meaning_en":"","page":890},{"gurmukhi":"ਅਸ ਕੁਵ੍ਰਿਤਿ ਬੀਰ ਦੁਰ ਧਰਖ ਅਤਿ ਜਿਦਿਨ ਸਮਰ ਕਹ ਸਜਿ ਹੈ।","roman":"As kuvriti beer dur dharakh ati jidin samar kah saji hai |","meaning_en":"","page":890},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਬੀਰਤ ਤਜਿ ਅਉਰ ਸਕਲ ਦਲ ਭਜਿ ਹੈ। ੧੮੧।","roman":"Binu ik dheeraj beerat taji aur sakal dal bhaji hai | 181 |","meaning_en":"","page":890}]},{"type":"verse","number":[182],"number_text":"੧੮੨।","page":891,"lines":[{"gurmukhi":"ਚਰਮ ਬਰਮ ਕਹ ਧਰੇ ਧਰਮ ਛਤ੍ਰੀ ਕੋ ਧਾਰਤ।","roman":"Charam baram kah dhare dharam chhatree ko dhaarat |","meaning_en":"","page":891},{"gurmukhi":"ਅਜੈ ਜਾਨਿ ਆਪਨਹਿ ਸਰਬ ਰਣ ਸੁਭਟ ਪਚਾਰਤ।","roman":"Ajai jaani aapanhi sarab ran subhat pachaarat |","meaning_en":"","page":891},{"gurmukhi":"ਧਰਨ ਨ ਆਗੈ ਧੀਰ ਬੀਰ ਜਿਹ ਸਮੁਹ ਧਾਵਤ।","roman":"Dharan na aagai dheer beer jih samuh dhaavat |","meaning_en":"","page":891},{"gurmukhi":"ਸੁਰ ਅਸੁਰ ਅਰੁ ਨਰ ਨਾਰਿ ਜਛ ਗੰਧ੍ਰਬ ਗੁਨ ਗਾਵਤ।","roman":"Sur asur aru nar naari jachh gandhrab gun gaavat |","meaning_en":"","page":891},{"gurmukhi":"ਇਹ ਬਿਧਿ ਗੁਮਾਨ ਜਾ ਦਿਨ ਗਰਜ ਪਰਮ ਕ੍ਰੋਧ ਕਰ ਢੂਕ ਹੈ।","roman":"Ih bidhi gumaan jaa din garaj param krodh kar dhook hai |","meaning_en":"","page":891},{"gurmukhi":"ਬਿਨੁ ਇਕ ਸੀਲ ਸੁਨ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪਾਣਿ ਸੁ ਅਉਰ ਸਕਲ ਦਲ ਹੂਕ ਹੈ। ੧੮੨।","roman":"Binu ik seel sun nripti nripaani su aur sakal dal hook hai | 182 |","meaning_en":"","page":891}]},{"type":"verse","number":[183],"number_text":"੧੮੩।","page":891,"lines":[{"gurmukhi":"ਕੜਕਿ ਕ੍ਰੋਧ ਕਰਿ ਚੜਗੁ ਭੜਕਿ ਭਾਦਵਿ ਜ੍ਯੋਂ ਗਜਤ।","roman":"Karki krodh kari chargu bharki bhaadvi jyon gajat |","meaning_en":"","page":891},{"gurmukhi":"ਸੜਕ ਤੇਗ ਦਾਮਿਨ ਤੜਕ ਤੜਭੜ ਰਣ ਸਜਤ।","roman":"Sarak teg daamin tarak tarbhar ran sajat |","meaning_en":"","page":891},{"gurmukhi":"ਲੁੜਕ ਲੁਥ ਬਿਥੁਰਗ ਸੇਲ ਸਾਮੁਹਿ ਹ੍ਵੈ ਘਲਤ।","roman":"Lurak luth bithurag sel saamuhi hvai ghalat |","meaning_en":"","page":891},{"gurmukhi":"ਜਿਦਿਨ ਰੋਸ ਰਾਵਤ ਰਣਹਿ ਦੂਸਰ ਕੋ ਝਲਤ।","roman":"Jidin ros raavat ranhi doosar ko jhalat |","meaning_en":"","page":891},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਪਮਾਨ ਤਿਹ ਭ੍ਰਾਤ ਭਨ ਜਿਦਿਨ ਰੁਦ੍ਰ ਰਸ ਮਚਿ ਹੈ।","roman":"Ih bidhi apmaan tih bhraat bhan jidin rudr ras machi hai |","meaning_en":"","page":891},{"gurmukhi":"ਬਿਨ ਇਕ ਸੀਲ ਦੁਸੀਲ ਭਟ ਸੁ ਅਉਰ ਕਵਣ ਰਣਿ ਰਚਿ ਹੈ। ੧੮੩।","roman":"Bin ik seel duseel bhat su aur kavan rani rachi hai | 183 |","meaning_en":"","page":891}]},{"type":"verse","number":[184],"number_text":"੧੮੪।","page":891,"lines":[{"gurmukhi":"ਧਨੁਖ ਮੰਡਲਾਕਾਰ ਲਗਤ ਜਾ ਕੋ ਸਦੀਵ ਰਣ।","roman":"Dhanukh mandlaakaar lagat jaa ko sadeev ran |","meaning_en":"","page":891},{"gurmukhi":"ਨਿਰਖਤ ਤੇਜ ਪ੍ਰਭਾਵ ਭਟਕ ਭਾਜਤ ਹੈ ਭਟ ਗਣ।","roman":"Nirkhat tej prabhaav bhatak bhaajat hai bhat gan |","meaning_en":"","page":891},{"gurmukhi":"ਕਉਨ ਬਾਧਿ ਤੇ ਧੀਰ ਬੀਰ ਨਿਰਖਤ ਦੁਤਿ ਲਾਜਤ।","roman":"Kaun baadhi te dheer beer nirkhat duti laajat |","meaning_en":"","page":891},{"gurmukhi":"ਨਹਨ ਜੁਧ ਠਹਰਾਤਿ ਤ੍ਰਸਤ ਦਸਹੂੰ ਦਿਸ ਭਾਜਤ।","roman":"Nahan judh thahraati trasat dashoon dis bhaajat |","meaning_en":"","page":891},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਨਰਥ ਸਮਰਥ ਰਣਿ ਜਿਦਿਨ ਤੁਰੰਗ ਮਟਕ ਹੈ।","roman":"Ih bidhi anrath samrath rani jidin turang matak hai |","meaning_en":"","page":891},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰ ਸੁਨ ਬੀਰ ਬਰੁ ਸੁ ਦੂਸਰ ਕਉਨ ਹਟਕਿ ਹੈ। ੧੮੪।","roman":"Binu ik dheer sun beer baru su doosar kaun hatki hai | 184 |","meaning_en":"","page":891}]},{"type":"verse","number":[185],"number_text":"੧੮੫।","page":891,"lines":[{"gurmukhi":"ਪ੍ਰੀਤ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਧੁਜਾ ਪੀਅਰੀ ਰਥ ਧਾਰੇ।","roman":"Preet basatr tani dhare dhujaa peearee rath dhaare |","meaning_en":"","page":891},{"gurmukhi":"ਪੀਤ ਮਨੁਖ ਕਰਿ ਸੋਭ ਮਾਨ ਰਤਿ ਪਤਿ ਕੋ ਟਾਰੇ।","roman":"Peet manukh kari sobh maan rati pati ko taare |","meaning_en":"","page":891},{"gurmukhi":"ਪੀਤ ਬਰਣ ਸਾਰਥੀ ਪੀਤ ਬਰਣੈ ਰਥ ਬਾਜੀ।","roman":"Peet baran saarthee peet barnai rath baajee |","meaning_en":"","page":891},{"gurmukhi":"ਪੀਤ ਬਰਨ ਕੋ ਬਾਣ ਖੇਤਿ ਚੜਿ ਗਰਜਤ ਗਾਜੀ।","roman":"Peet baran ko baan kheti chari garjat gaajee |","meaning_en":"","page":891},{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੈਰ ਸੂਰਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਗਰਜਿ ਦਲ ਗਾਹਿ ਹੈ।","roman":"Ih bhaati bair sooraa nripti jidin garji dal gaahi hai |","meaning_en":"","page":891},{"gurmukhi":"ਬਿਨੁ ਇਕ ਗਿਆਨ ਸਵਧਾਨ ਹ੍ਵੈ ਅਉਰ ਸਮਰ ਕੋ ਚਾਹਿ ਹੈ। ੧੮੫।","roman":"Binu ik giaan savdhaan hvai aur samar ko chaahi hai | 185 |","meaning_en":"","page":891}]},{"type":"verse","number":[186],"number_text":"੧੮੬।","page":891,"lines":[{"gurmukhi":"ਮਲਿਤ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਮਲਿਤ ਭੂਖਨ ਰਥ ਬਾਧੇ।","roman":"Malit basatr tani dhare malit bhookhan rath baadhe |","meaning_en":"","page":891},{"gurmukhi":"ਮਲਿਤ ਮੁਕਟ ਸਿਰ ਧਰੇ ਪਰਮ ਬਾਣਣ ਕਹ ਸਾਧੇ।","roman":"Malit mukat sir dhare param baanan kah saadhe |","meaning_en":"","page":891},{"gurmukhi":"ਮਲਿਤ ਬਰਣ ਸਾਰਥੀ ਮਲਿਤ ਤਾਹੂੰ ਆਭੂਖਨ।","roman":"Malit baran saarthee malit taahoon aabhookhan |","meaning_en":"","page":891},{"gurmukhi":"ਮਲਯਾਗਰ ਕੀ ਗੰਧੰ ਸਕਲ ਸਤ੍ਰੂ ਕੁਲ ਦੂਖਨ।","roman":"Malyaagar kee gandhan sakal satroo kul dookhan |","meaning_en":"","page":891},{"gurmukhi":"ਇਹ ਭਾਤਿ ਨਿੰਦ ਅਨਧਰ ਸੁਭਟ ਜਿਦਿਨ ਅਯੋਧਨ ਮਚਿ ਹੈ।","roman":"Ih bhaati nind andhar subhat jidin ayodhan machi hai |","meaning_en":"","page":891},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨ ਬੀਰਬਰ ਸੁ ਆਉਰ ਕਵਣ ਰਣਿ ਰਚਿ ਹੈ। ੧੮੬।","roman":"Binu ik dheeraj sun beerbar su aaur kavan rani rachi hai | 186 |","meaning_en":"","page":891}]},{"type":"verse","number":[187],"number_text":"੧੮੭।","page":892,"lines":[{"gurmukhi":"ਘੋਰ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਘੋਰ ਪਗੀਆ ਸਿਰ ਬਾਧੇ।","roman":"Ghor basatr tani dhare ghor pageeaa sir baadhe |","meaning_en":"","page":892},{"gurmukhi":"ਘੋਰ ਬਰਣ ਸਿਰਿ ਮੁਕਟ ਘੋਰ ਸਤ੍ਰਨ ਕਹ ਸਾਧੇ।","roman":"Ghor baran siri mukat ghor satran kah saadhe |","meaning_en":"","page":892},{"gurmukhi":"ਘੋਰ ਮੰਤ੍ਰ ਮੁਖ ਜਪਤ ਪਰਮ ਆਘੋਰ ਰੂਪ ਤਿਹ।","roman":"Ghor mantr mukh japat param aaghor roop tih |","meaning_en":"","page":892},{"gurmukhi":"ਲਖਤ ਸ੍ਵਰਗ ਭਹਰਾਤ ਘੋਰ ਆਭਾ ਲਖਿ ਕੇ ਜਿਹ।","roman":"Lakhat svarag bhahraat ghor aabhaa lakhi ke jih |","meaning_en":"","page":892},{"gurmukhi":"ਇਹ ਭਾਤਿ ਨਰਕ ਦੁਰ ਧਰਖ ਭਟ ਜਿਦਿਨ ਰੋਸਿ ਰਣਿ ਆਇ ਹੈ।","roman":"Ih bhaati narak dur dharakh bhat jidin rosi rani aai hai |","meaning_en":"","page":892},{"gurmukhi":"ਬਿਨੁ ਇਕ ਹਰਿਨਾਮ ਸੁਨ ਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਕੋਇ ਬਚਾਇ ਹੈ। ੧੮੭।","roman":"Binu ik harinaam sun ho nripti su aur na koi bachaai hai | 187 |","meaning_en":"","page":892}]},{"type":"verse","number":[188],"number_text":"੧੮੮।","page":892,"lines":[{"gurmukhi":"ਸਮਟ ਸਾਗ ਸੰਗ੍ਰਹੈ ਸੇਲ ਸਾਮੁਹਿ ਹ੍ਵੈ ਸੁਟੈ।","roman":"Samat saag sangrahai sel saamuhi hvai sutai |","meaning_en":"","page":892},{"gurmukhi":"ਕਲਿਤ ਕ੍ਰੋਧ ਸੰਜੁਗਤਿ ਗਲਿਤ ਗੈਵਰ ਜਿਯੋਂ ਜੁਟੈ।","roman":"Kalit krodh sanjugti galit gaivar jiyon jutai |","meaning_en":"","page":892},{"gurmukhi":"ਇਕ ਇਕ ਬਿਨੁ ਕੀਨ ਇਕ ਤੇ ਇਕ ਨ ਚਲੈ।","roman":"Ik ik binu keen ik te ik na chalai |","meaning_en":"","page":892},{"gurmukhi":"ਇਕ ਇਕ ਸੰਗ ਭਿੜੈ ਸਸਤ੍ਰ ਸਨਮੁਖ ਹ੍ਵੈ ਝਲੈ।","roman":"Ik ik sang bhirai sasatr sanmukh hvai jhalai |","meaning_en":"","page":892},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਸੀਲ ਦੁਸੀਲ ਭਟ ਸਹਤ ਕੁਚੀਲ ਗਰਜਿ ਹੈ।","roman":"Ih bidhi naseel duseel bhat sahat kucheel garji hai |","meaning_en":"","page":892},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸੁਚਹਿ ਸੁਨਿ ਨ੍ਰਿਪ ਨ੍ਰਿਪਣਿ ਸੁ ਅਉਰ ਨ ਕੋਊ ਬਰਜਿ ਹੈ। ੧੮੮।","roman":"Binu ek suchhi suni nrip nripni su aur na ko'oo barji hai | 188 |","meaning_en":"","page":892}]},{"type":"verse","number":[189],"number_text":"੧੮੯।","page":892,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਦੋਊ ਨਿਪੁਣ ਨਿਪੁਣ ਸਬ ਬੇਦ ਸਾਸਤ੍ਰ ਕਰ।","roman":"Sasatr asatr do'oo nipun nipun sab bed saasatr kar |","meaning_en":"","page":892},{"gurmukhi":"ਅਰੁਣ ਨੇਤ੍ਰ ਅਰੁ ਰਕਤ ਬਸਤ੍ਰ ਧ੍ਰਿਤਵਾਨ ਧਨੁਰਧਰ।","roman":"Arun netr aru rakat basatr dhritvaan dhanurdhar |","meaning_en":"","page":892},{"gurmukhi":"ਬਿਕਟ ਬਾਕ੍ਯ ਬਡ ਡ੍ਯਾਛ ਬਡੋ ਅਭਿਮਾਨ ਧਰੇ ਮਨ।","roman":"Bikat baaky bad dyaachh bado abhimaan dhare man |","meaning_en":"","page":892},{"gurmukhi":"ਅਮਿਤ ਰੂਪ ਅਮਿਤੋਜ ਅਭੈ ਆਲੋਕ ਅਜੈ ਰਨ।","roman":"Amit roop amitoj abhai aalok ajai ran |","meaning_en":"","page":892},{"gurmukhi":"ਅਸ ਸੁਭਟ ਛੁਧਾ ਤ੍ਰਿਸਨਾ ਸਬਲ ਜਿਦਿਨ ਰੰਗ ਰਣ ਰਚਿ ਹੈ।","roman":"As subhat chhudhaa trisnaa sabal jidin rang ran rachi hai |","meaning_en":"","page":892},{"gurmukhi":"ਬਿਨੁ ਇਕ ਨ੍ਰਿਪਤਿ ਨਿਗ੍ਰਹ ਬਿਨਾ ਅਉਰ ਜੀਅ ਨ ਲੈ ਬਚਿ ਹੈ। ੧੮੯।","roman":"Binu ik nripti nigrah binaa aur jeea na lai bachi hai | 189 |","meaning_en":"","page":892}]},{"type":"verse","number":[190],"number_text":"੧੯੦।","page":892,"lines":[{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਸੁ ਛਬਿ ਸਾਵਜ ਤਾੜਤਾ ਕ੍ਰਿਤ।","roman":"Pavan beg rath chalat su chhabi saavaj taartaa krit |","meaning_en":"","page":892},{"gurmukhi":"ਗਿਰਤ ਧਰਨ ਸੁੰਦਰੀ ਨੈਕ ਜਿਹ ਦਿਸਿ ਫਿਰਿ ਝਾਕਤ।","roman":"Girat dharan sundree naik jih disi phiri jhaakat |","meaning_en":"","page":892},{"gurmukhi":"ਮਦਨ ਮੋਹ ਰਹਤ ਮਨੁਛ ਦੇਖਿ ਛਬਿ ਲਾਜਤ।","roman":"Madan moh rahat manuchh dekhi chhabi laajat |","meaning_en":"","page":892},{"gurmukhi":"ਉਪਜਤ ਹੀਯ ਹੁਲਾਸ ਨਿਰਖਿ ਦੁਤਿ ਕਹ ਦੁਖ ਭਾਜਤ।","roman":"Upjat heey hulaas nirkhi duti kah dukh bhaajat |","meaning_en":"","page":892},{"gurmukhi":"ਇਮਿ ਕਪਟ ਦੇਵ ਅਨਜੇਵ ਨ੍ਰਿਪੁ ਜਿਦਿਨ ਝਟਕ ਦੈ ਧਾਇ ਹੈ।","roman":"Imi kapat dev anjev nripu jidin jhatak dai dhaai hai |","meaning_en":"","page":892},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨੇਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਕਵਨ ਸਮੁਹਾਇ ਹੈ। ੧੯੦।","roman":"Binu ek saanti suneho nripti su aur kavan samuhaai hai | 190 |","meaning_en":"","page":892}]},{"type":"verse","number":[191],"number_text":"੧੯੧।","page":892,"lines":[{"gurmukhi":"ਚਖਨ ਚਾਰੁ ਚੰਚਲ ਪ੍ਰਭਾਵ ਖੰਜਨ ਲਖਿ ਲਾਜਤ।","roman":"Chakhan chaaru chanchal prabhaav khanjan lakhi laajat |","meaning_en":"","page":892},{"gurmukhi":"ਗਾਵਤ ਰਾਗ ਬਸੰਤ ਬੇਣ ਬੀਨਾ ਧੁਨਿ ਬਾਜਤ।","roman":"Gaavat raag basant ben beenaa dhuni baajat |","meaning_en":"","page":892},{"gurmukhi":"ਧਧਕਤ ਧ੍ਰਿਕਟ ਮ੍ਰਿਦੰਗ ਝਾਂਝ ਝਾਲਰ ਸੁਭ ਸੋਹਤ।","roman":"Dhadhkat dhrikat mridang jhaanjh jhaalar subh sohat |","meaning_en":"","page":892},{"gurmukhi":"ਖਗ ਮ੍ਰਿਗ ਜਛ ਭੁਜੰਗ ਅਸਰ ਸੁਰ ਨਰ ਮਨ ਮੋਹਤ।","roman":"Khag mrig jachh bhujang asar sur nar man mohat |","meaning_en":"","page":892},{"gurmukhi":"ਅਸ ਲੋਭ ਨਾਮ ਜੋਧਾ ਬਡੋ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟਿ ਹੈ।","roman":"As lobh naam jodhaa bado jidin judh kah juti hai |","meaning_en":"","page":892},{"gurmukhi":"ਜਸ ਪਵਨ ਬੇਗ ਤੇ ਮੇਘ ਗਣ ਸੁ ਅਸ ਤਵ ਸਬ ਦਲ ਫੁਟਿ ਹੈ। ੧੯੧।","roman":"Jas pavan beg te megh gan su as tav sab dal phuti hai | 191 |","meaning_en":"","page":892}]},{"type":"verse","number":[192],"number_text":"੧੯੨।","page":893,"lines":[{"gurmukhi":"ਧੁਜ ਪ੍ਰਮਾਣ ਬੀਜੁਰੀ ਭੁਜਾ ਭਾਰੀ ਜਿਹ ਰਾਜਤ।","roman":"Dhuj pramaan beejuree bhujaa bhaaree jih raajat |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਚੰਚਲ ਰਥ ਚਲਤ ਨਿਰਖ ਸੁਰ ਨਰ ਮੁਨਿ ਭਾਜਤ।","roman":"Ati chanchal rath chalat nirakh sur nar muni bhaajat |","meaning_en":"","page":893},{"gurmukhi":"ਅਧਿਕ ਰੂਪ ਅਮਿਤੋਜ ਅਮਿਟ ਜੋਧਾ ਰਣ ਦੁਹ ਕਰ।","roman":"Adhik roop amitoj amit jodhaa ran duh kar |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਬਲਵੰਤ ਲਗਤ ਸਤ੍ਰਨ ਕਹ ਰਿਪੁ ਹਰ।","roman":"Ati prataap balvant lagat satran kah ripu har |","meaning_en":"","page":893},{"gurmukhi":"ਅਸ ਮੋਹ ਨਾਮ ਜੋਧਾ ਜਸ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟਿ ਹੈ।","roman":"As moh naam jodhaa jas jidin judh kah juti hai |","meaning_en":"","page":893},{"gurmukhi":"ਬਿਨ ਇਕ ਬਿਚਾਰ ਅਬਿਚਾਰ ਨ੍ਰਿਪ ਅਉਰ ਸਕਲ ਦਲ ਫੁਟਿ ਹੈ। ੧੯੨।","roman":"Bin ik bichaar abichaar nrip aur sakal dal phuti hai | 192 |","meaning_en":"","page":893}]},{"type":"verse","number":[193],"number_text":"੧੯੩।","page":893,"lines":[{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਗਵਨ ਲਖਿ ਮੋਹਿਤ ਨਾਗਰ।","roman":"Pavan beg rath chalat gavan lakhi mohit naagar |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਅਮਿਤੋਜ ਅਜੈ ਪ੍ਰਤਮਾਨ ਪ੍ਰਭਾਧਰ।","roman":"Ati prataap amitoj ajai pratmaan prabhaadhar |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਅਧਿਸਟ ਸਕਲ ਸੈਨਾ ਕਹੁ ਜਾਨਹੁ।","roman":"Ati balisat adhisat sakal sainaa kahu jaanhu |","meaning_en":"","page":893},{"gurmukhi":"ਕ੍ਰੋਧ ਨਾਮ ਬਢਿਯਾਛ ਬਡੋ ਜੋਧਾ ਜੀਅ ਮਾਨਹੁ।","roman":"Krodh naam badhiyaachh bado jodhaa jeea maanhu |","meaning_en":"","page":893},{"gurmukhi":"ਧਰਿ ਅੰਗਿ ਕਵਚ ਧਰ ਪਨਚ ਕਰਿ ਜਿਦਿਨ ਤੁਰੰਗ ਮਟਕ ਹੈ।","roman":"Dhari angi kavach dhar panach kari jidin turang matak hai |","meaning_en":"","page":893},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨ ਸਤਿ ਨ੍ਰਿਪ ਸੁ ਅਉਰ ਨ ਕੋਊ ਹਟਕਿ ਹੈ। ੧੯੩।","roman":"Binu ek saanti sun sati nrip su aur na ko'oo hatki hai | 193 |","meaning_en":"","page":893}]},{"type":"verse","number":[194],"number_text":"੧੯੪।","page":893,"lines":[{"gurmukhi":"ਗਲਿਤ ਦੁਰਦ ਮਦਿ ਚੜ੍ਯੋ ਕਢਿ ਕਰਵਾਰ ਭਯੰਕਰ।","roman":"Galit durad madi charyo kadhi karvaar bhayankar |","meaning_en":"","page":893},{"gurmukhi":"ਸ੍ਯਾਮ ਬਰਣ ਆਭਰਣ ਖਚਿਤ ਸਬ ਨੀਲ ਮਣਿਣ ਬਰ।","roman":"Syaam baran aabhran khachit sab neel manin bar |","meaning_en":"","page":893},{"gurmukhi":"ਸ੍ਵਰਨ ਕਿੰਕਣੀ ਜਾਲ ਬਧੇ ਬਾਨੈਤ ਗਜੋਤਮ।","roman":"Svaran kinknee jaal badhe baanait gajotam |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਪ੍ਰਭਾਵ ਜੁਤਿ ਬੀਰ ਸਿਧ ਸਾਵੰਤ ਨਰੋਤਮ।","roman":"Ati prabhaav juti beer sidh saavant narotam |","meaning_en":"","page":893},{"gurmukhi":"ਇਹ ਛਬਿ ਹੰਕਾਰ ਨਾਮਾ ਸੁਭਟ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਮਾਨੀਐ।","roman":"Ih chhabi hankaar naamaa subhat ati balisat tih maaneeai |","meaning_en":"","page":893},{"gurmukhi":"ਜਿਹ ਜਗਤ ਜੀਵ ਜੀਤੇ ਸਬੈ ਆਪ ਅਜੀਤ ਤਿਹ ਜਾਨੀਐ। ੧੯੪।","roman":"Jih jagat jeev jeete sabai aap ajeet tih jaaneeai | 194 |","meaning_en":"","page":893}]},{"type":"verse","number":[195],"number_text":"੧੯੫।","page":893,"lines":[{"gurmukhi":"ਸੇਤ ਹਸਤ ਆਰੂੜ ਢੁਰਤ ਚਹੂੰ ਓਰਿ ਚਵਰ ਬਰ।","roman":"Set hasat aaroor dhurat chahoon ori chavar bar |","meaning_en":"","page":893},{"gurmukhi":"ਸ੍ਵਰਣ ਕਿੰਕਣੀ ਬਧੇ ਨਿਰਖਿ ਮੋਹਤ ਨਾਰੀ ਨਰ।","roman":"Svaran kinknee badhe nirkhi mohat naaree nar |","meaning_en":"","page":893},{"gurmukhi":"ਸੁਭ੍ਰ ਸੈਹਥੀ ਪਾਣਿ ਪ੍ਰਭਾ ਕਰ ਮੈ ਅਸ ਧਾਵਤ।","roman":"Subhr saihthee paani prabhaa kar mai as dhaavat |","meaning_en":"","page":893},{"gurmukhi":"ਨਿਰਖਿ ਦਿਪਤਿ ਦਾਮਨੀ ਪ੍ਰਭਾ ਹੀਯਰੇ ਪਛੁਤਾਵਤ।","roman":"Nirkhi dipti daamnee prabhaa heeyre pachhutaavat |","meaning_en":"","page":893},{"gurmukhi":"ਅਸ ਦ੍ਰੋਹ ਨਾਮ ਜੋਧਾ ਬਡੋ ਅਤਿ ਪ੍ਰਭਾਵ ਤਿਹ ਜਾਨੀਐ।","roman":"As droh naam jodhaa bado ati prabhaav tih jaaneeai |","meaning_en":"","page":893},{"gurmukhi":"ਜਲ ਥਲ ਬਿਦੇਸ ਦੇਸਨ ਨ੍ਰਿਪਤਿ ਆਨ ਜਵਨ ਕੀ ਮਾਨੀਐ। ੧੯੫।","roman":"Jal thal bides desan nripti aan javan kee maaneeai | 195 |","meaning_en":"","page":893}]},{"type":"verse","number":[196],"number_text":"੧੯੬।","page":893,"lines":[{"gurmukhi":"ਤਬਲ ਬਾਜ ਘੁੰਘਰਾਰ ਸੀਸ ਕਲਗੀ ਜਿਹਾ ਸੋਹਤ।","roman":"Tabal baaj ghunghraar sees kalgee jihaa sohat |","meaning_en":"","page":893},{"gurmukhi":"ਦ੍ਵੈ ਕ੍ਰਿਪਾਣ ਗਜਗਾਹ ਨਿਰਖਿ ਨਾਰੀ ਨਰ ਮੋਹਤ।","roman":"Dvai kripaan gajgaah nirkhi naaree nar mohat |","meaning_en":"","page":893,"flags":[{"code":"0x50","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਅਮਿਤ ਰੂਪ ਅਮਿਤੋਜ ਬਿਕਟ ਬਾਨੈਤ ਅਮਿਟ ਭਟ।","roman":"Amit roop amitoj bikat baanait amit bhat |","meaning_en":"","page":893},{"gurmukhi":"ਅਤਿ ਸੁਬਾਹ ਅਤਿ ਸੂਰ ਅਜੈ ਅਨਭਿਦ ਸੁ ਅਨਕਟ।","roman":"Ati subaah ati soor ajai anbhid su ankat |","meaning_en":"","page":893},{"gurmukhi":"ਇਹ ਭਾਤਿ ਭਰਮ ਅਨਭਿਦ ਭਟ ਜਿਦਿਨ ਕ੍ਰੁਧ ਜੀਯ ਧਾਰ ਹੈ।","roman":"Ih bhaati bharam anbhid bhat jidin krudh jeey dhaar hai |","meaning_en":"","page":893},{"gurmukhi":"ਬਿਨ ਇਕ ਬਿਚਾਰ ਅਬਚਿਾਰ ਨ੍ਰਿਪ ਸਸੁ ਅਉਰ ਨ ਆਨਿ ਉਬਾਰਿ ਹੈ। ੧੯੬।","roman":"Bin ik bichaar abchaar nrip sasu aur na aani ubaari hai | 196 |","meaning_en":"","page":893}]},{"type":"verse","number":[197],"number_text":"੧੯੭।","page":894,"lines":[{"gurmukhi":"ਲਾਲ ਮਾਲ ਸੁਭ ਬਧੈ ਨਗਨ ਸਰਪੇਚਿ ਖਚਿਤ ਸਿਰ।","roman":"Laal maal subh badhai nagan sarpechi khachit sir |","meaning_en":"","page":894},{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਅਨਿਭੇਦ ਅਜੈ ਸਾਵੰਤ ਭਟਾਂਬਰ।","roman":"Ati balisat anibhed ajai saavant bhataanbar |","meaning_en":"","page":894},{"gurmukhi":"ਕਟਿ ਕ੍ਰਿਪਾਣ ਸੈਹਥੀ ਤਜਤ ਧਾਰਾ ਬਾਣਨ ਕਰ।","roman":"Kati kripaan saihthee tajat dhaaraa baanan kar |","meaning_en":"","page":894},{"gurmukhi":"ਦੇਖਤ ਹਸਤ ਪ੍ਰਭਾਵ ਲਜਤ ਤੜਿਤਾ ਧਾਰਾਧਰ।","roman":"Dekhat hasat prabhaav lajat taritaa dhaaraadhar |","meaning_en":"","page":894},{"gurmukhi":"ਅਸ ਬ੍ਰਹਮ ਦੋਖ ਅਨਮੋਖ ਭਟ ਅਕਟ ਅਜੈ ਤਿਹ ਜਾਨੀਐ।","roman":"As braham dokh anmokh bhat akat ajai tih jaaneeai |","meaning_en":"","page":894},{"gurmukhi":"ਅਰਿ ਦਵਨ ਅਜੈ ਆਨੰਦ ਕਰ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਕੋ ਮਾਨੀਐ। ੧੯੭।","roman":"Ari davan ajai aanand kar nrip abibek ko maaneeai | 197 |","meaning_en":"","page":894}]},{"type":"verse","number":[198],"number_text":"੧੯੮।","page":894,"lines":[{"gurmukhi":"ਅਸਿਤ ਬਸਤ੍ਰ ਅਰੁ ਅਸਿਤ ਗਾਤ ਅਮਿਤੋਜ ਰਣਾਚਲ।","roman":"Asit basatr aru asit gaat amitoj ranaachal |","meaning_en":"","page":894},{"gurmukhi":"ਅਤਿ ਪ੍ਰਚੰਡ ਅਤਿ ਬੀਰ ਬੀਰ ਜੀਤੇ ਜਿਨ ਜਲ ਥਲ।","roman":"Ati prachand ati beer beer jeete jin jal thal |","meaning_en":"","page":894},{"gurmukhi":"ਅਕਟ ਅਜੈ ਅਨਭੇਦ ਅਮਿਟ ਅਨਰਥਿ ਨਾਮ ਤਿਹੈ।","roman":"Akat ajai anbhed amit anarthi naam tihai |","meaning_en":"","page":894},{"gurmukhi":"ਅਤਿ ਪ੍ਰਮਾਥ ਅਰਿ ਮਥਨ ਸਤ੍ਰੁ ਸੋਖਨ ਹੈ ਬ੍ਰਿਦ ਜਿਹ।","roman":"Ati pramaath ari mathan satru sokhan hai brid jih |","meaning_en":"","page":894},{"gurmukhi":"ਦੁਰ ਧਰਖ ਸੂਰ ਅਨਭੇਦ ਭਟ ਅਤਿ ਪ੍ਰਤਾਪ ਤਿਹ ਜਾਨੀਐ।","roman":"Dur dharakh soor anbhed bhat ati prataap tih jaaneeai |","meaning_en":"","page":894},{"gurmukhi":"ਅਨਜੈ ਅਨੰਦ ਦਾਤਾ ਅਪਨ ਅਤਿ ਸੁਬਾਹ ਤਿਹ ਮਾਨੀਐ। ੧੯੮।","roman":"Anjai anand daataa apan ati subaah tih maaneeai | 198 |","meaning_en":"","page":894}]},{"type":"verse","number":[199],"number_text":"੧੯੯।","page":894,"lines":[{"gurmukhi":"ਮੋਰ ਬਰਣ ਰਥ ਬਾਜ ਮੋਰ ਹੀ ਬਰਣ ਪਰਮ ਜਿਹ।","roman":"Mor baran rath baaj mor hee baran param jih |","meaning_en":"","page":894},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਦੁਰ ਧਰਖ ਸਤ੍ਰੁ ਲਖ ਕਰ ਕੰਪਤ ਤਿਹ।","roman":"Amit tej dur dharakh satru lakh kar kanpat tih |","meaning_en":"","page":894},{"gurmukhi":"ਅਮਿਟ ਬੀਰ ਆਜਾਨ ਬਾਹੁ ਅਲੋਕ ਰੂਪ ਗਨ।","roman":"Amit beer aajaan baahu alok roop gan |","meaning_en":"","page":894},{"gurmukhi":"ਮਤਸ ਕੇਤੁ ਲਖਿ ਜਾਹਿ ਹ੍ਰਿਦੈ ਲਾਜਤ ਹੈ ਦੁਤਿ ਮਨਿ।","roman":"Matas ketu lakhi jaahi hridai laajat hai duti mani |","meaning_en":"","page":894},{"gurmukhi":"ਅਸ ਝੂਠ ਰੂਠਿ ਜਿਦਿਨ ਨ੍ਰਿਪਤਿ ਰਣਹਿ ਤੁਰੰਗ ਉਥਕਿ ਹੈ।","roman":"As jhooth roothi jidin nripti ranhi turang uthki hai |","meaning_en":"","page":894},{"gurmukhi":"ਬਿਨੁ ਇਕ ਸਤਿ ਸੁਣ ਸਤਿ ਨ੍ਰਿਪ ਸੁ ਅਉਰ ਨ ਆਨਿ ਹਟਕਿ ਹੈ। ੧੯੯।","roman":"Binu ik sati sun sati nrip su aur na aani hatki hai | 199 |","meaning_en":"","page":894}]},{"type":"verse","number":[200],"number_text":"੨੦੦।","page":894,"lines":[{"gurmukhi":"ਰਥ ਤੁਰੰਗ ਸਿਤ ਅਸਿਤ ਅਸਿਤ ਸਿਤ ਧੁਜਾ ਬਿਰਾਜਤ।","roman":"Rath turang sit asit asit sit dhujaa biraajat |","meaning_en":"","page":894},{"gurmukhi":"ਅਸਿਤ ਸੇਤਹਿ ਬਸਤ੍ਰ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮੁਨਿ ਲਾਜਤ।","roman":"Asit sethi basatr nirkhi sur nar muni laajat |","meaning_en":"","page":894},{"gurmukhi":"ਅਸਿਤ ਸੇਤ ਸਾਰਥੀ ਅਸਿਤ ਸੇਤ ਛਕਿਓ ਰਥਾਂਬਰ।","roman":"Asit set saarthee asit set chhakio rathaanbar |","meaning_en":"","page":894},{"gurmukhi":"ਸੁਵਰਣ ਕਿੰਕਨੀ ਕੇਸ ਜਨੁਕ ਦੂਸਰੇ ਦੇਵੇਸੁਰ।","roman":"Suvran kinknee kes januk doosre devesur |","meaning_en":"","page":894},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਮਿਥਿਆ ਸੁਭਟ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਕਹ ਕਹ੍ਯੋ।","roman":"Ih chhabi prabhaav mithiaa subhat ati balisat tih kah kahyo |","meaning_en":"","page":894},{"gurmukhi":"ਜਿਹ ਜਗਤ ਜੀਵ ਜੀਤੇ ਸਬੈ ਨਹਿ ਅਜੀਤ ਨਰ ਕੋ ਰਹ੍ਯੋ। ੨੦੦।","roman":"Jih jagat jeev jeete sabai nahi ajeet nar ko rahyo | 200 |","meaning_en":"","page":894}]},{"type":"verse","number":[201],"number_text":"੨੦੧।","page":894,"lines":[{"gurmukhi":"ਚਕ੍ਰ ਬਕ੍ਰ ਕਰ ਧਰੇ ਚਾਰੁ ਬਾਗਾ ਤਨਿ ਧਾਰੇ।","roman":"Chakr bakr kar dhare chaaru baagaa tani dhaare |","meaning_en":"","page":894},{"gurmukhi":"ਆਨਨ ਖਾਤ ਤੰਬੋਲ ਗੰਧਿ ਉਤਮ ਬਿਸਥਾਰੇ।","roman":"Aanan khaat tanbol gandhi utam bisthaare |","meaning_en":"","page":894},{"gurmukhi":"ਚਵਰੁ ਚਾਰੁ ਚਹੂੰ ਓਰਿ ਢੁਰਤ ਸੁੰਦਰ ਛਬਿ ਪਾਵਤ।","roman":"Chavru chaaru chahoon ori dhurat sundar chhabi paavat |","meaning_en":"","page":894},{"gurmukhi":"ਨਿਰਖਤ ਨੈਨ ਬਸੰਤ ਪ੍ਰਭਾ ਤਾਕਹ ਸਿਰ ਨ੍ਯਾਵਤ।","roman":"Nirkhat nain basant prabhaa taakah sir nyaavat |","meaning_en":"","page":894},{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੁਬਾਹੁ ਚਿੰਤਾ ਸੁਭਟ ਅਤਿ ਦੁਰ ਧਰਖ ਬਖਾਨੀਐ।","roman":"Ih bidhi subaahu chintaa subhat ati dur dharakh bakhaaneeai |","meaning_en":"","page":894},{"gurmukhi":"ਅਨਭੰਗ ਗਾਤ ਅਨਭੈ ਸੁਭਟ ਅਤਿ ਪ੍ਰਚੰਡ ਤਿਹ ਮਾਨੀਐ। ੨੦੧।","roman":"Anbhang gaat anbhai subhat ati prachand tih maaneeai | 201 |","meaning_en":"","page":894}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":895},{"type":"verse","number":[202],"number_text":"੨੦੨।","page":895,"lines":[{"gurmukhi":"ਲਾਲ ਹੀਰਨ ਕੇ ਧਰੇ ਜਿਹ ਸੀਸ ਪੈ ਬਹੁ ਹਾਰ।","roman":"Laal heeran ke dhare jih sees pai bahu haar |","meaning_en":"","page":895},{"gurmukhi":"ਸ੍ਵਰਣੀ ਕਿੰਕਣਿ ਸੌ ਛਕ ਗਜ ਰਾਜ ਪਬਾਕਾਰ।","roman":"Svarnee kinkni sau chhak gaj raaj pabaakaar |","meaning_en":"","page":895},{"gurmukhi":"ਦੁਰਦ ਰੂੜ ਦਰਿਦ੍ਰ ਨਾਮ ਸੁ ਬੀਰ ਹੈ ਸੁਨਿ ਭੂਪ।","roman":"Durad roor daridr naam su beer hai suni bhoop |","meaning_en":"","page":895},{"gurmukhi":"ਕਉਨ ਤਾ ਤੇ ਜੀਤ ਹੈ ਰਣ ਆਨਿ ਰਾਜ ਸਰੂਪ। ੨੦੨।","roman":"Kaun taa te jeet hai ran aani raaj saroop | 202 |","meaning_en":"","page":895}]},{"type":"verse","number":[203],"number_text":"੨੦੩।","page":895,"lines":[{"gurmukhi":"ਜਰਕਸੀ ਕੇ ਬਸਤ੍ਰ ਹੈ ਅਰੁ ਪਰਮ ਬਾਜਾਰੂੜ।","roman":"Jaraksee ke basatr hai aru param baajaaroor |","meaning_en":"","page":895},{"gurmukhi":"ਪਰਮ ਰੂਪ ਪਵਿਤਰ ਗਾਤ ਅਛਿਜ ਰੂਪ ਅਗੂੜ।","roman":"Param roop pavitar gaat achhij roop agoor |","meaning_en":"","page":895},{"gurmukhi":"ਛਤ੍ਰ ਧਰਮ ਧਰੇ ਮਹਾ ਭਟ ਬੰਸ ਕੀ ਜਿਹ ਲਾਜ।","roman":"Chhatr dharam dhare mahaa bhat bans kee jih laaj |","meaning_en":"","page":895},{"gurmukhi":"ਸੰਕ ਨਾਮਾ ਸੂਰ ਸੋ ਸਬ ਸੂਰ ਹੈ ਸਿਰਤਾਜ। ੨੦੩।","roman":"Sank naamaa soor so sab soor hai sirtaaj | 203 |","meaning_en":"","page":895}]},{"type":"verse","number":[204],"number_text":"੨੦੪।","page":895,"lines":[{"gurmukhi":"ਪਿੰਗ ਬਾਜ ਨਹੇ ਰਥੈ ਸਹਿ ਅਡਿਗ ਬੀਰ ਅਖੰਡ।","roman":"Ping baaj nahe rathai sahi adig beer akhand |","meaning_en":"","page":895},{"gurmukhi":"ਅੰਤ ਰੂਪ ਧਰੇ ਮਨੋ ਅਛਿਜ ਗਾਤ ਪ੍ਰਚੰਡ।","roman":"Ant roop dhare mano achhij gaat prachand |","meaning_en":"","page":895},{"gurmukhi":"ਨਾਮ ਸੂਰ ਅਸੋਭ ਤਾ ਕਹ ਜਾਨਹੀ ਸਭ ਲੋਕ।","roman":"Naam soor asobh taa kah jaanhee sabh lok |","meaning_en":"","page":895},{"gurmukhi":"ਕਉਨ ਰਾਵ ਬਿਬੇਕ ਹੈ ਜੁ ਨ ਮਾਨਿ ਹੈ ਇਹ ਸੋਕ। ੨੦੪।","roman":"Kaun raav bibek hai ju na maani hai ih sok | 204 |","meaning_en":"","page":895}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"","page":895},{"type":"verse","number":[205],"number_text":"੨੦੫।","page":895,"lines":[{"gurmukhi":"ਸਜੇ ਸ੍ਯਾਮ ਬਾਜੀ ਰਥੰ ਜਾਸੁ ਜਾਨੋ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਅਜੈ ਤਾਸੁ ਮਾਨੋ।","roman":"Saje syaam baajee rathan jaasu jaano | mahaa jang jodhaa ajai taasu maano |","meaning_en":"","page":895},{"gurmukhi":"ਅਸੰਤੁਸਟ ਨਾਮ ਮਹਾਬੀਰ ਸੋਹੈ। ਤਿਹੂੰ ਲੋਕ ਜਾ ਕੋ ਬਡੋ ਤ੍ਰਾਸ ਮੋਹੈ। ੨੦੫।","roman":"Asantusat naam mahaabeer sohai | tihoon lok jaa ko bado traas mohai | 205 |","meaning_en":"","page":895}]},{"type":"verse","number":[206],"number_text":"੨੦੬।","page":895,"lines":[{"gurmukhi":"ਚੜ੍ਯੋ ਤਤ ਤਾਜੀ ਸਿਰਾਜੀਤ ਸੋਭੈ। ਸਿਰੰ ਜੈਤ ਪਤ੍ਰੰ ਲਖੇ ਚੰਦ੍ਰ ਛੋਭੈ।","roman":"Charyo tat taajee siraajeet sobhai | siran jait patran lakhe chandr chhobhai |","meaning_en":"","page":895},{"gurmukhi":"ਅਨਾਸ ਊਚ ਨਾਮਾ ਮਹਾ ਸੂਰ ਸੋਹੈ। ਬਡੋ ਛਤ੍ਰਧਾਰੀ ਧਰੈ ਛਤ੍ਰ ਜੋ ਹੈ। ੨੦੬।","roman":"Anaas ooch naamaa mahaa soor sohai | bado chhatradhaaree dharai chhatr jo hai | 206 |","meaning_en":"","page":895}]},{"type":"verse","number":[207],"number_text":"੨੦੭।","page":895,"lines":[{"gurmukhi":"ਰਥੰ ਸੇਤ ਬਾਜੀ ਸਿਰਾਜੀਤ ਸੋਹੈ। ਲਖੇ ਇੰਦ੍ਰ ਬਾਜੀ ਤਰੈ ਦ੍ਰਿਸਟ ਕੋ ਹੈ।","roman":"Rathan set baajee siraajeet sohai | lakhe indr baajee tarai drisat ko hai |","meaning_en":"","page":895},{"gurmukhi":"ਹਠੀ ਬਾਬਰੀ ਕੋ ਹਿੰਸਾ ਨਾਮ ਜਾਨੋ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਅਜੈ ਲੋਕ ਮਾਨੋ। ੨੦੭।","roman":"Hathee baabree ko hinsaa naam jaano | mahaa jang jodhaa ajai lok maano | 207 |","meaning_en":"","page":895}]},{"type":"verse","number":[208],"number_text":"੨੦੮।","page":895,"lines":[{"gurmukhi":"ਸੁਭੰ ਸੰਦਲੀ ਬਾਜ ਰਾਜੀ ਸਿਰਾਜੀ। ਲਖੇ ਰੂਪ ਤਾ ਕੋ ਲਜੈ ਇੰਦ੍ਰ ਬਾਜੀ।","roman":"Subhan sandlee baaj raajee siraajee | lakhe roop taa ko lajai indr baajee |","meaning_en":"","page":895},{"gurmukhi":"ਕੁਮੰਤੰ ਮਹਾ ਜੰਗ ਜੋਧਾ ਜੁਝਾਰੰ। ਜਲੰ ਵਾ ਥਲੰ ਜੇਣ ਜਿਤੇ ਬਰਿਆਰੰ। ੨੦੮।","roman":"Kumantan mahaa jang jodhaa jujhaaran | jalan vaa thalan jen jite bariaaran | 208 |","meaning_en":"","page":895}]},{"type":"verse","number":[209],"number_text":"੨੦੯।","page":895,"lines":[{"gurmukhi":"ਚੜ੍ਯੋ ਬਾਜ ਤਾਜੀ ਕੋਪਤੰ ਸਰੂਪੰ। ਧਰੇ ਚਰਮ ਬਰਮੰ ਬਿਸਾਲੰ ਅਨੂਪੰ।","roman":"Charyo baaj taajee koptan saroopan | dhare charam barman bisaalan anoopan |","meaning_en":"","page":895},{"gurmukhi":"ਧੁਜਾ ਬਧ ਸਿਧੰ ਅਲਜਾ ਜੁਝਾਰੰ। ਬਡੋ ਜੰਗ ਜੋਧਾ ਸੁ ਕ੍ਰੁਧੀ ਬਰਾਰੰ। ੨੦੯।","roman":"Dhujaa badh sidhan aljaa jujhaaran | bado jang jodhaa su krudhee baraaran | 209 |","meaning_en":"","page":895}]},{"type":"verse","number":[210],"number_text":"੨੧੦।","page":896,"lines":[{"gurmukhi":"ਧਰੇ ਛੀਨ ਬਸਤ੍ਰੰ ਮਲੀਨੰ ਦਰਿਦ੍ਰੀ। ਧੁਜਾ ਫਾਟ ਬਸਤ੍ਰੰ ਸੁ ਧਾਰੇ ਉਪਦ੍ਰੀ।","roman":"Dhare chheen bastran maleenan daridree | dhujaa phaat bastran su dhaare updree |","meaning_en":"","page":896},{"gurmukhi":"ਮਹਾ ਸੂਰ ਚੋਰੀ ਕਰੋਰੀ ਸਮਾਨੰ। ਲਸੈ ਤੇਜ ਐਸੋ ਲਜੈ ਦੇਖਿ ਸ੍ਵਾਨੰ। ੨੧੦।","roman":"Mahaa soor choree karoree samaanan | lasai tej aiso lajai dekhi svaanan | 210 |","meaning_en":"","page":896}]},{"type":"verse","number":[211],"number_text":"੨੧੧।","page":896,"lines":[{"gurmukhi":"ਫਟੇ ਬਸਤ੍ਰ ਸਰਬੰ ਸਬੈ ਅੰਗ ਧਾਰੇ। ਬਧੇ ਸੀਸ ਜਾਰੀ ਬੁਰੀ ਅਰਧ ਜਾਰੇ।","roman":"Phate basatr sarban sabai ang dhaare | badhe sees jaaree buree aradh jaare |","meaning_en":"","page":896},{"gurmukhi":"ਚੜ੍ਯੋ ਭੀਮ ਭੈਸੰ ਮਹਾ ਭੀਮ ਰੂਪੰ। ਬਿਭੈਚਾਰ ਜੋਧਾ ਕਹੋ ਤਾਸ ਭੂਪੰ। ੨੧੧।","roman":"Charyo bheem bhaisan mahaa bheem roopan | bibhaichaar jodhaa kaho taas bhoopan | 211 |","meaning_en":"","page":896}]},{"type":"verse","number":[212],"number_text":"੨੧੨।","page":896,"lines":[{"gurmukhi":"ਸਭੈ ਸਿਆਮ ਬਰਣੰ ਸਿਰੰ ਸੇਤ ਏਕੰ। ਨਹੇ ਗਰਧਪੰ ਸ੍ਯੰਦਨੇਕੰ ਅਨੇਕੰ।","roman":"Sabhai siaam barnan siran set ekan | nahe garadhpan syandnekan anekan |","meaning_en":"","page":896},{"gurmukhi":"ਧੁਜਾ ਸ੍ਯਾਮ ਬਰਣੰ ਭੁਜੰ ਭੀਮ ਰੂਪੰ। ਸਰੰ ਸ੍ਰੋਣਿਤੰ ਏਕ ਅਛੇਕ ਕੂਪੰ। ੨੧੨।","roman":"Dhujaa syaam barnan bhujan bheem roopan | saran sronitan ek achhek koopan | 212 |","meaning_en":"","page":896}]},{"type":"verse","number":[213],"number_text":"੨੧੩।","page":896,"lines":[{"gurmukhi":"ਮਹਾ ਜੋਧ ਦਾਰਿਦ੍ਰ ਨਾਮਾ ਜੁਝਾਰੰ। ਧਰੇ ਚਰਮ ਬਰਮੰ ਸੁ ਪਾਣੰ ਕੁਠਾਰੰ।","roman":"Mahaa jodh daaridr naamaa jujhaaran | dhare charam barman su paanan kuthaaran |","meaning_en":"","page":896},{"gurmukhi":"ਬਡੋ ਚਿਤ੍ਰ ਜੋਧੀ ਕਰੋਧੀ ਕਰਾਲੰ। ਤਜੈ ਨਾਸਕਾ ਨੈਨ ਧੂਮ੍ਰੰ ਬਰਾਲੰ। ੨੧੩।","roman":"Bado chitr jodhee karodhee karaalan | tajai naaskaa nain dhoomran baraalan | 213 |","meaning_en":"","page":896,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":896},{"type":"verse","number":[214],"number_text":"੨੧੪।","page":896,"lines":[{"gurmukhi":"ਸ੍ਵਾਮਿਘਾਤ ਕ੍ਰਿਤਘਨਤਾ ਦੋਊ ਬੀਰ ਹੈ ਦੁਰ ਧਰਖ।","roman":"Svaamighaat kritghantaa do'oo beer hai dur dharakh |","meaning_en":"","page":896},{"gurmukhi":"ਸਤ੍ਰੁ ਸੂਰਨ ਕੇ ਸੰਘਾਰਕ ਸੈਨ ਕੇ ਭਰਤਰਖ।","roman":"Satru sooran ke sanghaarak sain ke bharatrakh |","meaning_en":"","page":896},{"gurmukhi":"ਕਉਨ ਦੋ ਥਨ ਸੋ ਜਨਾ ਜੁ ਨ ਮਾਨਿ ਹੈ ਤਿਹੰ ਤ੍ਰਾਸ।","roman":"Kaun do than so janaa ju na maani hai tihan traas |","meaning_en":"","page":896},{"gurmukhi":"ਰੂਪ ਅਨੂਪ ਬਿਲੋਕਿ ਕੈ ਭਟ ਭਜੈ ਹੋਇ ਉਦਾਸ। ੨੧੪।","roman":"Roop anoop biloki kai bhat bhajai hoi udaas | 214 |","meaning_en":"","page":896}]},{"type":"verse","number":[215],"number_text":"੨੧੫।","page":896,"lines":[{"gurmukhi":"ਮਿਤ੍ਰ ਦੋਖ ਅਰੁ ਰਾਜ ਦੋਖ ਸੁ ਏਕ ਹੀ ਹੈ ਭ੍ਰਾਤ।","roman":"Mitr dokh aru raaj dokh su ek hee hai bhraat |","meaning_en":"","page":896},{"gurmukhi":"ਏਕ ਬੰਸ ਦੁਹੂੰਨ ਕੋ ਅਰ ਏਕ ਹੀ ਤਿਹ ਮਾਤ।","roman":"Ek bans duhoonn ko ar ek hee tih maat |","meaning_en":"","page":896},{"gurmukhi":"ਛਤ੍ਰਿ ਧਰਮ ਧਰੇ ਹਠੀ ਰਣ ਧਾਇ ਹੈ ਜਿਹ ਓਰ।","roman":"Chhatri dharam dhare hathee ran dhaai hai jih or |","meaning_en":"","page":896},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰ ਭਟਾਂਬਰ ਲੇਤ ਹੈ ਝਕਝੋਰ। ੨੧੫।","roman":"Kaun dheer dhar bhataanbar let hai jhakjhor | 215 |","meaning_en":"","page":896}]},{"type":"verse","number":[216],"number_text":"੨੧੬।","page":896,"lines":[{"gurmukhi":"ਈਰਖਾ ਅਰੁ ਉਚਾਟ ਏ ਦੋਊ ਜੰਗ ਜੋਧਾ ਸੂਰ।","roman":"Eerkhaa aru uchaat e do'oo jang jodhaa soor |","meaning_en":"","page":896},{"gurmukhi":"ਭਾਜਿ ਹੈ ਅਵਿਲੋਕ ਕੈ ਅਰੁ ਰੀਝਿ ਹੈ ਲਖਿ ਹੂਰ।","roman":"Bhaaji hai avilok kai aru reejhi hai lakhi hoor |","meaning_en":"","page":896},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰੈ ਭਟਾਂਬਰ ਜੀਤਿ ਹੈ ਸਬ ਸਤ੍ਰੂ।","roman":"Kaun dheer dharai bhataanbar jeeti hai sab satroo |","meaning_en":"","page":896},{"gurmukhi":"ਦੰਤ ਲੈ ਤ੍ਰਿਣ ਭਾਜਿ ਹੈ ਭਟ ਕੋ ਨ ਗਹਿ ਹੈ ਅਤ੍ਰ। ੨੧੬।","roman":"Dant lai trin bhaaji hai bhat ko na gahi hai atr | 216 |","meaning_en":"","page":896}]},{"type":"verse","number":[217],"number_text":"੨੧੭।","page":896,"lines":[{"gurmukhi":"ਘਾਤ ਅਉਰ ਬਸੀਕਰਣ ਬਡ ਬੀਰ ਧੀਰ ਅਪਾਰ।","roman":"Ghaat aur baseekran bad beer dheer apaar |","meaning_en":"","page":896},{"gurmukhi":"ਕ੍ਰੂਰ ਕਰਮ ਕੁਠਾਰ ਪਾਣਿ ਕਰਾਲ ਦਾੜ ਬਰਿਆਰ।","roman":"Kroor karam kuthaar paani karaal daar bariaar |","meaning_en":"","page":896},{"gurmukhi":"ਬਿਜ ਤੇਜ ਅਛਿਜ ਗਾਤਿ ਅਭਿਜ ਰੂਪ ਦੁਰੰਤ।","roman":"Bij tej achhij gaati abhij roop durant |","meaning_en":"","page":896},{"gurmukhi":"ਕਉਨ ਕਉਨ ਨ ਜੀਤਿਏ ਜਿਨਿ ਜੀਵ ਜੰਤ ਮਹੰਤ। ੨੧੭।","roman":"Kaun kaun na jeetie jini jeev jant mahant | 217 |","meaning_en":"","page":896}]},{"type":"verse","number":[218],"number_text":"੨੧੮।","page":897,"lines":[{"gurmukhi":"ਆਪਦਾ ਅਰੁ ਝੂਠਤਾ ਅਰੁ ਬੀਰ ਬੰਸ ਕੁਠਾਰ।","roman":"Aapdaa aru jhoothtaa aru beer bans kuthaar |","meaning_en":"","page":897},{"gurmukhi":"ਪਰਮ ਰੂਪ ਦੁਰ ਧਰਖ ਗਾਤ ਅਮਰਖ ਤੇਜ ਅਪਾਰ।","roman":"Param roop dur dharakh gaat amrakh tej apaar |","meaning_en":"","page":897},{"gurmukhi":"ਅੰਗ ਅੰਗਨਿ ਨੰਗ ਬਸਤ੍ਰ ਨ ਅੰਗ ਬਲਕੁਲ ਪਾਤ।","roman":"Ang angni nang basatr na ang balkul paat |","meaning_en":"","page":897},{"gurmukhi":"ਦੁਸਟ ਰੂਪ ਦਰਿਦ੍ਰ ਧਾਮ ਸੁ ਬਾਣ ਸਾਧੇ ਸਾਤ। ੨੧੮।","roman":"Dusat roop daridr dhaam su baan saadhe saat | 218 |","meaning_en":"","page":897}]},{"type":"verse","number":[219],"number_text":"੨੧੯।","page":897,"lines":[{"gurmukhi":"ਬਿਯੋਗ ਅਉਰ ਅਪਰਾਧ ਨਾਮ ਸੁ ਧਾਰ ਹੈ ਜਬ ਕੋਪ।","roman":"Biyog aur apraadh naam su dhaar hai jab kop |","meaning_en":"","page":897},{"gurmukhi":"ਕਉਨ ਠਾਢ ਸਕੈ ਮਹਾ ਬਲਿ ਭਾਜਿ ਹੈ ਬਿਨੁ ਓਪ।","roman":"Kaun thaadh sakai mahaa bali bhaaji hai binu op |","meaning_en":"","page":897},{"gurmukhi":"ਸੂਲ ਸੈਥਨ ਪਾਨਿ ਬਾਨ ਸੰਭਾਰਿ ਹੈ ਤਵ ਸੂਰ।","roman":"Sool saithan paani baan sanbhaari hai tav soor |","meaning_en":"","page":897},{"gurmukhi":"ਭਾਜਿ ਹੈ ਤਜਿ ਲਾਜ ਕੋ ਬਿਸੰਭਾਰ ਹ੍ਵੈ ਸਬ ਕੂਰ। ੨੧੯।","roman":"Bhaaji hai taji laaj ko bisanbhaar hvai sab koor | 219 |","meaning_en":"","page":897}]},{"type":"verse","number":[220],"number_text":"੨੨੦।","page":897,"lines":[{"gurmukhi":"ਭਾਨੁ ਕੀ ਸਰ ਭੇਦ ਜਾ ਦਿਨ ਤਪਿ ਹੈ ਰਣ ਸੂਰ।","roman":"Bhaanu kee sar bhed jaa din tapi hai ran soor |","meaning_en":"","page":897},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰੈ ਮਹਾ ਭਟ ਭਾਜਿ ਹੈ ਸਭ ਕੂਰ।","roman":"Kaun dheer dharai mahaa bhat bhaaji hai sabh koor |","meaning_en":"","page":897},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰਨ ਛਾਡਿ ਕੈ ਅਰੁ ਬਾਜ ਰਾਜ ਬਿਸਾਰਿ।","roman":"Sasatr astran chhaadi kai aru baaj raaj bisaari |","meaning_en":"","page":897},{"gurmukhi":"ਕਾਟਿ ਕਾਟਿ ਸਨਾਹ ਤਵ ਭਟ ਭਾਜਿ ਹੈ ਬਿਸੰਭਾਰ। ੨੨੦।","roman":"Kaati kaati sanaah tav bhat bhaaji hai bisanbhaar | 220 |","meaning_en":"","page":897}]},{"type":"verse","number":[221],"number_text":"੨੨੧।","page":897,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਅਉ ਧੂਮ੍ਰ ਨੈਨ ਸੁ ਸਾਤ ਧੂਮ੍ਰ ਜੁਆਲ।","roman":"Dhoomr baran au dhoomr nain su saat dhoomr juaal |","meaning_en":"","page":897},{"gurmukhi":"ਛੀਨ ਬਸਤ੍ਰ ਧਰੇ ਸਬੈ ਤਨ ਕ੍ਰੂਰ ਬਰਣ ਕਰਾਲ।","roman":"Chheen basatr dhare sabai tan kroor baran karaal |","meaning_en":"","page":897,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਨਾਮ ਆਲਸ ਤਵਨ ਕੋ ਸੁਨਿ ਰਾਜ ਰਾਜ ਵਤਾਰ।","roman":"Naam aalas tavan ko suni raaj raaj vataar |","meaning_en":"","page":897},{"gurmukhi":"ਕਉਨ ਸੂਰ ਸੰਘਾਰਿ ਹੈ ਤਿਹ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਪ੍ਰਹਾਰ। ੨੨੧।","roman":"Kaun soor sanghaari hai tih sasatr asatr prahaar | 221 |","meaning_en":"","page":897}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"","page":897},{"type":"verse","number":[222],"number_text":"੨੨੨।","page":897,"lines":[{"gurmukhi":"ਚੜਿ ਹੈ ਗਹਿ ਕੋਪ ਕ੍ਰਿਪਾਣ ਰਣੰ। ਘਮਕੰਤ ਕਿ ਘੁੰਘਰ ਘੋਰ ਘਣੰ।","roman":"Chari hai gahi kop kripaan ranan | ghamkant ki ghunghar ghor ghanan |","meaning_en":"","page":897},{"gurmukhi":"ਤਿਹ ਨਾਮ ਸੁ ਖੇਦ ਅਭੇਦ ਭਟੰ। ਤਿਹ ਬੀਰ ਸੁਧੀਰ ਲਖੋ ਨਿਪਟੰ। ੨੨੨।","roman":"Tih naam su khed abhed bhatan | tih beer sudheer lakho niptan | 222 |","meaning_en":"","page":897}]},{"type":"verse","number":[223],"number_text":"੨੨੩।","page":897,"lines":[{"gurmukhi":"ਕਲ ਰੂਪ ਕਰਾਲ ਜ੍ਵਾਲ ਜਲੰ। ਅਸਿ ਉਜਲ ਪਾਨਿ ਪ੍ਰਭਾ ਨਿਮ੍ਰਲੰ।","roman":"Kal roop karaal jvaal jalan | asi ujal paani prabhaa nimralan |","meaning_en":"","page":897},{"gurmukhi":"ਅਤਿ ਉਜਲ ਦੰਦ ਅਨੰਦ ਮਨੰ। ਕੁਕ੍ਰਿਆ ਤਿਹ ਨਾਮ ਸੁ ਜੋਧ ਗਨੰ। ੨੨੩।","roman":"Ati ujal dand anand manan | kukriaa tih naam su jodh ganan | 223 |","meaning_en":"","page":897}]},{"type":"verse","number":[224],"number_text":"੨੨੪।","page":897,"lines":[{"gurmukhi":"ਅਤਿ ਸਿਆਮ ਸਰੂਪ ਕਰੂਪ ਤਨੰ। ਉਪਜੰ ਅਗ੍ਯਾਨ ਬਿਲੋਕਿ ਮਨੰ।","roman":"Ati siaam saroop karoop tanan | upjan agyaan biloki manan |","meaning_en":"","page":897},{"gurmukhi":"ਤਿਹ ਨਾਮ ਗਿਲਾਨਿ ਪ੍ਰਧਾਨ ਭਟੰ। ਰਣ ਮੋ ਨ ਮਹਾ ਹਠਿ ਹਾਰਿ ਹਟੰ। ੨੨੪।","roman":"Tih naam gilaani pradhaan bhatan | ran mo na mahaa hathi haari hatan | 224 |","meaning_en":"","page":897}]},{"type":"verse","number":[225],"number_text":"੨੨੫।","page":897,"lines":[{"gurmukhi":"ਅਤਿ ਅੰਗ ਸੁਰੰਗ ਸਨਾਹ ਸੁਭੰ। ਬਹੁ ਕਸਟ ਸਰੂਪ ਸੁ ਕਸਟ ਛੁਭੰ।","roman":"Ati ang surang sanaah subhan | bahu kasat saroop su kasat chhubhan |","meaning_en":"","page":897},{"gurmukhi":"ਅਤਿ ਬੀਰ ਅਧੀਰ ਨ ਭਯੋ ਕਬ ਹੀ। ਦਿਵ ਦੇਵ ਪਛਾਨਤ ਹੈ ਸਬ ਹੀ। ੨੨੫।","roman":"Ati beer adheer na bhayo kab hee | div dev pachhaanat hai sab hee | 225 |","meaning_en":"","page":897}]},{"type":"verse","number":[226],"number_text":"੨੨੬।","page":898,"lines":[{"gurmukhi":"ਭਟ ਕਰਮ ਬਿਕਰਮ ਜਬੈ ਧਰਿ ਹੈ। ਰਣ ਰੰਗ ਤੁਰੰਗਹਿ ਬਿਚਰਿ ਹੈ।","roman":"Bhat karam bikram jabai dhari hai | ran rang turanghi bichri hai |","meaning_en":"","page":898},{"gurmukhi":"ਤਬ ਬੀਰ ਸੁ ਧੀਰਹਿੰ ਕੋ ਧਰਿ ਹੈ। ਬਲ ਬਿਕ੍ਰਮ ਤੇਜ ਤਬੈ ਹਰਿ ਹੈ। ੨੨੬।","roman":"Tab beer su dheerhin ko dhari hai | bal bikram tej tabai hari hai | 226 |","meaning_en":"","page":898}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":898},{"type":"verse","number":[227],"number_text":"੨੨੭।","page":898,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਤਨ ਸੂਰਾ ਸੁ ਧਰਿ ਧੈ ਹੈ ਨ੍ਰਿਪ ਅਬਿਬੇਕ।","roman":"Ih bidhi tan sooraa su dhari dhai hai nrip abibek |","meaning_en":"","page":898},{"gurmukhi":"ਨ੍ਰਿਪ ਬਿਬੇਕ ਕੀ ਦਿਸਿ ਸੁਭਟ ਠਾਢ ਨ ਰਹਿ ਹੈ ਏਕ। ੨੨੭।","roman":"Nrip bibek kee disi subhat thaadh na rahi hai ek | 227 |","meaning_en":"","page":898}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ ਨਾਟਕ ਗ੍ਰੰਥੇ ਪਾਰਸ ਮਛਿੰਦ੍ਰ ਸੰਬਾਦੇ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਆਗਮਨ ਨਾਮ","roman":"Iti sree bachit naatak granthe paaras machhindr sanbaade nrip abibek aagman naam","meaning_en":"","page":898},{"gurmukhi":"ਸੁਭਟ ਬਰਨਨੰ ਨਾਮ ਧਿਆਇ ਸਮਾਪਤਮ ਸਤ ਸੁਭਮ ਸਤ।","roman":"Subhat barannan naam dhiaai samaaptam sat subham sat |","meaning_en":"","page":898}],"page":898}});
